window.EXPL={"공인노2024_33-39-2":{"f":"국가는 적정임금의 보장에 노력하여야 한다.","w":"헌법 제32조 제1항은 적정임금 보장에 노력할 의무를 국가에 지운다. 사용자에게 지운 의무가 아니다.","c":"상","v":1},"공인노2024_33-39-3":{"f":"전몰군경의 유가족은 법률이 정하는 바에 의하여 우선적으로 근로의 기회를 부여받는다.","w":"헌법 제32조 제6항에서 우선적으로 근로 기회를 받는 사람은 국가유공자·상이군경, 그리고 전몰군경의 유가족이다. 전몰군경은 이미 사망한 사람이므로 그 유가족이 대상이다.","c":"상","v":1},"공인노2024_33-39-4":{"f":"근로조건의 기준은 인간의 존엄성을 보장하도록 법률로 정한다.","w":"헌법 제32조 제3항에서 인간의 존엄성을 보장하도록 법률로 정하는 대상은 근로조건의 기준이다.","c":"상","v":1},"공인노2024_33-39-5":{"f":"여자의 근로는 고용ㆍ임금 및 근로조건에 있어서 부당한 차별을 받지 아니한다.","w":"고용·임금·근로조건에서 부당한 차별을 받지 않는다고 헌법 제32조 제4항이 정한 대상은 여자의 근로다. 연소자의 근로는 제5항에서 특별한 보호를 받는다고만 정한다.","c":"상","v":1},"공인노2026_35-08-2":{"f":"근로 관계 당사자는 「근로기준법」에서 정하는 기준을 이유로 근로조건을 낮출 수 없다.","w":"근로기준법 제3조는 이 법의 기준이 최저기준이므로 그 기준을 이유로 근로조건을 낮출 수 없다고 정한다.","c":"상","v":1},"공인노2024_33-03-4":{"f":"근로기준법상 사업은 그 사업의 종류를 한정하지 아니하고 영리사업이 아니어도 된다.","w":"판례는 근로기준법의 사업을 경제적·사회적 활동 단위로 보며, 영리를 목적으로 하는지는 묻지 않는다. 비영리 사업에도 근로기준법이 적용된다.","c":"상","v":1},"공인노2026_35-06-3":{"f":"상시 4명 이하의 근로자를 사용하는 사업 또는 사업장의 사용자는 근로자에게 「관공서의 공휴일에 관한 규정」상 일요일을 제외한 공휴일을 유급으로 보장할 의무가 없다.","w":"근로기준법 시행령 별표 1에 따라 공휴일 유급휴일(제55조 제2항)은 상시 4명 이하 사업장에 적용되지 않는다. 주휴일(제55조 제1항)은 4명 이하 사업장에도 적용된다.","c":"상","v":1},"공인노2024_33-02-2":{"f":"「근로기준법」 제6조에서 말하는 사회적 신분은 그 지위에 변동가능성이 없을 것까지 요구되지는 않는다.","w":"대법원 전원합의체 판결(2023)은 근로기준법 제6조의 사회적 신분이 반드시 선천적으로 고정된 것일 필요는 없고, 사회에서 장기간 점하는 지위로서 일정한 사회적 평가를 수반하면 된다고 보았다.","c":"중","v":1},"공인노2025_34-40-1":{"f":"근로자들의 집단적 동의를 받아 불리하게 변경된 취업규칙은 그보다 유리한 근로조건을 따로 정한 기존의 개별 근로계약부분에 우선하는 효력을 갖지 못한다.","w":"판례는 집단적 동의로 불리하게 바뀐 취업규칙이라도 근로자가 개별적으로 동의하지 않았다면 더 유리한 기존 근로계약이 우선한다고 본다(근로기준법 제97조 반대해석).","c":"상","v":1},"공인노2026_35-36-1":{"f":"「근로기준법」에서 정한 기준에 미달하는 근로조건을 단체협약으로 정한 경우 그 협약의 내용은 무효이다.","w":"근로기준법의 기준은 강행규정인 최저기준이어서 단체협약으로도 그보다 낮게 정할 수 없고, 미달하는 부분은 무효다. 신법 우선 원칙은 법령끼리 충돌할 때의 해석 원칙이라 여기에 쓰이지 않는다.","c":"상","v":1},"공인노2026_35-36-2":{"f":"고용노동부 고시는 행정기관 내부의 사무처리 준칙으로서 대외적으로 국민을 기속하지 않는다면 법원으로 인정되지 않는다.","w":"행정 내부의 사무처리 준칙에 그치는 고시나 지침은 국민과 법원을 구속하지 않으므로 노동법의 법원이 아니다. 법령의 위임을 받아 법령을 보충하는 고시만 대외적 효력을 가진다.","c":"상","v":1},"공인노2026_35-36-3":{"f":"국제노동기구(ILO)의 결사의 자유 및 단결권의 보호에 관한 협약(제87호)은 국내 노동법의 법원에 해당하나, 강제노동 철폐 협약(제105호)은 해당하지 않는다.","w":"우리나라는 2021년에 제87호·제98호·제29호를 비준했지만 강제노동 철폐 협약(제105호)은 비준하지 않았다. 헌법 제6조 제1항에 따라 국내법과 같은 효력을 갖는 것은 비준·공포된 조약뿐이다.","c":"상","v":1},"공인노2026_35-36-5":{"f":"「근로기준법」에서 정하는 기준에 미치지 못하는 근로조건을 정한 근로계약은 그 부분에 한정하여 무효로 한다.","w":"근로기준법 제15조 제1항은 기준에 미달하는 부분만 무효로 하고(일부무효), 무효가 된 부분은 같은 조 제2항에 따라 이 법의 기준으로 채운다.","c":"상","v":1},"공인노2017_26-15-1":{"f":"모든 국민은 근로의 권리를 가지며 근로의 의무를 진다.","w":"헌법 제32조 제1항은 근로의 권리를, 제2항은 모든 국민이 근로의 의무를 진다고 정한다.","c":"상","v":1},"공인노2019_28-10-3":{"f":"국가는 근로의 의무의 내용과 조건을 민주주의원칙에 따라 법률로 정하여야 한다.","w":"헌법 제32조 제2항이 민주주의원칙에 따라 법률로 정하도록 한 것은 근로의 의무의 내용과 조건이다.","c":"상","v":1},"공인노2022_31-25-4":{"f":"국가유공자ㆍ상이군경 및 전몰군경의 유가족은 법률이 정하는 바에 의하여 우선적으로 근로의 기회를 부여받는다.","w":"헌법 제32조 제6항은 이들에게 우선적으로 근로의 기회를 준다고 정한다. 근로의 의무를 먼저 이행하라는 규정이 아니다.","c":"상","v":1},"공인노2025_34-39-1":{"f":"근로의 권리에는 일할 환경에 관한 권리도 포함된다.","w":"헌법재판소는 근로의 권리에 일할 자리에 관한 권리뿐 아니라 건강한 작업환경, 정당한 보수, 합리적인 근로조건 등 일할 환경에 관한 권리도 들어 있다고 본다.","c":"상","v":1},"공인노2025_34-39-2":{"f":"모든 국민은 근로의 의무를 진다.","w":"헌법 제32조 제2항은 근로의 의무를 정하면서 그 내용과 조건을 민주주의원칙에 따라 법률로 정하게 한다. 그래서 근로의 의무는 국가가 일을 강제할 수 있는 법적 의무가 아니라 윤리적·도의적 의무로 이해된다.","c":"중","v":1},"공인노2025_34-39-4":{"f":"근로자는 국가에 대해 직접적인 직장존속보장청구권을 가지고 있지 않으므로 국가는 근로관계의 당연승계를 보장하는 입법을 반드시 하여야 할 헌법상의 의무가 없다.","w":"헌법재판소는 근로의 권리에서 국가에 대한 직접적인 직장존속보장청구권이 나오지 않으며, 영업양도 때 근로관계 당연승계를 보장하는 입법을 할 헌법상 의무도 없다고 보았다.","c":"상","v":1},"공인노2025_34-39-5":{"f":"여자의 근로와 연소자의 근로는 각각 특별한 보호를 받는다.","w":"헌법 제32조 제4항은 여자의 근로를, 제5항은 연소자의 근로를 따로 특별히 보호한다. 연소자이면서 여자인 경우로 한정하지 않는다.","c":"상","v":1},"공인노2026_35-01-2":{"f":"사용기간이 30일 미만인 일용근로자에 대하여는 근로자 명부를 작성하지 아니할 수 있다.","w":"근로기준법 시행령 제21조에 따라 근로자 명부를 작성하지 않아도 되는 일용근로자는 사용기간 30일 미만인 경우다.","c":"상","v":1},"공인노2025_34-03-4":{"f":"근로계약서의 보존기간은 근로관계가 끝난 날부터 기산한다.","w":"근로기준법 시행령 제22조 제2항은 근로계약서 보존기간(3년)을 근로관계가 끝난 날부터 센다고 정한다.","c":"상","v":1},"공인노2025_34-01-1":{"f":"단시간근로자의 1일 소정근로시간 수는 4주 동안의 소정근로시간을 그 기간의 통상 근로자의 총 소정근로일 수로 나눈 시간 수로 한다.","w":"근로기준법 시행령 별표 2는 단시간근로자의 4주 소정근로시간을 통상 근로자의 총 소정근로일 수로 나누어 1일 소정근로시간을 구하게 한다.","c":"상","v":1},"공인노2019_28-03-5":{"f":"미성년자의 근로계약은 미성년자의 동의를 얻더라도 친권자 또는 후견인이 대리할 수 없다.","w":"근로기준법 제67조 제1항은 친권자나 후견인이 미성년자의 근로계약을 대리할 수 없다고 정한다. 미성년자가 동의해도 마찬가지다.","c":"상","v":1},"공인노2024_33-04-2":{"f":"시용기간 중에는 사용자의 해약권이 유보되어 있더라도 그 기간 중에 확정적 근로관계는 존재한다.","w":"판례는 시용기간에도 이미 확정적 근로관계가 성립해 있고, 다만 사용자에게 해약권이 유보되어 있을 뿐이라고 본다.","c":"상","v":1},"공인노2019_28-04-1":{"f":"채용내정자의 해약권유보부 근로계약에도 근로기준법 제23조(해고 등의 제한)가 적용된다.","w":"판례는 채용내정으로 해약권이 유보된 근로계약이 성립한다고 보고, 채용내정 취소는 해고에 해당하므로 정당한 이유가 있어야 한다고 본다.","c":"상","v":1},"공인노2022_31-09-1":{"f":"통상임금에는 1개월 이내의 주기마다 정기적으로 지급되는 임금과 수당만이 포함되는 것은 아니다.","w":"판례는 1개월을 넘는 주기로 지급되더라도 정기적으로 지급되는 임금이면 통상임금에 들어갈 수 있다고 본다(정기상여금 등).","c":"상","v":1},"공인노2017_26-10-3":{"f":"근로자가 임금채권을 타인에게 양도한 경우에도 사용자는 임금채권의 양수인에게 임금을 지급할 수 없다.","w":"근로기준법 제43조의 직접불 원칙 때문에 임금채권 양수인도 사용자에게 직접 임금을 청구할 수 없고, 사용자는 근로자 본인에게 지급해야 한다(판례).","c":"상","v":1},"공인노2024_33-09-2":{"f":"명단 공개는 공공장소에 3년간 게시한다.","w":"근로기준법 시행령 제23조의3 제2항에 따라 체불사업주 명단은 관보, 인터넷 홈페이지, 관할 지방고용노동관서 게시판 등 공공장소에 3년간 게시한다.","c":"상","v":1},"공인노2025_34-12-1":{"f":"고정성을 통상임금의 개념적 징표에서 제외하였더라도 주휴수당은 통상임금에 속하지 않는다.","w":"주휴수당은 소정근로의 대가가 아니라 근로기준법 제55조에 따라 주휴일에 지급되는 수당이어서, 2024년 전원합의체가 고정성 요건을 뺀 뒤에도 통상임금에 들어가지 않는다.","c":"중","v":1},"공인노2024_33-01-2":{"f":"사용자는 연장근로에 대하여는 통상임금의 100분의 50 이상을 가산하여 근로자에게 지급하여야 한다.","w":"근로기준법 제56조 제1항은 연장근로 가산임금의 기준을 통상임금으로 정한다.","c":"상","v":1},"공인노2024_33-01-3":{"f":"평균임금의 산정기간 중에 출산전후휴가 기간이 있는 경우 그 기간은 산정기간에서 제외된다.","w":"근로기준법 시행령 제2조 제1항은 출산전후휴가 기간과 그 기간 중 받은 임금을 평균임금 산정기간과 임금 총액에서 각각 뺀다고 정한다.","c":"상","v":1},"공인노2024_33-01-4":{"f":"일용근로자의 평균임금은 고용노동부장관이 사업이나 직업에 따라 정하는 금액으로 한다.","w":"근로기준법 시행령 제3조는 일용근로자의 평균임금을 고용노동부장관이 사업이나 직업에 따라 정하는 금액으로 한다고 정한다. 최저임금위원회는 최저임금을 심의하는 기구다.","c":"상","v":1},"공인노2024_33-01-5":{"f":"평균임금이란 이를 산정하여야 할 사유가 발생한 날 이전 3개월 동안에 그 근로자에게 지급된 임금의 총액을 그 기간의 총일수로 나눈 금액을 말한다.","w":"근로기준법 제2조 제1항 제6호는 평균임금을 3개월간 임금 총액을 그 기간의 총일수(달력상 일수)로 나눈 금액으로 정한다.","c":"상","v":1},"공인노2025_34-13-5":{"f":"사용자의 귀책사유로 휴업하는 경우에 지급하는 휴업수당은 임금으로 볼 수 있다.","w":"휴업수당은 사용자의 귀책사유로 일하지 못한 기간에 근로기준법 제46조에 따라 지급하는 금품으로, 판례는 이를 임금으로 본다.","c":"중","v":1},"공인노2019_28-05-4":{"f":"근로자의 임금포기에 관한 약정에 대해서는 문언의 기재 내용에 따라 엄격하게 해석해야 하지만 임금포기를 한 경위나 목적 등 여러 사정을 반영하는 합목적적 해석을 배제할 것은 아니다.","w":"판례는 임금포기 약정을 엄격하게 해석하되, 포기의 경위와 목적 등 여러 사정을 반영한 합목적적 해석까지 막는 것은 아니라고 본다.","c":"상","v":1},"공인노2026_35-04-4":{"f":"사용자가 근로자의 임금 지급에 갈음하여 사용자가 제3자에 대하여 가지는 채권을 근로자에게 양도하기로 하는 약정은 원칙적으로 무효이다.","w":"판례는 임금 지급에 갈음하여 사용자의 제3자에 대한 채권을 근로자에게 양도하는 약정은 근로기준법 제43조 제1항에 어긋나 원칙적으로 무효라고 본다. 당사자가 그 무효를 알았더라면 '임금의 지급을 위하여' 양도하기를 원했으리라고 인정될 때에만 무효행위 전환으로 효력을 가진다.","c":"상","v":1},"공인노2019_28-08-4":{"f":"연차 유급휴가 규정을 적용하는 경우 육아휴직으로 휴업한 기간은 출근한 것으로 본다.","w":"근로기준법 제60조 제6항 제3호는 남녀고용평등법 제19조에 따른 육아휴직으로 휴업한 기간을 연차휴가 산정에서 출근한 것으로 본다. 이 호는 2017.11.28. 개정으로 들어와 2018.5.29.부터 시행되었다.","c":"상","v":1},"공인노2017_26-04-1":{"f":"3개월 이내 탄력적 근로시간제에서 특정한 주의 근로시간의 한도는 52시간이다.","w":"근로기준법 제51조 제2항은 3개월 이내 탄력적 근로시간제에서 특정한 주는 52시간, 특정한 날은 12시간을 넘을 수 없다고 정한다.","c":"상","v":1},"공인노2017_26-04-2":{"f":"사용자가 2주 이내의 탄력적 근로시간제를 시행하려면 취업규칙(취업규칙에 준하는 것을 포함한다)으로 정하여야 한다.","w":"2주 이내 탄력적 근로시간제는 취업규칙 등으로 정하면 된다(근로기준법 제51조 제1항). 근로자대표와 서면 합의가 필요한 것은 3개월 이내 탄력제다(같은 조 제2항).","c":"상","v":1},"공인노2017_26-04-4":{"f":"사용자가 근로자대표와 서면 합의로 정한 시간을 근로한 것으로 보는 재량근로의 대상 업무에 정보처리시스템의 설계 업무는 해당한다.","w":"근로기준법 시행령 제31조는 정보처리시스템의 설계 또는 분석 업무를 재량근로 대상 업무로 정한다.","c":"상","v":1},"공인노2017_26-04-5":{"f":"2주 이내의 탄력적 근로시간제를 실시하는 경우 특정한 날의 근로시간을 제한하는 명시 규정은 없다.","w":"근로기준법 제51조 제1항은 2주 이내 탄력제에서 특정한 주의 근로시간만 48시간으로 묶는다. 특정한 날 12시간 한도는 3개월 이내 탄력제(제51조 제2항)에 붙은 규정이다.","c":"상","v":1},"공인노2026_35-02-4":{"f":"사용자는 탄력적 근로시간제에 따라 근로자를 근로시킬 경우에는 임금 수준이 낮아지지 아니하도록 임금보전방안을 강구하여야 한다.","w":"임금보전방안 마련 의무는 탄력적 근로시간제에 붙은 것이다(근로기준법 제51조 제4항). 선택적 근로시간제(제52조)에는 이런 규정이 없다.","c":"상","v":1},"공인노2025_34-14-2":{"f":"근로자가 1년간 80퍼센트 미만 출근한 경우에도 1개월 개근 시 1일의 유급휴가를 부여받는다.","w":"근로기준법 제60조 제2항은 계속 근로 1년 미만이거나 1년간 80% 미만 출근한 근로자에게 1개월 개근 시 1일의 유급휴가를 주도록 한다.","c":"상","v":1},"공인노2026_35-05-4":{"f":"근로자가 연차유급휴가권을 취득한 후에 이를 사용하기 전 근로관계가 종료된 경우, 연차휴가수당을 청구할 권리는 그대로 유지된다.","w":"판례는 휴가를 쓰기 전에 퇴직 등으로 근로관계가 끝나도 이미 생긴 연차휴가에 대한 수당청구권은 남는다고 본다.","c":"상","v":1},"공인노2017_26-12-1":{"f":"사용자는 근로자대표와의 서면 합의에 따라 연장근로에 대하여 임금을 지급하는 대신에 휴가를 줄 수 있다.","w":"근로기준법 제57조의 보상휴가제는 근로자대표와의 서면 합의로 도입한다. 고용노동부장관의 승인은 요건이 아니다.","c":"상","v":1},"공인노2017_26-12-2":{"f":"사용자는 근로자에게 1주일에 평균 1회 이상의 유급휴일을 보장하여야 한다.","w":"근로기준법 제55조 제1항은 1주 평균 1회 이상의 유급휴일만 요구하고, 그날을 일요일로 정하지는 않는다.","c":"상","v":1},"공인노2017_26-12-3":{"f":"사용자가 고용노동부장관의 승인을 받은 경우 단속적(斷續的)으로 근로에 종사하는 자에게는 휴일에 관한 규정을 적용하지 아니한다.","w":"근로기준법 제63조 제3호에 따라 감시·단속적 근로자는 고용노동부장관의 승인을 받아야 근로시간·휴게·휴일 규정의 적용에서 빠진다.","c":"상","v":1},"공인노2017_26-12-5":{"f":"사용자는 8시간 이내의 휴일근로에 대하여는 통상임금의 100분의 50 이상을 가산하여 지급하여야 한다.","w":"근로기준법 제56조 제2항은 휴일근로 가산임금을 통상임금 기준으로 8시간 이내는 50% 이상, 8시간을 넘는 부분은 100% 이상으로 정한다.","c":"상","v":1},"공인노2022_31-07-1":{"f":"사용자는 근로자에게 근로시간이 8시간인 경우에는 1시간 이상의 휴게시간을 근로시간 도중에 주어야 한다.","w":"근로기준법 제54조 제1항은 근로시간 4시간이면 30분 이상, 8시간이면 1시간 이상의 휴게시간을 주도록 한다. 제63조에 해당하는 근로자에게는 휴게 규정이 적용되지 않으므로 모든 근로자도 아니다.","c":"상","v":1},"공인노2022_31-07-2":{"f":"사용자는 근로자에게 1주에 평균 1회 이상의 유급휴일을 보장해야 한다.","w":"근로기준법 제55조 제1항은 유급휴일을 1주 평균 1회 이상 주도록 한다.","c":"상","v":1},"공인노2022_31-07-3":{"f":"사용자는 근로자에게 대통령령으로 정하는 휴일을 유급으로 보장하여야 하나 근로자대표와 서면 합의를 한 경우 특정한 근로일로 대체할 수 있다.","w":"근로기준법 제55조 제2항 단서는 근로자대표와 서면 합의가 있으면 공휴일을 특정한 근로일로 대체할 수 있게 한다.","c":"상","v":1},"공인노2022_31-07-4":{"f":"사용자는 8시간을 초과한 휴일근로에 대하여는 통상임금의 100분의 100 이상을 가산하여 지급하여야 한다.","w":"연장근로 가산율은 통상임금의 50% 이상이다(근로기준법 제56조 제1항). 100% 이상은 8시간을 넘는 휴일근로에 적용된다(같은 조 제2항).","c":"상","v":1},"공인노2024_33-12-4":{"f":"사용자는 18세 이상의 여성을 오후 10시부터 오전 6시까지의 시간에 근로시키려면 그 근로자의 동의를 받아야 한다.","w":"18세 이상 여성의 야간근로는 근로기준법 제70조 제1항에 따라 본인 동의만 있으면 되고 시간 한도는 없다. 1일 2시간·1주 6시간·1년 150시간 한도는 산후 1년이 지나지 않은 여성의 시간외근로에 관한 제71조의 내용이다.","c":"상","v":1},"공인노2022_31-12-3":{"f":"연차 유급휴가 일수의 산정 시 근로자가 업무상의 질병으로 휴업한 기간은 출근한 것으로 본다.","w":"근로기준법 제60조 제6항 제1호는 업무상 부상·질병으로 휴업한 기간을 출근한 것으로 본다.","c":"상","v":1},"공인노2024_33-10-1":{"f":"사용자는 8시간을 초과한 휴일근로에 대하여는 통상임금의 100분의 100 이상을 가산하여 근로자에게 지급하여야 한다.","w":"근로기준법 제56조 제2항 제2호는 8시간을 넘는 휴일근로에 통상임금의 100% 이상을 더해 주도록 한다. 50%는 8시간 이내 휴일근로에 적용된다.","c":"상","v":1},"공인노2017_26-06-4":{"f":"징계처분에서 징계사유로 삼지 아니한 비위행위 사실도 징계양정의 참작자료로 삼을 수 있다.","w":"판례는 징계사유로 삼지 않은 비위행위라도 평소 소행, 근무성적, 징계사유 전후의 비위행위 등은 징계양정에서 참작할 수 있다고 본다.","c":"상","v":1},"공인노2019_28-12-2":{"f":"징계위원회에 무자격위원이 참여한 상태에서 징계처분이 이루어진 경우 그 위원을 제외하더라도 의결정족수가 충족된다고 하여 그 징계처분이 유효한 것은 아니다.","w":"판례는 무자격위원이 참여한 징계위원회의 의결은 그 위원을 빼고도 정족수가 채워지더라도 구성상 하자가 있어 무효라고 본다.","c":"상","v":1},"공인노2017_26-07-4":{"f":"사직의 의사표시는 특별한 사정이 없는 한 당해 근로계약을 종료시키는 취지의 해약고지로 볼 것이다.","w":"판례는 근로자의 사직 의사표시를 특별한 사정이 없으면 근로계약을 끝내는 해약고지로 본다. 그래서 사용자에게 도달한 뒤에는 사용자 동의 없이 철회할 수 없다.","c":"상","v":1},"공인노2025_34-09-5":{"f":"부당해고 구제신청에 관한 중앙노동위원회 명령의 취소를 구하는 소송에서 그 명령의 기초가 된 사실이 동일하다면 노동위원회에서 주장하지 아니한 사유도 행정소송에서 주장할 수 있다.","w":"판례는 재심판정 취소소송에서 처분의 기초 사실이 같은 범위라면 노동위원회 단계에서 내세우지 않은 사유도 소송에서 새로 주장할 수 있다고 본다.","c":"상","v":1},"공인노2024_33-06-4":{"f":"정부는 해고된 근로자에 대하여 생계안정, 재취업, 직업훈련 등 필요한 조치를 우선적으로 취하여야 한다.","w":"근로기준법 제25조 제2항은 경영상 해고된 근로자의 생계안정·재취업·직업훈련 조치를 우선적으로 취할 의무를 정부에 지운다. 사용자에게는 같은 조 제1항의 우선 재고용 노력 의무가 있다.","c":"상","v":1},"공인노2019_28-14-2":{"f":"근로자의 과반수로 조직된 노동조합이 있는 경우에는 사용자가 그 노동조합과의 협의 외에 근로자집단의 대표와 별도로 협의할 필요는 없다.","w":"근로기준법 제24조 제3항은 과반수 노동조합이 있으면 그 노동조합과 협의하도록 한다. 판례도 과반수 노조와 협의했다면 해고 대상 직원 집단 대표와 따로 협의하지 않았다고 해서 절차 위반이 아니라고 본다.","c":"상","v":1},"공인노2024_33-07-2":{"f":"영업양도에 의하여 근로계약관계가 포괄적으로 승계된 경우에는 승계 후의 퇴직금 규정이 승계 전의 퇴직금 규정보다 근로자에게 불리하다면 승계 전의 퇴직금 규정을 적용한다.","w":"판례는 근로관계가 그대로 승계되므로 근로자 집단의 동의 없이는 양수 회사의 불리한 퇴직금 규정을 승계 근로자에게 적용할 수 없다고 본다.","c":"상","v":1},"공인노2026_35-09-3":{"f":"근로자의 과반수로 조직된 노동조합이 없는 경우에 그 협의의 상대방이 형식적으로는 근로자 과반수의 대표로서의 자격을 명확히 갖추지 못하였더라도 실질적으로 근로자의 의사를 반영할 수 있는 대표자라고 볼 수 있는 사정이 있다면 절차적 요건을 충족하였다고 볼 수 있다.","w":"판례는 협의 상대방이 형식상 과반수 대표 자격을 완전히 갖추지 못했어도 실질적으로 근로자 의사를 반영할 수 있는 대표자라면 경영상 해고의 협의 요건을 채운 것으로 본다.","c":"상","v":1},"공인노2024_33-05-3":{"f":"사용자가 인사처분을 함에 있어 노동조합의 사전 동의를 얻도록 단체협약에 규정하는 것은 사용자의 인사권의 본질적 내용을 침해하는 것이 아니어서 유효하다.","w":"판례는 인사처분에 노동조합의 사전 동의를 받도록 한 단체협약 조항을 유효로 보고, 그 동의 없이 한 처분은 원칙적으로 무효라고 한다. 다만 노조가 동의권을 남용한 경우에는 동의 없이도 처분이 유효할 수 있다.","c":"상","v":1},"공인노2022_31-11-2":{"f":"취업규칙에 따라 소명기회를 부여하였다면 징계위원회가 그 개개의 혐의 사항에 대하여 구체적으로 질문하고 징계대상자가 이에 대하여 빠짐없이 진술하도록 조치하지 않았더라도 부당한 징계가 되는 것은 아니다.","w":"판례는 소명 기회를 주는 것으로 충분하고, 징계위원회가 혐의 사항마다 구체적으로 묻고 빠짐없이 진술하게 해야 하는 것은 아니라고 본다.","c":"상","v":1},"공인노2017_26-09-1":{"f":"노동위원회는 사용자에게 구제명령을 하는 때에는 사용자가 구제명령을 서면으로 통지받은 날부터 30일 이내의 이행기한을 정하여야 한다.","w":"근로기준법 시행령 제11조는 구제명령의 이행기한을 사용자가 구제명령을 서면으로 통지받은 날부터 30일 이내로 정하도록 한다. 기간은 60일이 아니고, 기산점도 구제명령을 한 날이 아니다.","c":"상","v":1},"공인노2025_34-02-1":{"f":"노동위원회는 천재ㆍ사변, 그 밖의 부득이한 사유가 발생하여 납부기한 내에 이행강제금을 납부하기 어려운 경우에는 그 사유가 없어진 날부터 15일 이내의 기간을 납부기한으로 할 수 있다.","w":"근로기준법 시행령 제12조 제2항은 이런 경우 납부기한을 사유가 없어진 날부터 15일 이내로 정할 수 있게 한다.","c":"상","v":1},"공인노2025_34-02-2":{"f":"노동위원회의 기각결정은 중앙노동위원회에 대한 재심 신청에 의하여 그 효력이 정지되지 아니한다.","w":"근로기준법 제32조는 구제명령, 기각결정, 재심판정 모두 재심 신청이나 행정소송 제기로 효력이 멈추지 않는다고 정한다.","c":"상","v":1},"공인노2025_34-02-4":{"f":"노동위원회는 법원의 확정판결에 따라 노동위원회의 구제명령이 취소되면 이행강제금의 부과ㆍ징수를 즉시 중지하고 이미 징수한 이행강제금은 반환하여야 한다.","w":"근로기준법 시행령 제15조 제1항은 구제명령이 재심판정이나 법원의 확정판결로 취소되면 부과·징수를 즉시 멈추고 이미 징수한 이행강제금을 돌려주도록 한다. 돌려줄 때는 납부한 날부터의 이자도 더한다(같은 조 제2항).","c":"상","v":1},"공인노2025_34-02-5":{"f":"노동위원회는 구제명령을 받은 자가 구제명령을 이행하면 새로운 이행강제금을 부과하지 아니하되, 구제명령을 이행하기 전에 이미 부과된 이행강제금은 징수하여야 한다.","w":"근로기준법 제33조 제6항은 명령을 이행하면 새 이행강제금은 부과하지 않지만 이행 전에 이미 부과된 것은 징수하도록 한다.","c":"상","v":1},"공인노2026_35-03-1":{"f":"사용자가 근로자에게 부당해고를 하면 근로자는 노동위원회에 부당해고 구제신청을 할 수 있다.","w":"근로기준법 제28조 제1항에 따라 부당해고 구제신청은 해고된 근로자 본인이 한다. 노동조합이 신청인이 되는 것은 노동조합법의 부당노동행위 구제신청이다.","c":"상","v":1},"공인노2017_26-01-4":{"f":"노동위원회는 법원의 확정판결에 따라 노동위원회의 구제명령이 취소되는 경우에는 이미 징수한 이행강제금을 반환하여야 한다.","w":"근로기준법 시행령 제15조에 따라 구제명령이 확정판결로 취소되면 이미 징수한 이행강제금을 돌려준다.","c":"상","v":1},"공인노2019_28-13-4":{"f":"중앙노동위원회의 재심판정에 대하여 사용자나 근로자는 재심판정서를 송달받은 날부터 15일 이내에 행정소송법의 규정에 따라 소(訴)를 제기할 수 있다.","w":"근로기준법 제31조 제2항은 재심판정에 대한 행정소송 제기기간을 재심판정서 송달일부터 15일 이내로 정한다.","c":"상","v":1},"공인노2022_31-10-1":{"f":"중앙노동위원회의 재심판정에 대하여 사용자나 근로자는 재심판정서를 송달받은 날부터 15일 이내에 「행정소송법」의 규정에 따라 소(訴)를 제기할 수 있다.","w":"근로기준법 제31조 제2항의 제소기간은 재심판정서를 송달받은 날부터 15일 이내다.","c":"상","v":1},"공인노2022_31-10-2":{"f":"노동위원회의 구제명령, 기각결정 또는 재심판정은 중앙노동위원회에 대한 재심 신청이나 행정소송 제기에 의하여 그 효력이 정지되지 아니한다.","w":"근로기준법 제32조는 재심 신청이나 행정소송을 제기해도 구제명령·기각결정·재심판정의 효력이 멈추지 않는다고 정한다.","c":"상","v":1},"공인노2022_31-10-3":{"f":"노동위원회는 부당해고에 대한 구제명령을 할 때에 근로자가 원직복직을 원하지 아니하면 원직복직을 명하는 대신 해고기간 동안 임금 상당액 이상의 금품을 근로자에게 지급하도록 명할 수 있다.","w":"근로기준법 제30조 제3항의 금전보상명령은 근로자가 원직복직을 원하지 않을 때 할 수 있는 것이다. 사용자의 의사로 정해지지 않고, 반드시 명해야 하는 것도 아니다.","c":"상","v":1},"공인노2022_31-10-4":{"f":"노동위원회가 이행강제금을 부과할 때에는 이행강제금의 액수, 부과 사유 등을 서면으로 통보하여야 한다.","w":"근로기준법 제33조 제3항은 이행강제금의 액수, 부과 사유, 납부기한, 수납기관 등을 적은 문서로 이행강제금을 부과하도록 한다.","c":"상","v":1},"공인노2025_34-07-2":{"f":"사용자는 기숙사규칙의 작성 또는 변경에 관하여 기숙사에 기숙하는 근로자의 과반수를 대표하는 자의 동의를 받아야 한다.","w":"근로기준법 제99조 제2항은 기숙사규칙의 작성·변경에 기숙 근로자 과반수를 대표하는 자의 동의를 받도록 한다.","c":"상","v":1},"공인노2025_34-08-5":{"f":"검사는 확정된 구제명령을 이행하지 않은 경우 노동위원회에 통보하여 고발을 요청할 수 있다.","w":"확정된 구제명령 불이행죄는 노동위원회의 고발이 있어야 공소를 제기할 수 있고, 검사는 노동위원회에 통보해 고발을 요청할 수 있다(근로기준법 제112조). 요청은 재량이지 의무가 아니다.","c":"상","v":1},"공인노2026_35-12-4":{"f":"사용자가 확정된 구제명령을 이행하지 않은 경우 검사는 노동위원회에 통보하여 고발을 요청할 수 있다.","w":"근로기준법 제112조 제2항에서 노동위원회에 고발을 요청할 수 있는 사람은 검사이고, 요청할 수 있다고 정할 뿐 의무로 정하지 않는다.","c":"상","v":1},"공인노2025_34-10-4":{"f":"근로감독관은 근로감독관을 그만 둔 경우에도 직무상 알게 된 비밀을 엄수하여야 한다.","w":"근로기준법 제103조는 근로감독관이 직무상 알게 된 비밀을 재직 중은 물론 그만둔 뒤에도 지키도록 하고, 기간 제한을 두지 않는다.","c":"상","v":1},"공인노2022_31-03-5":{"f":"「근로기준법」에 따른 현장조사, 서류의 제출 등의 수사는 근로감독관이 전담하여 수행하나, 근로감독관의 직무에 관한 범죄의 수사는 그러하지 아니하다.","w":"근로기준법 제105조는 이 법에 따른 현장조사·서류제출·심문 등의 수사를 근로감독관이 전담하게 하면서 근로감독관의 직무에 관한 범죄 수사는 예외로 둔다. 출제 당시 조문은 「검사와 근로감독관」이 전담한다고 했으나 2026.8.4. 개정으로 검사가 빠졌다.","c":"상","v":1},"공인노2026_35-11-5":{"f":"근로감독관에게 거짓 장부ㆍ서류를 제출한 자에게는 500만원 이하의 과태료를 부과한다.","w":"근로감독관의 현장조사·검진을 거부·방해하거나 거짓 장부·서류를 제출한 자는 근로기준법 제116조 제2항 제4호에 따라 500만원 이하의 과태료 대상이다. 벌금형이 아니다.","c":"상","v":1},"공인노2025_34-11-1":{"f":"사용자 또는 근로자는 직장에서의 지위 또는 관계 등의 우위를 이용하여 업무상 적정범위를 넘어 다른 근로자에게 신체적·정신적 고통을 주는 행위를 하여서는 아니 된다.","w":"근로기준법 제76조의2가 보호하는 피해자는 다른 근로자이고, 사용자는 들어가지 않는다. 또 업무상 적정범위를 넘은 행위여야 직장 내 괴롭힘이 된다.","c":"중","v":1},"공인노2025_34-11-2":{"f":"누구든지 직장 내 괴롭힘 발생 사실을 알게 된 경우 그 사실을 사용자에게 신고할 수 있다.","w":"근로기준법 제76조의3 제1항은 누구든지 신고할 수 있다고 정한다. 신고 의무를 지우지는 않는다.","c":"상","v":1},"공인노2025_34-11-3":{"f":"사용자는 조사기간 동안 피해근로자등을 보호하기 위하여 필요한 경우 해당 피해근로자등에 대하여 근무장소의 변경, 유급휴가 명령 등 적절한 조치를 하여야 한다.","w":"근로기준법 제76조의3 제3항은 조사기간 중 보호조치의 대상을 피해근로자등으로 정하고, 피해근로자등의 의사에 반하는 조치는 금지한다. 행위자 배치전환을 의무로 정한 규정은 없다.","c":"상","v":1},"공인노2025_34-11-5":{"f":"직장 내 괴롭힘 발생 사실을 조사한 사람은 조사와 관련된 내용을 사용자에게 보고할 수 있다.","w":"근로기준법 제76조의3 제7항은 조사한 사람 등에게 비밀유지 의무를 지우면서, 조사 내용을 사용자에게 보고하거나 관계 기관의 요청에 따라 정보를 제공하는 경우는 예외로 둔다.","c":"상","v":1},"공인노2022_31-02-1":{"f":"근로자에게 신체적ㆍ정신적 고통을 주는 행위 외에 근무환경을 악화시키는 행위도 직장 내 괴롭힘에 관한 규정으로 규율된다.","w":"근로기준법 제76조의2는 신체적·정신적 고통을 주는 행위와 근무환경을 악화시키는 행위를 모두 직장 내 괴롭힘으로 정한다.","c":"상","v":1},"공인노2022_31-02-2":{"f":"직장 내 괴롭힘의 발생 사실을 알게 된 경우 그 피해근로자의 동의가 없더라도 누구든지 그 사실을 사용자에게 신고할 수 있다.","w":"근로기준법 제76조의3 제1항은 누구든지 신고할 수 있다고 정하고, 피해근로자의 동의를 요건으로 두지 않는다.","c":"상","v":1},"공인노2022_31-02-3":{"f":"사용자는 직장 내 괴롭힘 사실을 인지한 경우 그 신고의 접수가 없더라도 사실 확인을 위한 조사를 실시하여야 한다.","w":"근로기준법 제76조의3 제2항은 신고를 접수한 경우뿐 아니라 사용자가 발생 사실을 인지한 경우에도 지체 없이 조사하도록 한다.","c":"상","v":1},"공인노2022_31-02-4":{"f":"사용자는 조사 결과 직장 내 괴롭힘 발생 사실이 확인된 때에는 피해근로자가 요청하면 근무장소의 변경, 배치전환 등 적절한 조치를 하여야 한다.","w":"근로기준법 제76조의3 제4항은 괴롭힘이 확인된 뒤 피해근로자의 근무장소 변경·배치전환·유급휴가 명령 등을 피해근로자가 요청할 때 하도록 정한다.","c":"상","v":1},"공인노2019_28-09-2":{"f":"취업규칙 작성 시 과반수 노동조합이 있는 경우 사용자는 그 노동조합의 의견을 들어야 한다.","w":"근로기준법 제94조 제1항은 과반수 노동조합이 있으면 그 노동조합의 의견을, 없으면 근로자 과반수의 의견을 듣도록 한다. 조합원 회의 방식으로 따로 의견을 들을 필요는 없다.","c":"상","v":1},"공인노2022_31-08-3":{"f":"취업규칙에서 근로자에 대하여 감급(減給)의 제재를 정할 경우에 그 감액은 1회의 금액이 평균임금의 1일분의 2분의 1을, 총액이 1임금지급기의 임금 총액의 10분의 1을 초과하지 못한다.","w":"근로기준법 제95조는 감급 1회 금액을 평균임금 1일분의 2분의 1, 총액을 1임금지급기 임금 총액의 10분의 1까지로 묶는다.","c":"상","v":1},"공인노2024_33-15-3":{"f":"권리남용금지 원칙의 적용은 당사자의 주장이 없더라도 가능하므로, 집단적 동의권의 남용에 해당하는지에 대하여는 법원이 직권으로 판단할 수 있다.","w":"대법원 전원합의체(2023)는 권리남용금지 원칙은 당사자가 주장하지 않아도 법원이 직권으로 판단할 수 있으므로 집단적 동의권 남용 여부도 직권으로 판단할 수 있다고 했다.","c":"상","v":1},"공인노2024_33-16-2":{"f":"근로관계 종료 후의 권리·의무에 관한 사항이라고 하더라도 사용자와 근로자 사이에 존속하는 근로관계와 직접 관련되는 것으로서 근로자의 대우에 관하여 정한 사항이라면 취업규칙에서 정한 근로조건에 해당한다.","w":"판례는 퇴직 후의 권리·의무라도 존속 중인 근로관계와 직접 관련된 근로자 대우에 관한 사항이면 취업규칙의 근로조건에 들어간다고 본다.","c":"상","v":1},"공인노2017_26-13-2":{"f":"사용자는 18세 미만자의 동의가 있고 고용노동부장관의 인가를 받으면 오후 10시부터 오전 6시까지의 시간에 18세 미만자를 근로시킬 수 있다.","w":"근로기준법 제70조 제2항 제1호는 18세 미만자의 야간근로에 본인 동의와 고용노동부장관의 인가를 모두 요구한다.","c":"상","v":1},"공인노2026_35-14-5":{"f":"미성년자는 원칙적으로 법정대리인에 의하여서만 소송행위를 할 수 있으나 미성년자 자신의 노무제공에 따른 임금의 재판상 청구는 미성년자가 독자적으로 할 수 있다.","w":"근로기준법 제68조는 미성년자가 독자적으로 임금을 청구할 수 있다고 정하고, 판례는 이를 근거로 미성년자가 법정대리인 없이 임금 청구 소송을 낼 수 있다고 본다.","c":"상","v":1},"공인노2025_34-06-1":{"f":"사용자는 18세 이상의 임신 중인 여성을 휴일에 근로시키려면 그 근로자의 명시적인 청구가 있고 고용노동부장관의 인가를 받아야 한다.","w":"근로기준법 제70조 제2항 제3호는 임신 중인 여성의 야간·휴일근로를 본인이 명시적으로 청구하고 고용노동부장관의 인가를 받은 경우에만 허용한다. 동의로 족한 것은 산후 1년이 지나지 않은 여성이다.","c":"상","v":1},"공인노2026_35-17-2":{"f":"임신 중의 여성이 명시적으로 청구하는 경우, 사용자는 그 사업 또는 사업장의 근로자대표와 성실하게 협의를 하고 고용노동부장관의 인가를 받아 그 여성을 오후 10시부터 오전 6시까지의 시간에 근로시킬 수 있다.","w":"근로기준법 제70조 제3항은 고용노동부장관의 인가를 받기 전에 근로자대표와 성실하게 협의하도록 한다. 협의와 인가 둘 다 거쳐야 하며 어느 하나로 갈음할 수 없다.","c":"상","v":1},"공인노2025_34-04-4":{"f":"사용자가 취직인허증을 잃어버린 경우에는 지체 없이 재교부 신청을 하여야 한다.","w":"근로기준법 시행령 제39조는 취직인허증이 못 쓰게 되거나 분실된 경우 사용자 또는 15세 미만인 자가 지체 없이 재교부를 신청하도록 할 뿐, 15세 미만인 자의 동의를 요건으로 두지 않는다.","c":"상","v":1},"공인노2022_31-06-2":{"f":"사용자는 18세 미만인 사람에 대하여는 그 연령을 증명하는 가족관계기록사항에 관한 증명서와 친권자나 후견인의 동의서를 사업장에 갖추어 두어야 한다.","w":"근로기준법 제66조는 연령 증명서와 친권자·후견인의 동의서를 모두 갖추어 두도록 한다. 둘 중 하나로는 부족하다.","c":"상","v":1},"공인노2024_33-14-1":{"f":"사용자는 임신 중인 여성 근로자가 1일 소정근로시간을 유지하면서 업무의 시작 및 종료 시각의 변경을 신청하는 경우 이를 허용하여야 한다.","w":"근로기준법 제74조 제9항의 업무 시작·종료 시각 변경 신청권은 임신 중인 여성 근로자에게 주어진다. 산후 1년이 지나지 않은 여성에게 주어진 권리가 아니다.","c":"상","v":1},"공인노2026_35-15-3":{"f":"사용자는 임신 중의 여성 근로자에게 시간외근로를 하게 하여서는 아니 되며, 그 근로자의 요구가 있는 경우에는 쉬운 종류의 근로로 전환하여야 한다.","w":"근로기준법 제74조 제5항은 임신 중 여성의 시간외근로를 본인이 요구해도 금지한다. 요구가 있으면 쉬운 종류의 근로로 바꿔 주어야 한다.","c":"상","v":1},"공인노2019_28-21-3":{"f":"사용자는 최저임금법에 따른 최저임금을 이유로 종전의 임금수준을 낮추어서는 아니 된다.","w":"최저임금법 제6조 제2항은 최저임금을 이유로 종전 임금수준을 낮추는 것을 금지한다.","c":"상","v":1},"공인노2017_26-21-1":{"f":"1년 미만의 기간을 정하여 근로계약을 체결한 근로자에 대하여는 고용노동부장관에 의해 고시된 최저임금액보다 적은 최저임금액을 정할 수 없다.","w":"최저임금법 제5조 제2항에 따라 감액할 수 있는 근로자는 1년 이상의 기간을 정해 근로계약을 맺고 수습을 시작한 날부터 3개월 이내인 사람이며(단순노무업무 종사자 제외), 감액 한도는 최저임금액의 100분의 10이다.","c":"상","v":1},"공인노2022_31-19-4":{"f":"최저임금액은 시간ㆍ일(日)ㆍ주(週) 또는 월(月)을 단위로 하여 정한다.","w":"최저임금법 제5조 제1항이 정한 단위는 시간·일·주·월이며 연 단위는 없다. 일·주·월로 정할 때는 시간급으로도 표시해야 한다.","c":"상","v":1},"공인노2026_35-28-2":{"f":"최저임금위원회의 전문위원회는 근로자위원, 사용자위원 및 공익위원 각 5명 이내의 같은 수로 구성한다.","w":"최저임금법 제19조에 따라 전문위원회는 근로자위원·사용자위원·공익위원 각 5명 이내의 같은 수로 구성한다.","c":"상","v":1},"공인노2026_35-28-3":{"f":"고용노동부장관은 근로자의 생계비와 임금실태 등을 매년 조사하여야 한다.","w":"최저임금법 제23조는 고용노동부장관이 근로자의 생계비와 임금실태 등을 매년 조사하도록 한다.","c":"상","v":1},"공인노2026_35-28-4":{"f":"최저임금위원회에는 관계 행정기관의 공무원 중에서 3명 이내의 특별위원을 둘 수 있다.","w":"최저임금법 제16조 제1항은 관계 행정기관 공무원 중에서 3명 이내의 특별위원을 둘 수 있게 한다.","c":"상","v":1},"공인노2026_35-28-5":{"f":"최저임금위원회 위원의 임기는 3년으로 하되, 연임할 수 있다.","w":"최저임금법 제14조 제3항은 위원 임기를 3년으로 하고 연임을 허용한다.","c":"상","v":1},"공인노2025_34-30-2":{"f":"사용자는 최저임금의 내용을 최저임금의 효력발생일 전날까지 근로자에게 주지시켜야 한다.","w":"최저임금법 시행령 제11조는 사용자가 최저임금의 효력발생일 전날까지 근로자에게 알리도록 한다. 8월 5일은 고용노동부장관이 최저임금을 결정·고시하는 기한이다.","c":"상","v":1},"공인노2026_35-27-5":{"f":"정신 또는 신체의 장애가 업무 수행에 직접적으로 현저한 지장을 주는 것이 명백하다고 인정되는 사람에 대해서는 고용노동부장관의 인가를 받은 경우에 사용자가 최저임금의 적용을 제외할 수 있다.","w":"최저임금법 제7조는 장애로 근로능력이 현저히 낮은 사람이라도 사용자가 고용노동부장관의 인가를 받아야 최저임금 적용에서 제외할 수 있게 한다.","c":"상","v":1},"공인노2024_33-31-2":{"f":"위원회에 2명의 상임위원을 두며, 상임위원은 공익위원이 된다.","w":"최저임금법 제14조 제2항에 따라 상임위원 2명은 공익위원이 된다.","c":"상","v":1},"공인노2025_34-31-2":{"f":"최저임금위원회의 회의는 재적위원 3분의 1 이상이 소집을 요구하는 경우에 위원장이 소집한다.","w":"최저임금법 제17조에 따라 위원장은 고용노동부장관이 요구하거나, 재적위원 3분의 1 이상이 요구하거나, 위원장이 필요하다고 인정할 때 회의를 소집한다. 공익위원만의 요구로 정한 규정은 없다.","c":"상","v":1},"공인노2025_34-31-3":{"f":"최저임금을 심의하기 위하여 고용노동부에 최저임금위원회를 둔다.","w":"최저임금법 제12조는 최저임금위원회를 고용노동부에 둔다고 정한다.","c":"상","v":1},"공인노2025_34-31-4":{"f":"사무국에는 최저임금의 심의 등에 필요한 전문적인 사항을 조사ㆍ연구하게 하기 위하여 3명 이내의 연구위원을 둘 수 있다.","w":"최저임금법 제20조에 따라 최저임금위원회 사무국에 둘 수 있는 연구위원은 3명 이내다.","c":"상","v":1},"공인노2025_34-31-5":{"f":"최저임금위원회는 근로자위원, 사용자위원, 공익위원 각 9명으로 구성한다.","w":"최저임금법 제14조 제1항은 근로자위원·사용자위원·공익위원을 각 9명, 모두 27명으로 정한다.","c":"상","v":1},"공인노2024_33-30-5":{"f":"사용자를 대표하는 자는 고시된 최저임금안에 대하여 이의가 있으면 고시된 날부터 10일 이내에 고용노동부장관에게 이의를 제기할 수 있다.","w":"최저임금법 제9조 제2항과 시행령에 따라 근로자·사용자 대표자는 최저임금안 고시일부터 10일 이내에 이의를 제기할 수 있다.","c":"상","v":1},"공인노2019_28-23-5":{"f":"퇴직금제도를 설정하려는 사용자는 계속근로기간 1년에 대하여 30일분 이상의 평균임금을 퇴직금으로 퇴직 근로자에게 지급할 수 있는 제도를 설정하여야 한다.","w":"근로자퇴직급여 보장법 제8조 제1항은 퇴직금을 계속근로기간 1년에 30일분 이상의 평균임금으로 정한다.","c":"상","v":1},"공인노2026_35-29-3":{"f":"상시 300명 이상의 근로자를 사용하는 사업의 사용자는 퇴직연금제도 적립금의 합리적인 운용을 위하여 대통령령으로 정하는 바에 따라 적립금운용위원회를 구성하여야 한다.","w":"근로자퇴직급여 보장법 제18조의2 제1항은 적립금운용위원회 구성 의무를 상시 300명 이상의 근로자를 사용하는 사업의 사용자에게 지운다.","c":"상","v":1},"공인노2017_26-22-5":{"f":"확정급여형퇴직연금제도의 경우 55세 이상으로서 가입기간이 10년 이상인 가입자에게 연금으로 지급하되 연금의 지급기간은 5년 이상이어야 한다.","w":"근로자퇴직급여 보장법 제17조 제1항에 따라 확정급여형 연금은 55세 이상·가입기간 10년 이상인 가입자에게 지급하고, 지급기간은 5년 이상이어야 한다.","c":"상","v":1},"공인노2022_31-20-5":{"f":"퇴직연금사업자는 매년 1회 이상 적립금액 및 운용수익률 등을 고용노동부령으로 정하는 바에 따라 가입자에게 알려야 한다.","w":"근로자퇴직급여 보장법 제18조는 퇴직연금사업자가 적립금액과 운용수익률 등을 매년 1회 이상 가입자에게 알리도록 한다.","c":"상","v":1},"공인노2026_35-30-1":{"f":"중소기업퇴직연금기금제도는 근로복지공단에서 운영한다.","w":"근로자퇴직급여 보장법 제23조의2 제1항에 따라 중소기업퇴직연금기금제도는 근로복지공단이 운영한다.","c":"상","v":1},"공인노2024_33-32-3":{"f":"사용자가 퇴직급여제도를 다른 종류의 퇴직급여제도로 변경하려는 경우에는 근로자의 과반수를 대표하는 자의 동의를 받아야 한다.","w":"근로자퇴직급여 보장법 제4조 제3항은 퇴직급여제도를 설정하거나 다른 종류로 바꿀 때 근로자 과반수 노동조합, 없으면 근로자 과반수의 동의를 받도록 한다. 협의로는 부족하다.","c":"상","v":1},"공인노2025_34-33-2":{"f":"확정급여형퇴직연금제도의 설정 전에 해당 사업에서 제공한 근로기간에 대하여도 가입기간으로 할 수 있고, 이 경우 퇴직금을 미리 정산한 기간은 제외한다.","w":"근로자퇴직급여 보장법 제14조 제2항은 제도 설정 전의 근로기간도 가입기간에 넣을 수 있게 하고, 퇴직금 중간정산을 한 기간만 뺀다.","c":"상","v":1},"공인노2017_26-18-5":{"f":"사업주는 근로자가 배우자의 출산을 이유로 휴가를 고지하는 경우 20일의 유급휴가를 주어야 하며, 이 휴가는 배우자가 출산한 날부터 120일이 지나면 사용할 수 없다.","w":"현행 남녀고용평등법 제18조의2는 배우자 출산전후휴가를 20일 유급으로 하고, 배우자 출산예정일 50일 전부터 출산일 뒤 120일까지 쓰게 한다. 출제 당시(2017) 법은 5일 범위에서 3일 이상을 주고 최초 3일만 유급이었으며, 출산한 날부터 30일이 지나면 청구할 수 없었다.","c":"상","v":1},"공인노2022_31-18-1":{"f":"이 법과 관련한 분쟁해결에서 입증책임은 사업주가 부담한다.","w":"남녀고용평등법 제30조는 이 법과 관련한 분쟁에서 입증책임을 사업주에게 지운다.","c":"상","v":1},"공인노2024_33-23-1":{"f":"고용노동부장관은 사업장의 남녀고용평등 이행을 촉진하기 위하여 그 사업장 소속 근로자 중 노사가 추천하는 사람을 명예고용평등감독관으로 위촉할 수 있다.","w":"남녀고용평등법 제24조 제1항에서 명예고용평등감독관을 위촉하는 사람은 고용노동부장관이고, 위촉은 재량이다. 추천하는 쪽도 노사협의회가 아니라 노사다.","c":"상","v":1},"공인노2024_33-25-3":{"f":"육아기 근로시간 단축을 허용하는 경우 단축 후 근로시간은 주당 15시간 이상이어야 하고 35시간을 넘어서는 아니 된다.","w":"남녀고용평등법 제19조의2 제3항은 육아기 근로시간 단축 후 근로시간을 주 15시간 이상 35시간 이하로 정한다.","c":"상","v":1},"공인노2025_34-27-3":{"f":"상시 4명 이하의 근로자를 사용하는 사업 또는 사업장에 대하여도 이 법이 적용된다.","w":"남녀고용평등법은 근로자를 사용하는 모든 사업에 적용되고(제3조 제1항), 시행령 제2조가 법 전부의 적용을 빼는 것은 동거하는 친족만으로 이루어진 사업과 가사사용인뿐이다. 상시 5명 미만 사업에 일부 규정을 적용하지 않던 시행령 제2조 제2항은 2018.5.28. 삭제되었다.","c":"상","v":1},"공인노2025_34-28-4":{"f":"사업주는 휴직개시예정일의 전날까지 해당 사업에서 계속 근로한 기간이 6개월 미만인 근로자가 육아휴직을 신청하는 경우에 이를 허용하지 아니할 수 있다.","w":"남녀고용평등법 시행령 제10조는 계속 근로기간 6개월 미만인 근로자를 육아휴직을 허용하지 않아도 되는 경우로 정한다.","c":"상","v":1},"공인노2025_34-29-2":{"f":"직장 내 성희롱 행위를 한 사람에 대하여 징계 등 필요한 조치를 하지 않은 경우 피해근로자는 노동위원회에 차별적 처우등의 시정신청을 할 수 없다.","w":"남녀고용평등법 제26조 제1항의 시정신청 대상은 고용상 성차별, 성희롱 피해근로자 보호조치(제14조 제4항) 미이행, 피해근로자·신고자에 대한 불리한 처우, 고객 성희롱 관련 조치 미이행·불이익 조치다. 행위자 징계 등 조치(제14조 제5항)를 하지 않은 것은 시정신청 대상이 아니고 제39조 제3항의 과태료 대상이다.","c":"상","v":1},"공인노2026_35-32-1":{"f":"“근로자”란 사업주에게 고용된 사람과 취업할 의사를 가진 사람을 말한다.","w":"남녀고용평등법 제2조 제4호는 근로자에 사업주에게 고용된 사람뿐 아니라 취업할 의사를 가진 사람도 넣는다.","c":"상","v":1},"공인노2019_28-17-3":{"f":"가족돌봄휴직 기간은 연간 최장 90일로 하며, 이를 나누어 사용할 수 있다.","w":"남녀고용평등법 제22조의2 제4항은 가족돌봄휴직을 연간 최장 90일로 하고 나누어 쓸 수 있게 한다(1회 30일 이상).","c":"상","v":1},"공인노2019_28-20-5":{"f":"시정신청을 한 근로자는 사용자가 확정된 시정명령을 이행하지 아니하는 경우 이를 고용노동부장관에게 신고할 수 있다.","w":"기간제법 제15조 제2항은 확정된 시정명령을 사용자가 이행하지 않을 때 시정신청을 한 근로자가 고용노동부장관에게 신고할 수 있게 한다.","c":"상","v":1},"공인노2022_31-15-1":{"f":"상시 5인 이상의 동거의 친족만을 사용하는 사업 또는 사업장에는 적용되지 아니한다.","w":"기간제법 제3조 제1항 단서는 동거 친족만 사용하는 사업과 가사사용인을 적용 대상에서 뺀다. 근로자 수와 관계없다.","c":"상","v":1},"공인노2022_31-15-3":{"f":"단시간근로자의 초과근로에 대하여 사용자는 통상임금의 100분의 50 이상을 가산하여 지급하여야 한다.","w":"기간제법 제6조 제3항은 단시간근로자의 초과근로에 통상임금의 50% 이상을 더해 주도록 한다.","c":"상","v":1},"공인노2022_31-15-4":{"f":"사용자는 단시간근로자와 근로계약을 체결할 때 근로일별 근로시간을 서면으로 명시하여야 한다.","w":"기간제법 제17조 제6호는 단시간근로자의 근로일과 근로일별 근로시간을 서면 명시 사항으로 정한다.","c":"상","v":1},"공인노2022_31-15-5":{"f":"사용자는 통상근로자를 채용하고자 하는 경우에는 해당 사업 또는 사업장의 동종 또는 유사한 업무에 종사하는 단시간근로자를 우선적으로 고용하도록 노력하여야 한다.","w":"기간제법 제7조 제1항은 통상근로자를 채용할 때 동종·유사 업무의 단시간근로자를 우선 고용하도록 노력할 의무만 정한다.","c":"상","v":1},"공인노2024_33-21-3":{"f":"기간제근로자는 계속되는 차별적 처우를 받은 경우 차별적 처우의 종료일부터 6개월이 지난 때에는 노동위원회에 그 시정을 신청할 수 없다.","w":"기간제법 제9조 제1항은 차별적 처우가 있은 날(계속되는 경우 종료일)부터 6개월 안에 시정을 신청하도록 한다.","c":"상","v":1},"공인노2025_34-20-1":{"f":"노동위원회는 차별적 처우의 시정신청에 따른 심문의 과정에서 직권으로 조정절차를 개시할 수 있다.","w":"기간제법 제11조 제1항은 관계당사자 쌍방이나 일방의 신청 또는 직권으로 조정절차를 시작할 수 있게 한다.","c":"상","v":1},"공인노2025_34-20-3":{"f":"노동위원회는 특별한 사유가 없으면 조정절차를 개시한 때부터 60일 이내에 조정안을 제시하여야 한다.","w":"기간제법 제11조 제4항은 특별한 사유가 없으면 조정절차를 개시한 때부터 60일 이내에 조정안을 제시하도록 한다.","c":"상","v":1},"공인노2025_34-20-4":{"f":"중재결정서에는 중재에 관여한 위원전원이 서명ㆍ날인하여야 한다.","w":"관계당사자와 관여 위원 전원이 서명·날인하는 것은 조정조서다. 중재결정서에는 중재에 관여한 위원 전원만 서명·날인한다(기간제법 제11조 제6항).","c":"상","v":1},"공인노2025_34-20-5":{"f":"조정의 내용에는 적절한 배상 등이 포함될 수 있다.","w":"기간제법 제13조 제1항은 조정·중재결정과 시정명령의 내용에 차별행위 중지, 근로조건 개선과 함께 적절한 배상 등을 넣을 수 있게 한다.","c":"상","v":1},"공인노2025_34-22-1":{"f":"근로조건을 서면으로 명시하지 않는 경우 500만원 이하의 과태료를 부과한다.","w":"기간제법 제17조가 사용자에게 지우는 의무는 근로조건의 서면 명시이고, 제24조 제2항 제2호의 500만원 이하 과태료도 근로조건을 서면으로 명시하지 않은 경우에 부과한다. 서면 교부 의무는 기간제법에 없다.","c":"상","v":1},"공인노2017_26-19-2":{"f":"근로자파견대상업무에 해당하지 않는 업무에 파견근로자를 사용하는 경우 사용사업주는 해당 파견근로자를 직접 고용하여야 한다.","w":"파견법 제6조의2 제1항은 이런 경우 사용사업주에게 직접고용 의무를 지운다. 2006년 개정 전의 고용간주 규정은 고용의무 규정으로 바뀌었다.","c":"상","v":1},"공인노2017_26-19-3":{"f":"근로기준법에 따라 사용사업주가 파견근로자에게 유급휴일을 주는 경우 그 휴일에 대하여 유급으로 지급되는 임금은 파견사업주가 지급하여야 한다.","w":"파견법 제34조 제3항은 사용사업주가 근로기준법에 따라 유급휴일이나 유급휴가를 주더라도 그에 대한 임금은 파견사업주가 지급하도록 한다.","c":"상","v":1},"공인노2017_26-19-4":{"f":"파견사업주는 근로자대표의 동의가 있더라도 쟁의행위 중인 사업장에 그 쟁의행위로 중단된 업무의 수행을 위하여 근로자를 파견할 수 없다.","w":"파견법 제16조 제1항은 쟁의행위로 중단된 업무에 근로자를 파견하는 것을 예외 없이 금지한다.","c":"상","v":1},"공인노2017_26-19-5":{"f":"사용사업주는 파견근로자를 사용하고 있는 업무에 근로자를 직접 고용하려면 그 파견근로자를 우선적으로 고용하도록 노력하여야 한다.","w":"파견법 제6조의2 제4항은 우선 고용을 노력의무로 정한다.","c":"상","v":1},"공인노2022_31-14-3":{"f":"파견사업주는 파견근로자의 적절한 파견근로를 위하여 파견사업관리책임자를 선임하여야 한다.","w":"파견사업주가 선임하는 것은 파견사업관리책임자(파견법 제28조)이고, 사용사업관리책임자는 사용사업주가 선임한다(제32조).","c":"상","v":1},"공인노2024_33-19-5":{"f":"근로자파견사업 갱신허가의 유효기간은 그 갱신 전의 허가의 유효기간이 끝나는 날의 다음 날부터 기산하여 3년으로 한다.","w":"파견법 제10조 제3항은 갱신허가의 유효기간을 갱신 전 허가의 유효기간이 끝나는 날의 다음 날부터 3년으로 정한다.","c":"상","v":1},"공인노2025_34-18-5":{"f":"사용사업주가 파견근로자에게 유급휴일을 주는 경우 그 휴일에 대하여 유급으로 지급되는 임금은 파견사업주가 지급하여야 한다.","w":"파견법 제34조 제3항에 따라 유급휴일·휴가는 사용사업주가 주더라도 그 임금은 파견사업주가 지급한다.","c":"상","v":1},"공인노2025_34-19-3":{"f":"파견사업주는 그가 고용한 근로자 중 파견근로자로 고용하지 아니한 사람을 근로자파견의 대상으로 하려는 경우에는 미리 그 취지를 서면으로 알리고 그의 동의를 받아야 한다.","w":"파견법 제24조 제2항은 파견근로자로 고용하지 않은 사람을 파견하려면 미리 서면으로 알리고 동의를 받도록 한다.","c":"상","v":1},"공인노2026_35-22-5":{"f":"파견근로자가 파견사업주에게 근로자파견의 대가에 관하여 그 내역의 제시를 요구하였을 경우 파견사업주는 지체 없이 그 내역을 서면으로 제시하여야 한다.","w":"파견법 제26조에 따라 파견대가 내역 제시를 요구받는 상대방과 제시 의무자는 모두 파견사업주다.","c":"상","v":1},"공인노2026_35-23-4":{"f":"파견사업주는 근로자파견사업을 폐지하였을 때에는 고용노동부장관에게 신고하여야 한다.","w":"파견법 제11조 제1항은 근로자파견사업을 폐지하면 고용노동부장관에게 신고하도록 하고, 신고일부터 허가의 효력이 없어진다(같은 조 제2항). 허가가 필요한 것은 사업을 시작할 때다.","c":"상","v":1},"공인노2019_28-15-1":{"f":"산업안전보건법은 국가ㆍ지방자치단체 및 공기업에도 적용한다.","w":"산업안전보건법 제3조는 모든 사업에 적용한다고 정하고 국가·지방자치단체·공기업을 빼지 않는다. 대통령령으로 정한 일부 사업에만 전부나 일부가 적용되지 않는다.","c":"상","v":1},"공인노2024_33-27-2":{"f":"“안전보건진단”이란 산업재해를 예방하기 위하여 잠재적 위험성을 발견하고 그 개선 대책을 수립할 목적으로 조사ㆍ평가하는 것을 말한다.","w":"이 정의는 안전보건진단이다(산업안전보건법 제2조 제12호). 작업환경측정은 유해인자 측정계획을 세운 뒤 시료를 채취해 분석·평가하는 것이다(같은 조 제13호).","c":"상","v":1},"공인노2026_35-20-4":{"f":"고용노동부장관은 같은 유해인자에 노출되는 근로자들에게 유사한 질병의 증상이 발생한 경우에는 사업주에게 임시건강진단의 실시를 명할 수 있다.","w":"산업안전보건법 제131조 제1항에서 임시건강진단을 명하는 주체는 고용노동부장관이다. 산업보건의는 사업주에게 보건 사항을 조언하는 사람이라 명령 권한이 없다.","c":"상","v":1},"공인노2017_26-16-5":{"f":"안전ㆍ보건상 유해하거나 위험한 작업 중 대통령령으로 정하는 작업은 고용노동부장관의 승인을 받지 아니하면 도급할 수 없다.","w":"모든 유해·위험 작업이 대상은 아니다. 현행 산업안전보건법은 도금작업 등 제58조 제1항의 세 가지 작업은 도급 자체를 원칙적으로 금지하고, 급성 독성 물질 취급 등 대통령령으로 정하는 작업은 제59조에 따라 고용노동부장관의 승인을 받아야 도급할 수 있게 한다. 출제 당시 법도 대통령령으로 정한 작업만 장관의 인가를 받게 했다.","c":"상","v":1},"공인노2022_31-16-1":{"f":"직업성 질병자가 동시에 10명 이상 발생한 재해는 중대재해에 해당한다.","w":"산업안전보건법 시행규칙 제3조의 중대재해는 사망자 1명 이상, 3개월 이상 요양이 필요한 부상자 동시 2명 이상, 부상자 또는 직업성 질병자 동시 10명 이상 발생한 재해다.","c":"상","v":1},"공인노2024_33-28-1":{"f":"사업주는 잠수 작업에 종사하는 근로자에게는 1일 6시간, 1주 34시간을 초과하여 근로하게 해서는 아니 된다.","w":"산업안전보건법 제139조와 시행령 제99조는 잠함·잠수 등 고기압 작업의 근로시간을 1일 6시간, 1주 34시간으로 묶는다.","c":"상","v":1},"공인노2024_33-26-1":{"f":"안전보건관리규정은 취업규칙에 반할 수 없다. 이 경우 안전보건관리규정 중 취업규칙에 반하는 부분에 관하여는 그 취업규칙으로 정한 기준에 따른다.","w":"산업안전보건법 제25조 제2항은 안전보건관리규정이 단체협약이나 취업규칙에 반할 수 없고, 반하는 부분은 단체협약·취업규칙의 기준을 따르도록 한다.","c":"상","v":1},"공인노2025_34-24-4":{"f":"“작업환경측정”이란 사업주가 유해인자에 대한 측정계획을 수립한 후 시료를 채취하고 분석ㆍ평가하는 것을 말한다.","w":"이 문장은 작업환경측정의 정의다(산업안전보건법 제2조 제13호). 위험성평가는 유해·위험요인을 찾아내 부상·질병으로 이어질 위험성의 크기가 허용 가능한 범위인지 평가하고 감소대책을 세우는 것이다(제36조).","c":"상","v":1},"공인노2026_35-21-4":{"f":"업무정지 기간 중에 업무를 수행한 경우에는 그 등록을 취소하여야 한다.","w":"산업안전보건법 제154조는 업무정지 기간 중에 업무를 한 지도사의 등록을 반드시 취소하도록 한다. 업무정지 기간을 늘리는 규정은 없다.","c":"상","v":1},"공인노2022_31-22-2":{"f":"국가가 근로자의 근로복지를 위하여 「근로복지기본법」에 따라 보조 또는 융자한 자금은 그 목적 외 사업에 사용될 수 없다.","w":"근로복지기본법 제6조는 국가나 지방자치단체가 근로복지를 위해 보조·융자한 자금을 누구든지 그 목적사업에만 쓰도록 한다.","c":"상","v":1},"공인노2017_26-24-1":{"f":"사내근로복지기금법인은 자금차입을 할 수 없다.","w":"근로복지기본법 제64조 제2항은 사내근로복지기금법인이 자금을 차입할 수 없다고 정한다.","c":"상","v":1},"공인노2017_26-24-3":{"f":"우리사주조합은 지배관계회사로부터 우리사주 취득자금을 차입하여 우리사주를 취득할 수 있다.","w":"근로복지기본법 제42조 제1항은 우리사주조합이 우리사주제도 실시회사, 지배관계회사, 수급관계회사, 그 회사의 주주, 금융회사 등으로부터 자금을 빌려 우리사주를 취득할 수 있게 한다.","c":"상","v":1},"공인노2017_26-24-4":{"f":"사용자는 사내근로복지기금법인의 설치를 이유로 그 설치 당시에 운영하고 있는 근로복지시설의 운영을 중단할 수 없다.","w":"근로복지기본법 제68조 제1항은 사용자가 기금법인 설치를 이유로 설치 당시 운영하던 근로복지제도나 근로복지시설을 중단하거나 감축하지 못하게 한다.","c":"상","v":1},"공인노2017_26-24-5":{"f":"근로복지시설을 설치ㆍ운영하는 자는 근로자의 소득수준, 가족관계 등을 고려하여 근로복지시설의 이용자를 제한하거나 이용료를 차등하여 받을 수 있다.","w":"근로복지기본법 제30조는 근로복지시설 운영자가 근로자의 소득수준, 가족관계 등을 고려해 이용자를 제한하거나 이용료를 차등하여 받을 수 있다고 정한다.","c":"상","v":1},"공인노2022_31-22-1":{"f":"사용자는 사내근로복지기금의 설립 및 출연을 이유로 근로관계 당사자 간에 정하여진 근로조건을 낮출 수 없다.","w":"근로복지기본법 제51조는 사용자가 사내근로복지기금의 설립이나 출연을 이유로 근로관계 당사자 사이에 정해진 근로조건을 낮출 수 없다고 정한다.","c":"상","v":1},"공인노2022_31-22-4":{"f":"노동조합 및 근로자는 생산성 향상에 노력하고 근로복지정책에 협력하여야 한다.","w":"근로복지기본법 제5조 제2항은 노동조합과 근로자에게 근로의욕 증진을 통한 생산성 향상과 근로복지정책 협력을 책무로 직접 지운다. 그 협력을 위해 사용자가 임금을 올려야 한다는 규정은 없다.","c":"상","v":1},"공인노2022_31-22-5":{"f":"사용자는 우리사주조합원의 의사와 무관하게 우리사주조합원을 소속, 계급 등 일정한 기준으로 분류하여 우리사주를 할당할 수 없다.","w":"근로복지기본법 제42조의2 제1항 제2호는 우리사주조합원의 의사에 반하여 소속·계급 등 일정한 기준으로 분류해 우리사주를 할당하는 행위를 금지한다.","c":"상","v":1},"공인노2024_33-36-4":{"f":"근로복지시설을 설치ㆍ운영하는 자는 근로자의 소득수준, 가족관계 등을 고려하여 근로복지시설의 이용자를 제한하거나 이용료를 차등하여 받을 수 있다.","w":"근로복지기본법 제30조는 근로복지시설 운영자가 소득수준, 가족관계 등을 고려해 이용자를 제한하거나 이용료를 차등하여 받을 수 있다고 정한다.","c":"상","v":1},"공인노2025_34-36-4":{"f":"근로복지시설을 설치ㆍ운영하는 자는 근로복지시설의 이용료를 차등하여 받을 수 있다.","w":"근로복지기본법 제30조에 따라 근로복지시설 운영자는 근로자의 소득수준, 가족관계 등을 고려해 이용료를 차등하여 받을 수 있다.","c":"상","v":1},"공인노2026_35-35-5":{"f":"사용자는 기금법인의 설치를 이유로 그 설치 당시에 운영하고 있는 근로복지제도의 운영을 감축할 수 없다.","w":"근로복지기본법 제68조 제1항은 사용자가 기금법인 설치를 이유로 설치 당시 운영하던 근로복지제도나 근로복지시설의 운영을 중단하거나 감축하지 못하게 한다.","c":"상","v":1},"공인노2017_26-25-2":{"f":"이 법은 선원법의 적용을 받는 선박에 승무(乘務)하는 선원 중 대한민국 국적을 가지지 아니한 선원에게는 적용되지 아니한다.","w":"외국인근로자고용법 제3조 제1항 단서는 선원법이 적용되는 선박에 승무하는 외국인 선원과 그 선박 소유자를 적용 대상에서 뺀다.","c":"상","v":1},"공인노2019_28-25-2":{"f":"사용자는 외국인근로자와 근로계약을 체결하려는 경우 이를 한국산업인력공단 등에 대행하게 할 수 있다.","w":"외국인근로자고용법 제9조 제2항은 사용자가 근로계약 체결을 한국산업인력공단 등에 대행하게 할 수 있도록 한다.","c":"상","v":1},"공인노2022_31-23-1":{"f":"직업안정기관의 장은 「출입국관리법」을 위반하여 처벌을 받은 사용자에 대하여 그 사실이 발생한 날부터 3년간 외국인근로자의 고용을 제한할 수 있다.","w":"외국인근로자고용법 제20조 제1항에 따른 고용제한 기간은 그 사실이 발생한 날부터 3년이다.","c":"상","v":1},"공인노2024_33-38-2":{"f":"고용노동부장관은 송출국가가 송부한 송출대상 인력을 기초로 외국인구직자 명부를 작성하고, 관리하여야 한다.","w":"외국인근로자고용법 제7조 제1항에서 외국인구직자 명부를 작성·관리하는 주체는 고용노동부장관이다.","c":"상","v":1},"공인노2025_34-37-2":{"f":"사용자가 외국인근로자에게 기숙사를 제공하는 경우에는 「근로기준법」에서 정한 기숙사의 기준을 준수하여야 한다.","w":"외국인근로자고용법 제22조의2는 기숙사를 제공할 때 지켜야 할 기준과 정보 제공 의무를 정할 뿐, 기숙사를 반드시 제공하라고 하지는 않는다.","c":"상","v":1},"공인노2025_34-38-5":{"f":"직업안정기관의 장은 「출입국관리법」을 위반하여 처벌을 받은 사용자에 대하여 그 사실이 발생한 날부터 3년간 외국인근로자의 고용을 제한할 수 있다.","w":"외국인근로자고용법 제20조 제1항의 고용제한은 3년간이고, 제한 여부는 직업안정기관의 장의 재량이다.","c":"상","v":1},"공인노2026_35-38-3":{"f":"고용노동부장관은 외국인 취업교육기관이 거짓이나 그 밖의 부정한 방법으로 지정을 받은 경우에는 그 지정을 취소하여야 한다.","w":"외국인근로자고용법 제11조의4 제1항 단서는 거짓이나 부정한 방법으로 지정받은 외국인 취업교육기관의 지정을 반드시 취소하도록 한다. 업무정지로 대신할 수 없다.","c":"상","v":1},"공인노2019_28-22-1":{"f":"미성년자인 근로자는 독자적으로 체당금의 지급을 청구할 수 있다.","w":"임금채권보장법 제11조의2 제3항은 미성년자인 근로자가 독자적으로 대지급금(출제 당시 명칭은 체당금)의 지급을 청구할 수 있다고 정한다.","c":"상","v":1},"공인노2025_34-35-5":{"f":"고용노동부장관이 해당 근로자에게 대지급금을 지급하였을 때에는 「근로기준법」에 따른 임금채권 우선변제권은 대위되는 권리에 존속한다.","w":"임금채권보장법 제8조 제2항은 장관이 대위하는 권리에 근로기준법과 근로자퇴직급여 보장법의 우선변제권이 그대로 남는다고 정한다.","c":"상","v":1},"공인노2024_33-34-1":{"f":"도산대지급금을 지급받으려는 사람은 도산등사실인정이 있은 날부터 2년 이내에 고용노동부장관에게 대지급금의 지급을 청구해야 한다.","w":"임금채권보장법 시행령 제9조에 따라 도산대지급금은 파산선고등이나 도산등사실인정이 있은 날부터 2년 안에 고용노동부장관에게 청구한다.","c":"상","v":1},"공인노2026_35-40-1":{"f":"고용노동부장관은 사업주가 「채무자 회생 및 파산에 관한 법률」에 따른 회생절차개시의 결정이 있는 경우에 퇴직한 근로자가 지급받지 못한 임금등의 지급을 청구하면 대지급금을 지급해야 한다.","w":"임금채권보장법 제7조 제1항 제1호의 지급사유는 회생절차개시의 '결정'이다. 신청만으로는 대지급금을 받을 수 없다.","c":"상","v":1},"공인노2026_35-40-3":{"f":"재직 근로자에 대한 대지급금은 해당 근로자가 하나의 사업에 근로하는 동안 1회만 지급한다.","w":"임금채권보장법 제7조의2 제4항은 재직 근로자 대지급금을 같은 사업에서 일하는 동안 1회만 지급하도록 한다.","c":"상","v":1},"공인노2026_35-40-4":{"f":"“사업주”란 근로자를 사용하여 사업을 하는 자를 말한다.","w":"임금채권보장법 제2조는 사업주를 근로자를 사용하여 사업을 하는 자로 정의한다. 근로기준법의 사용자는 사업경영담당자 등까지 포함하는 더 넓은 개념이다.","c":"상","v":1},"공인노2026_35-40-5":{"f":"사업주가 부담하여야 하는 부담금은 그 사업에 종사하는 근로자의 보수총액에 1천분의 2의 범위에서 임금채권보장기금심의위원회의 심의를 거쳐 고용노동부장관이 정하는 부담금비율을 곱하여 산정한 금액으로 한다.","w":"임금채권보장법 제9조 제2항은 부담금비율 상한을 보수총액의 1천분의 2로 정한다.","c":"상","v":1},"공인노2026_35-34-2":{"f":"임금채권보장기금의 관리ㆍ운용에 관한 중요사항을 심의하기 위하여 고용노동부에 임금채권보장기금심의위원회를 둔다.","w":"임금채권보장법 제6조는 임금채권보장기금심의위원회를 고용노동부에 둔다고 정한다.","c":"상","v":1},"공인노2022_31-21-3":{"f":"대지급금에 관한 규정은 국가와 지방자치단체가 직접 수행하는 사업에 적용되지 아니한다.","w":"임금채권보장법 제3조 단서는 국가와 지방자치단체가 직접 수행하는 사업을 적용 대상에서 뺀다.","c":"상","v":1},"공인노2024_33-35-5":{"f":"사업주의 부담금을 산정할 때 해당 연도의 보수총액을 결정하기 곤란한 경우에는 「고용보험 및 산업재해보상보험의 보험료징수 등에 관한 법률」에 따라 고시하는 노무비율에 따라 보수총액을 결정한다.","w":"임금채권보장법 제9조 제3항은 보수총액을 정하기 어려운 경우 고용산재보험료징수법 제13조 제6항에 따라 고시하는 노무비율로 보수총액을 정하도록 한다. 전년도 보수총액을 기준으로 삼는 규정은 없다.","c":"상","v":1},"공인노2019_28-16-1":{"f":"국외 무료직업소개사업을 하려는 자는 고용노동부장관에게 신고하여야 한다.","w":"직업안정법 제18조 제1항은 무료직업소개사업을 신고제로 정한다. 국외 무료직업소개는 고용노동부장관에게 신고한다.","c":"상","v":1},"공인노2019_28-16-2":{"f":"국내 유료직업소개사업을 하려는 자는 주된 사업소의 소재지를 관할하는 특별자치도지사ㆍ시장ㆍ군수 및 구청장에게 등록하여야 한다.","w":"직업안정법 제19조 제1항은 유료직업소개사업을 등록제로 정한다. 신고로 시작할 수 있는 것은 무료직업소개사업이다.","c":"상","v":1},"공인노2019_28-16-3":{"f":"고용노동부장관의 허가를 받은 자만 근로자공급사업을 할 수 있다.","w":"직업안정법 제33조는 근로자공급사업을 허가제로 하고, 국내 근로자공급사업의 허가는 노동조합만 받을 수 있게 한다. 등록만으로 누구나 할 수 있는 사업이 아니다.","c":"상","v":1},"공인노2019_28-16-5":{"f":"직업안정기관의 장이 필요하다고 인정하면 구직자의 동의를 받아 직업적성검사를 할 수 있다.","w":"직업안정법 제9조 제2항은 구직자가 요청하거나, 직업안정기관의 장이 필요하다고 인정하여 구직자의 동의를 받은 경우에 직업상담이나 직업적성검사를 할 수 있게 한다.","c":"상","v":1},"공인노2022_31-17-4":{"f":"유료직업소개사업의 등록을 하고 유료직업소개사업을 하는 자는 구직자에게 제공하기 위하여 구인자로부터 선급금을 받아서는 아니 된다.","w":"직업안정법 제21조의2는 유료직업소개사업자가 구직자에게 줄 목적으로 구인자에게서 선급금을 받는 것을 금지한다.","c":"상","v":1},"공인노2025_34-26-1":{"f":"「노동조합 및 노동관계조정법」에 따른 노동조합은 국내 근로자공급사업의 허가를 받을 수 있다.","w":"직업안정법 제33조 제3항 제1호에 따라 국내 근로자공급사업의 허가를 받을 수 있는 자는 노동조합뿐이다.","c":"상","v":1},"공인노2024_33-29-3":{"f":"국내 유료직업소개사업을 하려는 자는 주된 사업소의 소재지를 관할하는 특별자치도지사ㆍ시장ㆍ군수 및 구청장에게 등록하여야 한다.","w":"직업안정법 제19조 제1항에 따라 국내 유료직업소개사업은 관할 시장·군수·구청장 등에게 등록한다. 고용노동부장관에게 등록하는 것은 국외 유료직업소개사업이다.","c":"상","v":1},"공인노2017_26-03":{"w":"근로기준법 시행규칙 별표(해고 예고의 예외가 되는 근로자의 귀책사유)에 네 가지가 모두 들어 있다.\nㄱ O 제품·원료를 몰래 훔치거나 불법 반출한 경우\nㄴ O 영업용 차량을 임의로 타인에게 대리운전하게 하여 교통사고를 일으킨 경우\nㄷ O 사업의 기밀·정보를 경쟁관계 사업자 등에게 제공하여 사업에 지장을 준 경우\nㄹ O 납품업체로부터 금품·향응을 받고 불량품을 납품받아 생산에 차질을 가져온 경우","c":"상","v":1},"공인노2019_28-18":{"w":"근로기준법 제26조 단서의 예외는 ① 계속 근로 기간 3개월 미만, ② 천재·사변 등 부득이한 사유로 사업 계속이 불가능한 경우, ③ 근로자가 고의로 사업에 막대한 지장을 주거나 재산상 손해를 끼친 경우로서 시행규칙 별표에 해당하는 경우다.\n①은 제26조 제1호, ③은 제2호, ④·⑤는 시행규칙 별표의 귀책사유다.\n② 단시간 근로 기간은 예외 사유가 아니다. 2019년 개정 전에는 일용·계절적 업무·수습 등 기간별 예외가 따로 있었으나 지금은 '3개월 미만'으로 통합되었다.","c":"상","v":1},"공인노2024_33-08":{"w":"ㄱ O 제29조 제2항: 노동위원회는 심문할 때 관계 당사자의 신청이나 직권으로 증인을 출석하게 하여 질문할 수 있다.\nㄴ O 제30조 제4항: 근로계약기간 만료·정년 도래 등으로 원직복직이 불가능해도 부당해고가 성립하면 임금 상당액 지급을 명할 수 있다.\nㄷ O 시행령 제11조: 구제명령의 이행기간은 서면 통지를 받은 날부터 30일 이내.\nㄹ X 제31조: 지방노동위원회 구제명령에는 중앙노동위원회에 재심을 신청할 수 있을 뿐이고, 행정소송은 중앙노동위원회의 재심판정을 대상으로 제기한다.","c":"상","v":1},"공인노2017_26-02":{"w":"③ 제2조 제1항 제4호의 근로계약 정의 그대로다.\n① 사용자는 사업주, 사업 경영 담당자, 그 밖에 근로자에 관한 사항에 대하여 사업주를 위하여 행위하는 자다. '사용자의 이익을 대표하여 행동하는 자'는 노동조합법에 나오는 표현이다.\n② 근로자는 직업의 종류와 관계없이 임금을 목적으로 사업이나 사업장에 근로를 제공하는 사람이다. 지문은 노동조합법상 근로자 정의다.\n④ 단시간근로자는 1주 동안의 소정근로시간이 같은 종류 업무의 통상 근로자보다 짧은 근로자다. 기준은 1일이 아니라 1주다.\n⑤ 평균임금은 그 근로자에게 지급된 임금 총액으로 계산한다. 전체 근로자가 아니다.","c":"상","v":1},"공인노2017_26-14":{"w":"(2022 개정 전 기준) 출제 당시 한국은 ILO 강제근로 협약(제29호)을 비준하지 않아 ④가 옳지 않은 진술이었다.\n한국은 2021년 4월 제29호·제87호·제98호를 비준했고 2022년 4월 20일 발효되었다. 지금은 제29호도 헌법 제6조 제1항에 따라 국내법과 같은 효력을 가지므로 ④도 옳은 진술이 되어 옳지 않은 선지가 없다.\n① 판례는 법원으로 보지 않는 것이 일반적 견해다.\n② 기업 내 관행이 근로관계를 규율하는 규범적 사실로 명확히 승인되면 근로계약의 내용이 된다(판례).\n③ 민법은 근로관계에 보충 적용된다.\n⑤ 행정해석은 법원이 아니다.","c":"상","v":1,"old":1,"ow":"출제 당시 정답 ④. 강제근로 협약(제29호)은 2021.4.20 비준해 2022.4.20 발효되었으므로 지금은 노동법의 법원으로 인정되고, ④도 옳은 설명이 되어 맞는 선지가 없다."},"공인노2019_28-01":{"w":"근로기준법 제1장 총칙에 있는 기본원칙은 근로조건의 기준·결정·준수, 균등한 처우(제6조), 강제 근로의 금지(제7조), 폭행의 금지(제8조), 중간착취의 배제(제9조), 공민권 행사의 보장(제10조)이다.\n국제협약의 준수는 근로기준법에 규정이 없다.","c":"상","v":1},"공인노2019_28-02":{"w":"시행령 제7조 별표 1에 따라 상시 4명 이하 사업장에도 제18조(단시간근로자의 근로조건)는 적용된다.\n제24조 경영상 해고 제한, 제27조 해고 서면통지, 제28조 부당해고 구제신청, 제46조 휴업수당은 4명 이하 사업장에는 적용되지 않는다(해고는 제23조 제2항 해고 시기 제한과 제26조 해고 예고만 적용).","c":"상","v":1},"공인노2019_28-11":{"w":"(2022 개정 전 기준) 출제 당시 한국은 ILO 제87호(결사의 자유 및 단결권 보호) 협약을 비준하지 않아 ①이 정답이었다.\n제26호(2001), 제111호(1998), 제138호(1999), 제81호(1992)는 그 전부터 비준한 협약이다.\n한국은 2021년 4월 제87호를 비준했고 2022년 4월 20일 발효되었다. 지금은 다섯 개 모두 비준 협약이라 답이 없다.","c":"상","v":1,"old":1,"ow":"출제 당시 정답 ①(제87호). 우리나라가 2021.4.20 제87호를 비준해 2022.4.20 발효되었으므로 지금은 다섯 협약 모두 비준한 협약이고 맞는 선지가 없다."},"공인노2022_31-24":{"w":"ㄱ X 제15조 제1항: 기준에 미치지 못하는 근로조건을 정한 근로계약은 그 부분에 한정하여 무효다. 계약 전체가 무효로 되지 않는다.\nㄴ O 제97조\nㄷ O 제96조 제1항: 취업규칙은 법령에 어긋나서는 안 된다.\nㄹ O 제96조 제1항: 해당 사업장에 적용되는 단체협약과도 어긋나서는 안 된다.","c":"상","v":1},"공인노2024_33-40":{"w":"네 협약 모두 비준했다.\nㄱ 제138호 취업최저연령 협약: 1999년 비준\nㄴ 제155호 산업안전보건 협약: 2008년 비준\nㄷ 제87호 결사의 자유 협약: 2021년 비준(2022년 발효)\nㄹ 제98호 단결권·단체교섭권 협약: 2021년 비준(2022년 발효)","c":"상","v":1},"공인노2026_35-37":{"w":"헌법 제32조와 맞는 것은 첫째 하나다.\n첫째 O 제2항: 국가는 근로의 의무의 내용과 조건을 민주주의원칙에 따라 법률로 정한다.\n둘째 X 제1항: 국가는 고용의 증진과 '적정임금'의 보장에 노력하고, 최저임금제는 법률이 정하는 바에 의하여 시행한다.\n셋째 X 제6항: 국가유공자·상이군경·전몰군경의 유가족은 법률이 정하는 바에 의하여 우선적으로 근로의 기회를 부여받는다. 국가의 노력 의무로 쓰여 있지 않다.\n넷째 X 제5항은 '연소자의 근로는 특별한 보호를 받는다'까지다. 고용·임금·근로조건의 부당한 차별 금지는 제4항 여자의 근로에 붙은 말이다.","c":"상","v":1},"공인노2017_26-05":{"w":"ㄱ O 제71조: 산후 1년 미만 여성은 단체협약이 있어도 1일 2시간, 1주 6시간, 1년 150시간을 넘는 시간외근로를 시킬 수 없다.\nㄴ X 제18조 제3항: 휴일·연차가 적용되지 않는 것은 4주 평균 1주 소정근로시간이 15시간 '미만'인 근로자다.\nㄷ O 제43조 제1항 단서: 법령 또는 단체협약에 특별한 규정이 있으면 임금 일부를 공제할 수 있다.\nㄹ X 제60조 제2항: 1년 미만 근로자는 1개월 개근 시 1일의 유급휴가를 받는다. 15일은 1년간 80% 이상 출근한 근로자의 연차다.","c":"상","v":1},"공인노2019_28-07":{"w":"제59조 제1항의 특례 사업은 육상운송 및 파이프라인 운송업, 수상운송업, 항공운송업, 기타 운송관련 서비스업, 보건업 다섯이다.\n육상운송업 중 노선(路線) 여객자동차운송사업은 특례에서 빠져 있다.","c":"상","v":1},"공인노2022_31-01":{"w":"제51조의2 제1항에 따라 서면 합의로 정하는 사항은 대상 근로자의 범위, 단위기간(3개월 초과 6개월 이내), 단위기간의 주별 근로시간, 그 밖에 대통령령으로 정하는 사항(서면 합의의 유효기간)이다.\n일별 근로시간은 합의 사항이 아니다. 사용자는 각 주의 근로일이 시작되기 2주 전까지 근로자에게 해당 주의 근로일별 근로시간을 통보한다(같은 조 제3항).","c":"상","v":1},"공인노2022_31-05":{"w":"시행령 제31조의 재량근로 대상 업무는 신상품·신기술 연구개발 및 인문사회과학·자연과학 연구, 정보처리시스템의 설계·분석, 신문·방송·출판의 기사 취재·편성·편집, 의복·실내장식·공업제품·광고 디자인·고안, 방송·영화 제작의 프로듀서·감독, 그 밖에 고용노동부장관이 정하는 업무다.\n정보처리시스템은 '설계·분석' 업무만 해당하고 교육 업무는 없다.","c":"상","v":1},"공인노2024_33-11":{"w":"제51조의3: 단위기간 중 근로자가 근로한 기간이 단위기간보다 짧으면, 그 근로한 기간을 평균하여 1주간에 40시간을 초과하여 근로한 시간 전부에 대해 가산임금을 지급한다.","c":"상","v":1},"공인노2024_33-13":{"w":"ㄱ X 노선여객자동차운송사업은 육상운송업 중에서도 특례에서 제외된다.\nㄴ O 수상운송업\nㄷ O 보건업\nㄹ X 영화업은 2018년 개정으로 특례 업종에서 빠졌다. 지금 특례는 육상운송 및 파이프라인 운송업, 수상운송업, 항공운송업, 기타 운송관련 서비스업, 보건업 다섯이다.","c":"상","v":1},"공인노2025_34-15":{"w":"ㄱ O 제56조 제2항 제2호: 8시간을 초과한 휴일근로는 통상임금의 100분의 100 이상을 가산한다.\nㄴ O 제57조 보상휴가제: 근로자대표와 서면 합의하면 연장·야간·휴일근로 임금 대신 휴가를 줄 수 있다.\nㄷ X 제70조 제2항: 18세 미만자의 휴일근로는 본인 동의에 더해 고용노동부장관의 인가를 받아야 한다.","c":"상","v":1},"공인노2017_26-08":{"w":"① 제67조 제1항: 친권자나 후견인은 미성년자의 근로계약을 대리할 수 없다.\n② 제17조: 연차 유급휴가는 명시 사항이다.\n③ 제20조 위약 예정의 금지\n④ 제22조 강제 저금의 금지\n⑤ 제19조 제1항: 명시된 근로조건이 사실과 다르면 근로자는 노동위원회에 손해배상을 신청할 수 있다.","c":"상","v":1},"공인노2022_31-13":{"w":"ㄱ O 제22조 제1항\nㄴ O 제18조 제1항: 같은 종류 업무에 종사하는 통상 근로자의 근로시간을 기준으로 산정한 비율에 따라 결정한다.\nㄷ O 제17조: 소정근로시간은 명시 사항이다.\nㄹ X 시용 후 본계약 체결 거절도 해고이므로 제27조에 따라 거절 사유를 서면으로 통지해야 한다(대법원 2015. 11. 27. 선고 2015두48136). 구두 통보는 효력이 없다.","c":"상","v":1},"공인노2022_31-04":{"w":"시행령 제27조의2의 임금명세서 기재사항은 근로자 성명·생년월일 등 특정 정보, 임금지급일, 임금 총액, 기본급·수당·상여금·성과금 등 항목별 금액, 항목별 계산방법(연장·야간·휴일근로 시간 수 포함), 공제 항목별 금액과 총액이다.\nㄱ O, ㄴ O\nㄷ X, ㄹ X 고용 연월일과 종사하는 업무는 임금대장(시행령 제27조) 기재사항이다.","c":"상","v":1},"공인노2025_34-16":{"w":"시행령 제27조의 임금대장 기재사항은 성명, 생년월일·사원번호 등, 고용 연월일, 종사하는 업무, 임금 및 가족수당 계산의 기초가 되는 사항, 근로일수, 근로시간수, 연장·야간·휴일근로 시간수, 기본급·수당 등 임금의 내역별 금액, 공제 항목별 금액이다.\nㄱ O, ㄴ O, ㄹ O(임금 내역별 금액)\nㄷ X 임금지급일은 임금명세서(시행령 제27조의2) 기재사항이다.","c":"상","v":1},"공인노2026_35-07":{"w":"제43조의3: 체불자료 제공일 이전 3년 이내 임금등을 체불하여 2회 이상 유죄가 확정된 자로서, 제공일 이전 1년 이내 체불총액이 2천만원 이상인 체불사업주가 대상이다.","c":"상","v":1},"공인노2017_26-11":{"w":"⑤ 판례: 취업규칙이 문언상 불리하게 변경된 것이 명백하면 사회통념상 합리성은 제한적으로 엄격하게 해석·적용한다(판례).\n① 동의 없는 불리한 변경도 변경 후 새로 취업한 근로자에게는 변경된 취업규칙이 적용된다(대법원 1992. 12. 22. 선고 91다45165 전원합의체).\n② 노동조합이 없으면 근로자 과반수의 동의(회의 방식 등 집단적 의사결정)가 필요하다.\n③ 과반수 노동조합이 있으면 그 노동조합의 동의가 필요하다.\n④ 일부에게 유리하고 일부에게 불리한 변경은 전체적으로 불이익 변경으로 보아 근로자 전체의 집단적 동의를 받아야 한다(판례).","c":"상","v":1},"공인노2024_33-17":{"w":"ㄱ X 근로기준법 제76조의2·제76조의3에는 직장 내 괴롭힘 예방교육 의무가 없다. 매년 예방교육 의무는 남녀고용평등법의 직장 내 성희롱 예방교육이다.\nㄴ O 제76조의3 제3항\nㄷ O 제76조의3 제4항","c":"상","v":1},"공인노2026_35-10":{"w":"ㄱ O 취업규칙상 당연퇴직 사유라도 근로자 의사에 반해 근로관계를 끝내는 것이면 해고이므로 제23조 제1항의 정당한 이유가 있어야 한다(판례).\nㄴ X 제96조 제2항: 고용노동부장관은 법령이나 단체협약에 어긋나는 취업규칙의 변경을 명할 수 있다.\nㄷ X 동의 없는 불리한 변경도 변경 후 취업한 근로자에게는 효력이 있다(대법원 91다45165 전원합의체).","c":"상","v":1},"공인노2026_35-13":{"w":"반의사불벌 대상은 제36조, 제43조, 제44조, 제44조의2, 제46조, 제51조의3, 제52조 제2항 제2호, 제56조 위반이다. 출제 당시에는 제109조 제2항에 있었고 2026. 4. 7. 개정으로 제107조 제2항으로 옮겨졌다. 명단 공개 기간 중의 위반은 반의사불벌이 아니다.\nㄱ O 제46조 휴업수당 미지급\nㄴ O 제56조 가산임금 미지급\nㄷ X 제26조 해고예고 위반은 제110조 제1호로 처벌하고 반의사불벌죄가 아니다.","c":"상","v":1},"공인노2026_35-16":{"w":"ㄱ O 제76조의2: 사용자 또는 근로자는 직장에서의 지위 또는 관계 등의 우위를 이용하여 업무상 적정범위를 넘어 다른 근로자에게 신체적·정신적 고통을 주거나 근무환경을 악화시키는 행위를 해서는 안 된다.\nㄴ X 고객의 폭언 등으로부터 근로자를 보호하는 조치는 산업안전보건법 제41조에 있다. 근로기준법 규정이 아니다.\nㄷ X 제76조의3 제5항: 징계 등 조치를 하기 '전에' 피해근로자의 의견을 들어야 한다.","c":"상","v":1},"공인노2019_28-06":{"w":"제69조: 15세 이상 18세 미만인 자의 근로시간은 1일 7시간, 1주 35시간을 초과하지 못하고, 합의에 따라 1일 1시간, 1주 5시간을 한도로 연장할 수 있다.\n7 + 35 + 1 + 5 = 48시간","c":"상","v":1},"공인노2025_34-05":{"w":"시행규칙 제12조의2: 미숙아를 출산한 경우 출산전후휴가는 100일이다. 미숙아는 임신 37주 미만의 출생아 또는 출생 시 체중 2천500그램 미만인 영유아로서, 출생 후 24시간 이내에 신생아중환자실에 입원한 영유아다.\nㄱ 100, ㄴ 37, ㄷ 24","c":"상","v":1},"공인노2025_34-17":{"w":"제71조: 산후 1년이 지나지 않은 여성은 단체협약이 있어도 1일 2시간, 1주 6시간, 1년 150시간을 초과하는 시간외근로를 시키지 못한다.","c":"상","v":1},"공인노2025_34-23":{"w":"ㄱ O 시행령 제18조 제1항 제1호: 산업안전보건위원회에서 심의·의결한 업무는 안전관리자의 업무다.\nㄴ O 보호구 구입 시 적격품 여부 확인은 제15조 제1항 제8호의 안전보건관리책임자 업무다. 제24조 제2항의 심의·의결 사항에는 이 호가 빠져 있다.\nㄷ O 제35조: 근로자대표는 산업안전보건위원회 의결 사항의 통지를 요청할 수 있고, 사업주는 성실히 따라야 한다.\nㄹ X 제44조 제2항: 공정안전보고서는 위원회의 심의를 거치고, 위원회가 없는 사업장은 근로자대표의 '의견'을 들어야 한다. 동의가 아니다.","c":"상","v":1},"공인노2025_34-25":{"w":"산업안전보건법 제39조 제1항의 보건조치 대상에 다섯 개가 모두 있다.\n산소결핍(제1호), 방사선(제2호), 사업장에서 배출되는 기체·액체·찌꺼기(제3호), 계측감시·컴퓨터 단말기 조작·정밀공작(제4호), 단순반복작업 또는 인체에 과도한 부담을 주는 작업(제5호).","c":"상","v":1},"공인노2026_35-19":{"w":"산업안전보건법 제2조 제11호의 건설공사는 건설산업기본법의 건설공사, 전기공사업법의 전기공사, 정보통신공사업법의 정보통신공사, 소방시설공사업법의 소방시설공사, 국가유산수리법의 국가유산 수리공사다. 네 개 모두 해당한다.","c":"상","v":1},"공인노2017_26-17":{"w":"③ 직업안정법 제21조의2: 등록을 하고 유료직업소개사업을 하는 자와 그 종사자는 구직자에게 제공하기 위하여 구인자로부터 선급금을 받아서는 안 된다.\n① 제8조: 구인자가 구인조건을 밝히기를 거부하면 구인신청의 수리를 거부할 수 있다.\n② 제11조 구인·구직의 개척\n④ 제21조의3: 무료·유료 직업소개사업을 하는 자와 그 종사자는 18세 미만 구직자를 소개할 때 친권자나 후견인의 취업동의서를 받아야 한다.\n⑤ 제33조 제1항","c":"상","v":1},"공인노2017_26-23":{"w":"② 임금채권보장법 제3조 단서: 국가와 지방자치단체가 직접 수행하는 사업에는 적용하지 않는다.\n① 체당금(지금 명칭은 대지급금)의 범위는 제7조 제2항의 임금, 최종 3년간 퇴직급여등, 휴업수당, 출산전후휴가기간 중 급여다. 재해보상금은 들어가지 않는다. 2026. 8. 20. 시행 개정으로 도산 대지급금의 임금·휴업수당·출산전후휴가 급여는 최종 6개월분까지로 늘었다.\n③ 제9조 사업주 부담금\n④ 제6조 임금채권보장기금심의위원회\n⑤ 제8조 미지급 임금등의 청구권 대위","c":"상","v":1},"공인노2019_28-24":{"w":"근로복지기본법 제62조의 사내근로복지기금 사업은 주택구입자금 보조 등 재산형성 지원, 장학금·재난구호금 등 생활원조, 모성보호·일가정 양립 비용 지원, 직접 도급받는 업체 소속 근로자 및 파견근로자의 복리후생 증진 등이다.\n사업주의 체불임금 지급 비용은 기금 사업이 아니다. 기금을 사업주의 임금 지급에 쓰면 근로자 복지라는 목적에서 벗어난다.","c":"상","v":1},"공인노2024_33-37":{"w":"외국인고용법 제18조의2: 취업활동 기간 3년이 만료되어 출국하기 전에 사용자가 재고용 허가를 요청한 근로자는 한 차례만 2년 미만의 범위에서 취업활동 기간을 연장받을 수 있다.","c":"상","v":1},"공인노2025_34-34":{"w":"임금채권보장법 제7조 제1항의 대지급금 지급 사유에 네 개가 모두 있다.\nㄱ O 제1호 회생절차개시 결정\nㄴ O 제2호 파산선고 결정\nㄷ O 제4호 확정된 종국판결 등\nㄹ O 제5호 체불임금등·사업주 확인서로 미지급임금등이 확인된 경우","c":"상","v":1},"공인노2026_35-31":{"w":"직업안정법 제26조의 겸업 금지 사업은 결혼중개업, 숙박업, 식품접객업 중 대통령령으로 정하는 영업(단란주점영업·유흥주점영업)이다. 네 개 모두 해당한다.","c":"상","v":1},"공인노2026_35-39":{"w":"외국인고용법 제20조 제1항과 시행령 제25조의 고용 제한 사유에 부상은 없다. 산업안전보건법 위반 중 고용 제한 사유는 외국인근로자의 '사망'으로 같은 법 제167조 제1항에 따른 처벌을 받은 경우다.\n①은 법 제20조 제1항, ②는 같은 항의 출입국관리법 위반 처벌, ④·⑤는 시행령 제25조의 사유다.","c":"상","v":1},"공인노2024_33-24":{"w":"(2025 개정 전 기준) 출제 당시 제18조의2는 배우자 출산휴가 10일, 출산한 날부터 90일이 지나면 청구할 수 없다고 정했고 가족돌봄휴직은 연간 최장 90일(제22조의2 제4항)이어서 정답이 ④였다.\n2025. 2. 23. 시행 개정으로 휴가는 20일, 기한은 출산한 날부터 120일로 늘었다. 2026. 9. 18. 시행 개정으로 이름이 '배우자 출산전후휴가'로 바뀌고 배우자 출산예정일 50일 전부터 쓸 수 있게 되었다. 가족돌봄휴직 90일은 그대로다.\n지금 기준으로는 맞는 선지가 없다.","c":"상","v":1,"old":1,"ow":"출제 당시 정답 ④(10, 90, 90). 2025.2.23 시행 개정으로 배우자 출산휴가는 20일, 청구 기한은 출산일부터 120일이 되어 지금 기준(20, 120, 90)에 맞는 선지가 없다(남녀고용평등법 제18조의2, 제22조의2)."},"공인노2026_35-26":{"w":"남녀고용평등법 시행령의 허용 예외는 계속 근로 6개월 미만, 14일 이상 구인 노력에도 대체인력 채용 불가, 업무 성격상 근로시간 분할 곤란, 정상적 사업 운영에 중대한 지장, 그리고 가족돌봄등근로시간단축 종료일부터 2년이 지나지 않은 근로자의 신청이다.\n⑤의 기간은 3년이 아니라 2년이다.","c":"상","v":1},"공인노2017_26-20":{"w":"⑤ 기간제법 제9조 제4항: 차별 분쟁의 입증책임은 사용자가 진다.\n① 제13조 제1항: 시정명령에는 취업규칙·단체협약 등의 제도개선 명령을 포함할 수 있다.\n② 제2조 제3호: 경영성과에 따른 성과금도 차별 판단 대상이므로 합리적 이유 없이 불리하게 처우하면 차별이다.\n③ 제17조: 근로일 및 근로일별 근로시간은 단시간근로자에게만 서면 명시한다.\n④ 제6조 제1항: 근로자 동의가 있어도 1주 12시간을 초과할 수 없다.","c":"상","v":1},"공인노2019_28-19":{"w":"파견법 제6조의2 제1항의 직접고용 의무 사유로 판단한다.\nㄱ O 무허가 파견사업자로부터 역무를 받은 경우(제7조 제3항 위반)\nㄴ X 제조업 직접생산공정업무라도 일시적·간헐적 사유로 사용기간 내에 쓰면 제5조 제2항에 따라 적법하므로 직접고용 의무가 없다.\nㄷ O, ㄹ O 건설공사현장 업무는 제5조 제3항의 절대 금지 업무여서 부상·연차휴가로 인한 결원이 있어도 파견할 수 없다. 위반하면 직접고용 의무가 생긴다.","c":"상","v":1},"공인노2024_33-18":{"w":"파견법 제5조 제3항의 파견 금지 업무에 세 개가 모두 있다.\nㄱ 건설공사현장 업무(제1호)\nㄴ 선원법상 선원의 업무(제3호)\nㄷ 물류정책기본법 등의 하역업무로서 직업안정법에 따라 근로자공급사업 허가를 받은 지역의 업무(제2호)","c":"상","v":1},"공인노2024_33-20":{"w":"ㄱ O 제4조 제1항 제3호\nㄴ O 제4조 제1항 제4호: 고령자(55세 이상)와 근로계약을 체결하는 경우\nㄷ O 제3조 제3항: 국가와 지방자치단체 기관에는 상시 근로자 수와 관계없이 적용한다.\nㄹ O 제4조 제1항 제2호","c":"상","v":1},"공인노2024_33-22":{"w":"기간제법 제17조의 서면 명시 사항은 근로계약기간, 근로시간·휴게, 임금의 구성항목·계산방법·지불방법, 휴일·휴가, 취업의 장소와 종사할 업무, 근로일 및 근로일별 근로시간(단시간근로자에 한정)이다.\nㄱ O, ㄴ O, ㄷ O\nㄹ X 근로일별 근로시간은 단시간근로자에게만 명시한다.","c":"상","v":1},"공인노2025_34-21":{"w":"시행령 제3조의 예외 사유에 네 개가 모두 있다.\nㄱ O 기업부설연구소 등 연구기관에서 연구업무에 직접 종사하는 경우\nㄴ O 기술사 등급 국가기술자격 소지자가 해당 분야에 종사하는 경우\nㄷ O 고등교육법상 학교의 조교 업무\nㄹ O 4주 평균 1주 소정근로시간 15시간 미만인 근로자","c":"상","v":1},"공인노2026_35-18":{"w":"기간제법 제21조: 제16조(불리한 처우의 금지)를 위반해 근로자에게 해고 그 밖의 불리한 처우를 한 자는 2년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. 위반 사실을 감독기관에 통지한 것(제18조)을 이유로 한 불리한 처우도 제16조에 들어 있다.","c":"상","v":1},"공인노2026_35-24":{"w":"제17조 제6호 근로일 및 근로일별 근로시간은 단시간근로자에 한정하여 서면으로 명시한다. 기간제근로자에게는 근로계약기간, 근로시간·휴게, 임금, 휴일·휴가, 취업 장소와 업무를 명시한다.","c":"상","v":1},"공인노2026_35-25":{"w":"시행령 제2조와 별표 1에 따라 상시 4명 이하 사업장에도 제7조(통상근로자로의 전환 노력)는 적용된다.\n제4조(2년 초과 사용 제한), 제6조(초과근로 제한), 제8조(차별적 처우 금지)와 그에 딸린 고용노동부장관의 시정요구(제15조의2)는 적용되지 않는다.","c":"중","v":1},"공인노2024_33-33":{"w":"퇴직급여법 시행령 제14조의 DC형 중도인출 사유로 판단한다.\nㄱ O 무주택자의 주거 목적 전세금·임대차보증금 부담(1회 한정)\nㄴ O 무주택자의 본인 명의 주택 구입\nㄷ X 장례비는 중도인출 사유가 아니다. 장례비·혼례비·대학등록금은 수급권 담보 제공 사유(시행령 제2조)에 있다.","c":"상","v":1},"공인노2025_34-32":{"w":"퇴직급여법 시행령 제2조의 담보 제공 사유로 판단한다.\nㄱ O 무주택자 본인 명의 주택 구입\nㄴ O 무주택자 주거 목적 전세금 부담(1회 한정)\nㄷ O 6개월 이상 요양이 필요한 본인·배우자·부양가족의 의료비\nㄹ O 가입자 본인·배우자·부양가족의 대학등록금\nㅁ X 임금피크제 시행은 퇴직금 중간정산 사유(시행령 제3조)다.","c":"상","v":1},"공인노2026_35-33":{"w":"퇴직급여법 제24조 제2항과 시행령 제17조에 따라 퇴직급여 일시금 수령자, 자영업자 등 안정적 소득이 있는 사람, 공무원연금·군인연금·사학연금·별정우체국연금 적용자 모두 개인형퇴직연금제도를 설정할 수 있다. 네 개 모두 해당한다.","c":"상","v":1},"공인노2017_26-15-2":{"w":"헌법 제32조 제3항이 근로조건의 기준을 인간의 존엄성을 보장하도록 법률로 정하게 한다. 이 위임에 따라 만든 법률이 근로기준법이다.","c":"상","v":1},"공인노2017_26-15-3":{"w":"헌법 제32조 제1항 후단이 최저임금제 시행을 국가의 의무로 정한다. 이를 구체화한 법률이 최저임금법이다.","c":"상","v":1},"공인노2017_26-15-4":{"w":"헌법 제32조 제4항이 여자의 근로에 대한 특별한 보호와 고용·임금·근로조건에서의 차별 금지를 함께 규정한다.","c":"상","v":1},"공인노2017_26-15-5":{"w":"헌법 제32조 제6항은 국가유공자·상이군경 및 전몰군경의 유가족에게 우선적 근로 기회를 준다. 전몰군경 본인이 아니라 그 유가족이 대상이다.","c":"상","v":1},"공인노2019_28-10-1":{"w":"헌법 제32조 제1항 후단이 최저임금제 시행을 국가의 의무로 정한다. 최저임금법이 이를 구체화한다.","c":"상","v":1},"공인노2019_28-10-2":{"w":"헌법 제32조 제4항이 여자의 근로에 대한 특별한 보호와 고용·임금·근로조건에서의 부당한 차별 금지를 규정한다.","c":"상","v":1},"공인노2019_28-10-4":{"w":"헌법 제32조 제5항이 연소자의 근로는 특별한 보호를 받는다고 정한다. 근로기준법 제5장(제64조 이하)이 그 보호 규정이다.","c":"상","v":1},"공인노2019_28-10-5":{"w":"헌법 제32조 제6항의 내용이다. 우선적 근로 기회의 대상은 국가유공자·상이군경과 전몰군경의 유가족이다.","c":"상","v":1},"공인노2022_31-25-1":{"w":"헌법재판소는 근로의 권리를 사람이 인간다운 생활을 위해 일할 권리로 보아 자연인에게만 인정하고 법인이나 노동조합은 주체가 될 수 없다고 본다.","c":"중","v":1},"공인노2022_31-25-2":{"w":"헌법 제32조 제3항이 근로조건의 기준을 인간의 존엄성을 보장하도록 법률로 정하게 한다.","c":"상","v":1},"공인노2022_31-25-3":{"w":"헌법 제37조 제2항에 따라 기본권인 근로의 권리도 국가안전보장·질서유지·공공복리를 위해 필요한 경우에 한하여 법률로 제한할 수 있다.","c":"상","v":1},"공인노2022_31-25-5":{"w":"헌법 제32조 제4항이 여자의 근로에 대한 특별한 보호와 고용·임금·근로조건에서의 부당한 차별 금지를 규정한다.","c":"상","v":1},"공인노2024_33-02-1":{"w":"근로기준법 제6조의 균등대우원칙은 헌법 제11조의 평등원칙을 근로관계에서 구체화한 규정이다. 판례도 같은 취지로 본다.","c":"중","v":1},"공인노2024_33-02-3":{"w":"근로기준법 제10조 단서에 따라 사용자는 공민권 행사나 공의 직무 수행에 지장이 없으면 근로자가 청구한 시간을 변경할 수 있다. 거부는 할 수 없다.","c":"상","v":1},"공인노2024_33-02-4":{"w":"근로기준법 제5조가 근로자와 사용자 모두에게 단체협약·취업규칙·근로계약을 지키고 성실하게 이행할 의무를 지운다.","c":"상","v":1},"공인노2024_33-02-5":{"w":"근로기준법 제9조(중간착취의 배제)의 내용이다. 주체를 '누구든지'로 정해 사용자에 한정하지 않는다.","c":"상","v":1},"공인노2024_33-03-1":{"w":"근로기준법 제11조 제1항 단서가 동거하는 친족만을 사용하는 사업·사업장과 가사 사용인을 적용 대상에서 뺀다.","c":"상","v":1},"공인노2024_33-03-2":{"w":"근로기준법 제11조 제1항은 상시 5명 이상 근로자를 사용하는 모든 사업에 적용한다. 판례는 사업이 계속적일 필요가 없어 1회적·일시적 사업도 포함된다고 본다.","c":"중","v":1},"공인노2024_33-03-3":{"w":"근로기준법 시행령 제7조 [별표 1]이 상시 4명 이하 사업에 적용하는 규정으로 제17조(근로조건의 명시)를 넣고 있다.","c":"상","v":1},"공인노2024_33-03-5":{"w":"근로기준법 시행령 제7조 [별표 1]의 4명 이하 사업 적용 규정에 제60조가 없다. 연차 유급휴가는 상시 5명 이상 사업에만 적용된다.","c":"상","v":1},"공인노2024_33-39-1":{"w":"헌법 제32조 제2항 후단이 근로의 의무의 내용과 조건을 민주주의원칙에 따라 법률로 정하게 한다.","c":"상","v":1},"공인노2025_34-39-3":{"w":"헌법 제32조 제1항 후단이 고용 증진과 적정임금 보장의 노력 의무를 국가에 지운다.","c":"상","v":1},"공인노2025_34-40-2":{"w":"근로기준법 제96조 제1항이 취업규칙은 법령이나 해당 사업장에 적용되는 단체협약과 어긋나서는 아니 된다고 정한다.","c":"상","v":1},"공인노2025_34-40-3":{"w":"근로기준법 제97조 전단의 내용이다. 무효로 된 부분은 같은 조 후단에 따라 취업규칙에 정한 기준으로 채운다.","c":"상","v":1},"공인노2025_34-40-4":{"w":"판례는 취업규칙을 근로기준법이 근로자 보호를 위해 작성을 강제하고(제93조) 법규범성을 부여한 것으로 본다(법규범설).","c":"중","v":1},"공인노2025_34-40-5":{"w":"근로기준법 제15조 제1항이 근로기준법 기준에 못 미치는 근로계약을 그 부분에 한정하여 무효로 한다. 무효 부분은 제2항에 따라 법의 기준으로 채운다.","c":"상","v":1},"공인노2026_35-06-1":{"w":"근로기준법 제18조 제3항이 4주 평균 1주 소정근로시간 15시간 미만인 근로자에게 제55조(휴일)와 제60조(연차 유급휴가)를 적용하지 않는다고 정한다.","c":"상","v":1},"공인노2026_35-06-2":{"w":"근로기준법 제93조가 상시 10명 이상 근로자를 사용하는 사용자에게 취업규칙 작성과 고용노동부장관 신고 의무를 지운다.","c":"상","v":1},"공인노2026_35-06-4":{"w":"근로기준법 제12조가 국가·특별시·광역시·도·시·군·구·읍·면·동 그 밖에 이에 준하는 것에도 이 법을 적용한다고 정한다.","c":"상","v":1},"공인노2026_35-06-5":{"w":"근로기준법 제63조 제1호가 토지의 경작·개간, 식물의 식재·재배·채취 사업, 그 밖의 농림 사업 근로자에게 근로시간·휴게·휴일 규정을 적용하지 않는다고 정한다.","c":"상","v":1},"공인노2026_35-08-1":{"w":"근로기준법 제13조가 사용자 또는 근로자는 근로감독관 등의 요구가 있으면 지체 없이 보고하거나 출석하여야 한다고 정한다. 근로자도 의무 주체다.","c":"상","v":1},"공인노2026_35-08-3":{"w":"근로기준법 제14조 제1항이 사용자에게 이 법과 시행령의 주요 내용과 취업규칙을 근로자가 자유롭게 열람할 수 있는 장소에 게시하거나 갖추어 두게 한다.","c":"상","v":1},"공인노2026_35-08-4":{"w":"근로기준법 제9조(중간착취의 배제)의 내용이다. 주체가 '누구든지'라서 사용자에 한정되지 않는다.","c":"상","v":1},"공인노2026_35-08-5":{"w":"근로기준법 제5조가 근로자와 사용자 각자에게 단체협약·취업규칙·근로계약을 지키고 성실하게 이행할 의무를 지운다.","c":"상","v":1},"공인노2026_35-36-4":{"w":"근로기준법 제97조는 취업규칙 기준에 미달하는 근로계약만 무효로 하므로 더 유리한 근로계약은 유효하다. 판례는 취업규칙이 집단적 동의로 불리하게 바뀌어도 근로자의 개별 동의가 없으면 유리한 근로계약이 우선한다고 본다(대법원 2019. 11. 14. 선고 2018다200709 판결).","c":"상","v":1},"공인노2019_28-03-1":{"w":"근로기준법 제64조 제1항 단서에 따라 15세 미만인 자도 대통령령이 정하는 기준에 따라 고용노동부장관이 발급한 취직인허증을 지니면 근로자로 사용할 수 있다.","c":"상","v":1},"공인노2019_28-03-2":{"w":"근로기준법 제67조 제3항이 18세 미만인 자와 근로계약을 체결할 때 제17조의 근로조건을 서면으로 명시하여 교부하게 한다.","c":"상","v":1},"공인노2019_28-03-3":{"w":"근로기준법 제19조 제1항이 명시된 근로조건이 사실과 다르면 근로자에게 손해배상청구권과 즉시 해제권을 준다.","c":"상","v":1},"공인노2019_28-03-4":{"w":"근로기준법 제67조 제2항이 친권자·후견인 또는 고용노동부장관에게 미성년자에게 불리한 근로계약의 해지권을 준다. 제1항은 친권자·후견인의 근로계약 대리 체결을 금지한다.","c":"상","v":1},"공인노2019_28-04-2":{"w":"판례는 채용내정 취소가 정당한 이유 없는 해고로서 무효이면 채용내정자가 취업했더라면 받았을 임금을 청구할 수 있다고 본다(민법 제538조 제1항).","c":"중","v":1},"공인노2019_28-04-3":{"w":"판례는 취업규칙상 시용기간 적용이 선택 사항인데도 근로계약에서 시용기간을 명시하지 않았다면 정식 사원으로 채용된 것으로 본다(대법원 1999. 11. 12. 선고 99다30473 판결).","c":"중","v":1},"공인노2019_28-04-4":{"w":"시용 근로계약의 본계약 거부도 근로기준법 제27조의 서면통지 대상이다. 판례는 거부 사유를 구체적·실질적으로 적어야 하므로 시용기간 만료만 적은 통지는 효력이 없다고 본다(대법원 2015. 11. 27. 선고 2015두48136 판결).","c":"중","v":1},"공인노2019_28-04-5":{"w":"판례는 시용기간 만료 후 본계약 거부를 해약권 유보에 따른 해고로 보아 보통 해고보다 넓게 인정하되 객관적으로 합리적인 이유가 있고 사회통념상 상당해야 한다고 본다(대법원 2006. 2. 24. 선고 2002다62432 판결).","c":"중","v":1},"공인노2024_33-04-1":{"w":"근로계약도 민법상 계약이므로 의사표시에 무효·취소 사유(민법 제107조~제110조)가 있으면 이를 주장할 수 있다. 판례는 학력 허위 기재 등 기망을 이유로 한 취소를 인정하되 취소의 효력은 장래에만 미친다고 본다.","c":"중","v":1},"공인노2024_33-04-3":{"w":"근로기준법 제17조 제1항 후단이 근로계약 체결 후 같은 항 각 호의 사항(임금·소정근로시간 등)을 변경하는 경우에도 명시하게 한다.","c":"상","v":1},"공인노2024_33-04-4":{"w":"판례는 시용기간 중 해고나 본계약 거부를 해약권 유보에 따른 것으로 보아 보통의 해고보다 넓게 인정한다. 다만 객관적으로 합리적인 이유와 사회통념상 상당성은 필요하다.","c":"중","v":1},"공인노2024_33-04-5":{"w":"판례는 사용자가 근로계약에 수반되는 신의칙상 부수적 의무로서 피용자의 생명·신체·건강을 해치지 않도록 필요한 조치를 할 보호의무를 진다고 본다. 이를 어기면 채무불이행 책임을 진다.","c":"중","v":1},"공인노2025_34-01-2":{"w":"근로기준법 시행령 제9조 [별표 2] 제5호(취업규칙의 작성 및 변경)가 단시간근로자에게만 적용되는 취업규칙을 불리하게 바꿀 때 적용 대상 단시간근로자 과반수의 동의를 받게 한다.","c":"중","v":1},"공인노2025_34-01-3":{"w":"근로기준법 시행령 제9조 [별표 2] 제4호(휴일·휴가의 적용)가 단시간근로자의 연차 유급휴가 임금을 시간급 기준으로 정한다.","c":"중","v":1},"공인노2025_34-01-4":{"w":"근로기준법 시행령 제9조 [별표 2] 제3호가 단시간근로자에게 초과근로를 시키려면 근로자와 합의하도록 정한다. 기간제법 제6조 제1항도 단시간근로자의 동의를 요구한다.","c":"중","v":1},"공인노2025_34-01-5":{"w":"근로기준법 시행령 제9조 [별표 2] 제4호가 여성인 단시간근로자의 생리휴가와 출산전후휴가 임금을 일급 통상임금 기준으로 정한다.","c":"중","v":1},"공인노2025_34-03-1":{"w":"근로기준법 시행령 제19조가 사용증명서 청구권자를 계속하여 30일 이상 근무한 근로자로 하고 청구 기한을 퇴직 후 3년 이내로 정한다.","c":"상","v":1},"공인노2025_34-03-2":{"w":"근로기준법 시행령 제21조가 사용기간이 30일 미만인 일용근로자에 대해 근로자 명부를 작성하지 아니할 수 있다고 정한다.","c":"상","v":1},"공인노2025_34-03-3":{"w":"근로기준법 제42조와 시행령 제22조 제1항이 고용·해고·퇴직에 관한 서류를 3년간 보존하게 한다.","c":"상","v":1},"공인노2025_34-03-5":{"w":"근로기준법 제19조 제1항에 따라 명시된 근로조건이 사실과 다르면 근로자는 손해배상을 청구하거나 즉시 근로계약을 해제할 수 있다.","c":"상","v":1},"공인노2026_35-01-1":{"w":"근로기준법 제40조(취업 방해의 금지)의 내용이다. 주체가 '누구든지'라서 사용자에 한정하지 않는다.","c":"상","v":1},"공인노2026_35-01-3":{"w":"근로기준법 제41조 제2항이 근로자 명부 기재 사항이 변경되면 지체 없이 정정하게 한다.","c":"상","v":1},"공인노2026_35-01-4":{"w":"근로기준법 시행령 제22조 제2항이 임금대장의 보존기간을 마지막으로 써 넣은 날부터 기산한다고 정한다. 보존기간은 법 제42조에 따라 3년이다.","c":"상","v":1},"공인노2026_35-01-5":{"w":"근로기준법 제39조 제1항이 퇴직 후라도 근로자가 청구하면 사용기간·업무 종류·지위와 임금 등에 관한 증명서를 즉시 내주게 한다. 제2항은 근로자가 요구한 사항만 적도록 한다.","c":"상","v":1},"공인노2017_26-10-1":{"w":"근로기준법 제43조 제1항의 직접 지급 원칙상 임금은 근로자 본인에게 주어야 한다. 판례도 근로자가 임금채권을 양도하거나 대리인에게 위임해도 사용자는 근로자에게 직접 지급해야 한다고 본다.","c":"중","v":1},"공인노2017_26-10-2":{"w":"근로기준법 제43조 제2항이 임금을 매월 1회 이상 일정한 날짜를 정하여 지급하게 한다. 연봉제라도 이 원칙의 예외가 아니어서 연봉을 나누어 매월 지급해야 한다.","c":"상","v":1},"공인노2017_26-10-4":{"w":"근로기준법 제45조와 시행령 제25조 제2호가 근로자나 그 수입으로 생계를 유지하는 자의 혼인을 비상한 경우로 정한다. 이때 지급기일 전이라도 이미 제공한 근로에 대한 임금을 주어야 한다.","c":"상","v":1},"공인노2017_26-10-5":{"w":"근로기준법 시행령 제23조 제1호가 1개월을 초과하는 기간의 출근 성적에 따라 지급하는 정근수당을 매월 1회 이상 지급 원칙(법 제43조 제2항)의 예외로 정한다.","c":"상","v":1},"공인노2019_28-05-1":{"w":"근로기준법 제43조 제1항 본문이 통화불·직접불·전액불 원칙을 정한다.","c":"상","v":1},"공인노2019_28-05-2":{"w":"근로기준법 제43조 제2항 본문이 정기불 원칙을 정한다. 임시 지급 임금 등은 같은 항 단서와 시행령 제23조의 예외에 해당한다.","c":"상","v":1},"공인노2019_28-05-3":{"w":"근로기준법 제43조 제1항의 전액불 원칙 때문에 사용자는 근로자에 대한 불법행위 손해배상채권이나 대출금채권으로 임금채권과 상계하지 못한다는 것이 판례다.","c":"중","v":1},"공인노2019_28-05-5":{"w":"판례는 임금채권 양도 자체는 유효하지만 근로기준법 제43조 제1항의 직접불 원칙상 사용자는 근로자에게 직접 지급해야 하므로 양수인은 사용자에게 지급을 청구할 수 없다고 본다(대법원 1988. 12. 13. 선고 87다카2803 전원합의체 판결).","c":"중","v":1},"공인노2022_31-09-2":{"w":"근로기준법 제2조 제2항이 산출된 평균임금이 통상임금보다 적으면 통상임금액을 평균임금으로 한다고 정한다.","c":"상","v":1},"공인노2022_31-09-3":{"w":"근로기준법 제43조 제2항 단서가 임시로 지급하는 임금·수당 등과 시행령 제23조의 임금을 정기불 원칙의 예외로 둔다.","c":"상","v":1},"공인노2022_31-09-4":{"w":"근로기준법 시행령 제2조 제1항 제2호가 출산전후휴가 기간과 그 기간 중 지급된 임금을 평균임금 산정기간과 임금 총액에서 각각 빼게 한다.","c":"상","v":1},"공인노2022_31-09-5":{"w":"근로기준법 제2조 제1항 제6호의 평균임금 정의다. 총일수로 나누므로 소정근로일수가 아니라 달력상 일수가 기준이다.","c":"상","v":1},"공인노2024_33-01-1":{"w":"판례는 공공기관 경영평가성과급처럼 계속적·정기적으로 지급되고 지급대상·조건이 확정돼 사용자에게 지급의무가 있으면 근로의 대가인 임금으로 보아 평균임금에 넣는다(대법원 2018. 12. 13. 선고 2018다231536 판결).","c":"중","v":1},"공인노2024_33-09-1":{"w":"근로기준법 제43조의2 제2항이 명단 공개 전에 체불사업주에게 3개월 이상의 기간을 정하여 소명 기회를 주게 한다.","c":"상","v":1},"공인노2024_33-09-3":{"w":"근로기준법 시행령 제23조의3 제1항 제1호가 체불사업주가 법인이면 그 대표자의 성명·나이·주소와 법인의 명칭·주소를 공개하게 한다.","c":"상","v":1},"공인노2024_33-09-4":{"w":"근로기준법 제43조의3 제2항은 체불자료를 받은 자가 체불사업주의 신용도·신용거래능력 판단과 관련한 업무 외의 목적으로 이용하는 것을 금지한다. 그 업무에는 이용할 수 있다.","c":"상","v":1},"공인노2024_33-09-5":{"w":"근로기준법 제43조의3 제1항 단서가 체불사업주의 사망·폐업으로 체불자료 제공의 실효성이 없는 경우 등에는 자료를 제공하지 않을 수 있게 한다.","c":"상","v":1},"공인노2025_34-12-2":{"w":"통상임금은 소정근로의 대가여야 한다. 판례는 소정근로시간을 넘는 근로나 근로계약에서 제공하기로 정하지 않은 근로에 대해 추가로 받는 임금은 소정근로의 대가가 아니어서 통상임금이 아니라고 본다.","c":"중","v":1},"공인노2025_34-12-3":{"w":"근로기준법의 통상임금 규정은 강행규정이다. 판례는 통상임금에 들어갈 수당을 빼기로 한 노사합의로 계산한 금액이 법 기준에 못 미치면 그 미달 범위에서 합의가 무효라고 본다(근로기준법 제15조, 대법원 2013. 12. 18. 선고 2012다89399 전원합의체 판결).","c":"중","v":1},"공인노2025_34-12-4":{"w":"판례는 1개월을 넘는 기간마다 정기적으로 지급되더라도 소정근로의 대가라는 성질이 사라지지 않는다고 본다. 근로기준법 시행령 제6조 제1항의 '시간급·일급·주급·월급'은 예시이므로 지급 주기만으로 통상임금에서 빠지지 않는다.","c":"중","v":1},"공인노2025_34-12-5":{"w":"근로기준법 시행령 제6조 제1항의 통상임금 정의다.","c":"상","v":1},"공인노2025_34-13-1":{"w":"근로기준법 제46조 제1항 단서가 평균임금의 100분의 70이 통상임금을 넘으면 통상임금을 휴업수당으로 지급할 수 있게 한다.","c":"상","v":1},"공인노2025_34-13-2":{"w":"판례는 근로기준법 제46조의 휴업을 사업 전부·일부 휴업뿐 아니라 근로자가 근로를 제공할 의사가 있는데도 의사에 반하여 취업이 거부되거나 불가능해진 경우까지 포함하는 개념으로 본다.","c":"중","v":1},"공인노2025_34-13-3":{"w":"판례는 사용자가 자신의 귀책사유인 경영상 필요로 개별 근로자에게 대기발령을 하여 근로를 제공하지 못하게 한 것도 근로기준법 제46조의 휴업이라고 보아 휴업수당 지급 의무를 인정한다.","c":"중","v":1},"공인노2025_34-13-4":{"w":"근로기준법 제46조 제2항이 부득이한 사유로 사업 계속이 불가능해 노동위원회의 승인을 받으면 기준에 못 미치는 휴업수당을 지급할 수 있게 한다.","c":"상","v":1},"공인노2026_35-04-1":{"w":"근로기준법 제43조 제1항 단서가 법령 또는 단체협약에 특별한 규정이 있으면 임금 일부 공제나 통화 이외의 것으로 지급을 허용한다. 취업규칙이나 근로계약은 여기에 들지 않는다.","c":"상","v":1},"공인노2026_35-04-2":{"w":"판례는 근로자의 동의를 얻은 상계는 그 동의가 자유로운 의사에 터잡은 것이라고 인정할 합리적 이유가 객관적으로 존재하면 전액불 원칙(근로기준법 제43조 제1항)에 어긋나지 않는다고 본다(대법원 2001. 10. 23. 선고 2001다25184 판결).","c":"중","v":1},"공인노2026_35-04-3":{"w":"판례는 전액불 원칙상 대출금·불법행위 채권으로 임금채권과 상계할 수 없다고 본다. 다만 초과지급된 임금의 반환채권은 시기·금액·방법이 근로자의 경제생활을 해치지 않는 범위에서 상계할 수 있다(대법원 2010. 5. 20. 선고 2007다90760 전원합의체 판결).","c":"중","v":1},"공인노2026_35-04-5":{"w":"판례는 근로기준법 제43조 제1항의 직접불 원칙상 임금채권 양수인도 사용자에게 직접 지급을 청구할 수 없다고 본다(대법원 1988. 12. 13. 선고 87다카2803 전원합의체 판결).","c":"중","v":1},"공인노2017_26-12-4":{"w":"근로기준법 제52조는 선택적 근로시간제 적용에서 15세 이상 18세 미만 근로자만 제외한다. 임신 중인 여성을 제외하는 것은 탄력적 근로시간제(제51조 제3항, 제51조의2 제6항)다.","c":"상","v":1},"공인노2019_28-08-1":{"w":"판례는 연차휴가를 사용할 권리는 다른 정함이 없으면 전년도 1년간의 근로를 마친 다음 날 발생한다고 본다(대법원 2018. 6. 28. 선고 2016다48297 판결). 근로기준법 제60조 제1항의 '1년간' 근로가 요건이다.","c":"중","v":1},"공인노2019_28-08-2":{"w":"판례는 연차휴가를 사용하기 전에 퇴직 등으로 근로관계가 끝나도 이미 발생한 휴가에 대한 연차휴가수당 청구권은 그대로 남는다고 본다. 근로관계 종료로 소멸하는 것은 휴가를 쓸 권리뿐이다.","c":"중","v":1},"공인노2019_28-08-3":{"w":"판례는 연차휴가수당은 사용하지 않은 휴가에 대한 보상일 뿐 휴일에 근로한 대가가 아니므로 근로기준법 제56조의 휴일근로 가산수당이 적용되지 않는다고 본다.","c":"중","v":1},"공인노2019_28-08-5":{"w":"판례는 연차휴가권을 취득한 날부터 1년(근로기준법 제60조 제7항의 사용기간)이 지나 휴가 불실시가 확정된 다음 날부터 수당청구권의 소멸시효가 진행한다고 본다. 시효기간은 제49조에 따라 3년이다.","c":"중","v":1},"공인노2022_31-07-5":{"w":"근로기준법 제57조가 근로자대표와의 서면 합의로 연장·야간·휴일근로에 대한 임금 지급을 갈음하여 휴가(보상휴가)를 줄 수 있게 한다.","c":"상","v":1},"공인노2022_31-12-1":{"w":"근로기준법 제60조 제2항이 계속 근로기간 1년 미만인 근로자에게 1개월 개근 시 1일의 유급휴가를 주게 한다.","c":"상","v":1},"공인노2022_31-12-2":{"w":"근로기준법 제60조 제2항이 1년간 80퍼센트 미만 출근한 근로자에게도 1개월 개근 시 1일의 유급휴가를 주게 한다.","c":"상","v":1},"공인노2022_31-12-4":{"w":"근로기준법 제60조 제4항이 3년 이상 근로자의 가산휴가를 포함한 총 휴가 일수를 25일 한도로 정한다.","c":"상","v":1},"공인노2022_31-12-5":{"w":"근로기준법 제62조(유급휴가의 대체)가 근로자대표와의 서면 합의로 연차 유급휴가일을 갈음하여 특정 근로일에 휴무시킬 수 있게 한다.","c":"상","v":1},"공인노2024_33-10-2":{"w":"근로기준법 제55조 제1항이 1주에 평균 1회 이상의 유급휴일을 보장하게 한다. 시행령 제30조 제1항은 1주 소정근로일을 개근한 자에게 주도록 정한다.","c":"상","v":1},"공인노2024_33-10-3":{"w":"근로기준법 제54조 제1항이 근로시간 4시간인 경우 30분 이상, 8시간인 경우 1시간 이상의 휴게시간을 근로시간 도중에 주게 한다.","c":"상","v":1},"공인노2024_33-10-4":{"w":"근로기준법 제60조 제2항이 계속 근로기간 1년 미만인 근로자에게 1개월 개근 시 1일의 유급휴가를 주게 한다.","c":"상","v":1},"공인노2024_33-10-5":{"w":"근로기준법 제63조 제3호가 감시 또는 단속적으로 근로하는 사람으로서 사용자가 고용노동부장관의 승인을 받은 사람에게 근로시간·휴게·휴일 규정을 적용하지 않는다고 정한다.","c":"상","v":1},"공인노2024_33-12-1":{"w":"근로기준법 제56조 제3항이 야간근로(오후 10시~다음 날 오전 6시)에 통상임금의 100분의 50 이상을 가산하게 한다.","c":"상","v":1},"공인노2024_33-12-2":{"w":"근로기준법 제57조가 근로자대표와의 서면 합의로 연장·야간·휴일근로 임금 지급을 갈음하여 휴가를 줄 수 있게 한다.","c":"상","v":1},"공인노2024_33-12-3":{"w":"근로기준법 제70조 제2항 제1호가 18세 미만자는 그 동의가 있고 고용노동부장관의 인가를 받으면 야간·휴일근로를 시킬 수 있게 한다.","c":"상","v":1},"공인노2024_33-12-5":{"w":"근로기준법 제70조 제2항 제3호가 임신 중의 여성이 명시적으로 청구하고 고용노동부장관의 인가를 받으면 야간·휴일근로를 시킬 수 있게 한다.","c":"상","v":1},"공인노2025_34-14-1":{"w":"근로기준법 제60조 제2항이 계속 근로기간 1년 미만인 근로자에게 1개월 개근 시 1일의 유급휴가를 주게 한다.","c":"상","v":1},"공인노2025_34-14-3":{"w":"근로기준법 시행령 제33조가 연차 유급휴가 임금을 유급휴가를 주기 전이나 준 직후의 임금지급일에 지급하게 한다.","c":"상","v":1},"공인노2025_34-14-4":{"w":"근로기준법 제60조 제6항 제1호가 업무상 부상·질병으로 휴업한 기간을 출근한 것으로 보게 한다.","c":"상","v":1},"공인노2025_34-14-5":{"w":"근로기준법 제62조(유급휴가의 대체)가 근로자대표와의 서면 합의로 연차 유급휴가일을 갈음하여 특정 근로일에 휴무시킬 수 있게 한다.","c":"상","v":1},"공인노2026_35-02-1":{"w":"근로기준법 제52조 제1항이 취업규칙 등으로 업무 시작·종료 시각을 근로자 결정에 맡긴 근로자에 대해 근로자대표와의 서면 합의로 선택적 근로시간제를 도입하게 한다.","c":"상","v":1},"공인노2026_35-02-2":{"w":"근로기준법 제52조 제1항 본문이 정산기간을 1개월 이내로 하되 신상품 또는 신기술의 연구개발 업무는 3개월 이내로 할 수 있게 한다.","c":"상","v":1},"공인노2026_35-02-3":{"w":"근로기준법 제52조 제1항은 15세 이상 18세 미만 근로자만 선택적 근로시간제에서 뺀다. 임신 중인 여성 제외는 탄력적 근로시간제(제51조 제3항)에만 있다.","c":"상","v":1},"공인노2026_35-02-5":{"w":"근로기준법 제52조 제1항 제6호와 시행령 제29조 제1항이 서면 합의 사항으로 표준근로시간(유급휴가 등 계산 기준이 되는 1일 근로시간)을 정한다.","c":"상","v":1},"공인노2026_35-05-1":{"w":"근로기준법 제55조 제1항과 시행령 제30조 제1항이 1주 소정근로일을 개근한 근로자에게 1주에 평균 1회 이상의 유급휴일을 주게 한다.","c":"상","v":1},"공인노2026_35-05-2":{"w":"근로기준법 제54조 제1항은 근로시간 4시간마다 30분 이상의 휴게를 근로시간 도중에 주게 한다. 연장근로도 근로시간이므로 4시간 연장근로 도중에 30분 이상의 휴게를 주어야 한다.","c":"중","v":1},"공인노2026_35-05-3":{"w":"연차휴가미사용수당도 임금이므로 근로기준법 제49조의 3년 소멸시효가 적용된다. 시효는 휴가 사용기간 1년이 지난 다음 날부터 진행한다.","c":"상","v":1},"공인노2026_35-05-5":{"w":"근로기준법 제63조 제4호가 사업의 종류와 관계없이 관리·감독 업무 또는 기밀 취급 업무 종사자에게 근로시간·휴게·휴일 규정을 적용하지 않는다고 정한다. 고용노동부장관 승인은 필요 없다.","c":"상","v":1},"공인노2017_26-06-1":{"w":"판례는 징계권 행사가 재량이더라도 같은 정도의 비위에 일반적으로 적용해 온 기준과 어긋나게 공평을 잃은 과중한 징계는 재량권 남용으로 위법하다고 본다(형평의 원칙).","c":"중","v":1},"공인노2017_26-06-2":{"w":"판례는 단체협약이나 취업규칙에 소명 기회를 주도록 정한 경우 그 기회를 주면 되고 근로자가 실제로 소명하지 않았더라도 절차 위반이 아니라고 본다.","c":"중","v":1},"공인노2017_26-06-3":{"w":"판례는 여러 징계사유 중 일부가 인정되지 않아도 인정되는 사유만으로 징계의 타당성을 인정하기에 충분하면 그 징계를 유지한다.","c":"중","v":1},"공인노2017_26-06-5":{"w":"판례는 징계위원회 출석·소명 기회를 주도록 정했다면 통보 시기·방법 규정이 없어도 소명 자료를 준비할 상당한 기간을 두고 개최 일시·장소를 알려야 하고 그렇지 않은 징계는 절차상 하자로 무효라고 본다.","c":"중","v":1},"공인노2017_26-07-1":{"w":"해고의 서면통지(근로기준법 제27조)는 근로기준법 시행령 제7조 [별표 1]의 상시 4명 이하 사업 적용 규정에 없다. 4명 이하 사업장에서는 서면 통지 의무가 없다.","c":"상","v":1},"공인노2017_26-07-2":{"w":"영업양도 시 근로관계는 원칙적으로 포괄승계된다. 판례는 일부 근로자를 승계에서 빼는 특약은 실질적으로 해고와 같으므로 근로기준법 제23조 제1항의 정당한 이유가 있어야 유효하다고 본다.","c":"중","v":1},"공인노2017_26-07-3":{"w":"판례는 시용기간 만료 시 본계약 거부를 사용자에게 유보된 해약권의 행사로 보아 보통의 해고보다 넓게 인정한다. 다만 객관적으로 합리적인 이유와 사회통념상 상당성은 필요하다.","c":"중","v":1},"공인노2017_26-07-5":{"w":"판례는 근로계약·취업규칙 등에 갱신 요건이 있거나 여러 사정에 비추어 갱신 기대권이 인정되면 합리적 이유 없는 갱신 거절은 부당해고와 같이 효력이 없고 종전 근로계약이 갱신된 것과 같다고 본다(대법원 2011. 4. 14. 선고 2007두1729 판결).","c":"중","v":1},"공인노2019_28-12-1":{"w":"판례는 사생활 비행은 원칙적으로 징계 대상이 아니지만 기업활동에 직접 관련되거나 기업의 사회적 평가를 해칠 염려가 있으면 정당한 징계사유가 될 수 있다고 본다.","c":"중","v":1},"공인노2019_28-12-3":{"w":"판례는 단체협약에서 조합 간부 징계 시 노동조합과 합의하도록 정했다면 그 합의 없이 한 징계는 원칙적으로 무효라고 본다. 노조가 합의권을 남용하거나 포기한 경우는 예외다.","c":"중","v":1},"공인노2019_28-12-4":{"w":"판례는 징계 과정의 절차 하자가 재심 과정에서 보완되면 그 하자가 치유된다고 본다. 원 징계와 재심 절차를 하나의 징계절차로 보기 때문이다.","c":"중","v":1},"공인노2019_28-12-5":{"w":"근로기준법 제95조가 감급 1회 금액은 평균임금 1일분의 2분의 1을, 총액은 1임금지급기 임금 총액의 10분의 1을 넘지 못하게 한다.","c":"상","v":1},"공인노2019_28-14-1":{"w":"판례는 긴박한 경영상 필요(근로기준법 제24조 제1항)를 판단할 때 일부 영업부문이나 영업소의 수지만 볼 것이 아니라 법인 전체의 경영사정을 종합해 판단해야 한다고 본다. 다만 그 부문이 독립적으로 운영되는 등 특별한 사정이 있으면 예외가 있다.","c":"중","v":1},"공인노2019_28-14-3":{"w":"근로기준법 제24조 제4항과 시행령 제10조가 일정 규모 이상 인원을 경영상 이유로 해고하려면 최초 해고 30일 전까지 고용노동부장관에게 신고하게 한다.","c":"상","v":1},"공인노2019_28-14-4":{"w":"근로기준법 제24조 제1항 후단이 경영 악화를 방지하기 위한 사업의 양도·인수·합병을 긴박한 경영상 필요가 있는 것으로 본다.","c":"상","v":1},"공인노2019_28-14-5":{"w":"판례는 사용자가 근로자대표와 성실하게 협의해 정리해고 실시에 관한 합의에 이르렀다면 그 사정도 해고회피노력(근로기준법 제24조 제2항)을 판단할 때 참작해야 한다고 본다.","c":"중","v":1},"공인노2022_31-11-1":{"w":"판례는 징계사유로 삼지 않은 비위행위라도 평소 소행·근무성적·징계사유 전후의 비위사실 등은 징계양정의 참작자료로 삼을 수 있다고 본다.","c":"중","v":1},"공인노2022_31-11-3":{"w":"판례는 대기발령이 정당한 사유로 이루어졌더라도 그 기간은 합리적 범위 내여야 하며 사유가 없어졌는데도 부당하게 장기간 유지하면 정당한 이유가 없다고 본다.","c":"중","v":1},"공인노2022_31-11-4":{"w":"판례는 여러 징계사유 중 일부가 인정되지 않아도 인정되는 다른 사유만으로 징계의 타당성을 인정하기에 충분하면 그 징계를 위법하다고 보지 않는다.","c":"중","v":1},"공인노2022_31-11-5":{"w":"판례는 단체협약에서 조합 간부 징계 시 노동조합과 합의하도록 정했다면 그 합의 없이 한 징계는 원칙적으로 무효라고 본다. 노조가 합의권을 남용하거나 포기한 경우는 예외다.","c":"중","v":1},"공인노2024_33-05-1":{"w":"판례는 전보·전직 등 인사명령을 원칙적으로 인사권자인 사용자의 고유권한으로 보아 업무상 필요한 범위에서 상당한 재량을 인정한다. 근로기준법 제23조 제1항에 위반되거나 권리남용이면 무효다.","c":"중","v":1},"공인노2024_33-05-2":{"w":"판례는 전직처분의 정당성을 업무상 필요성과 생활상 불이익을 비교해 판단하고 근로자 측과 성실한 협의를 거쳤는지는 정당한 이유를 판단하는 요소의 하나일 뿐이라고 본다. 협의를 거치지 않았다는 것만으로 당연 무효가 되지는 않는다.","c":"중","v":1},"공인노2024_33-05-4":{"w":"판례는 사생활 비행도 기업활동에 직접 관련되거나 기업의 사회적 평가를 훼손할 염려가 있으면 정당한 징계사유가 될 수 있다고 본다.","c":"중","v":1},"공인노2024_33-05-5":{"w":"판례는 징계의 정당성에 대한 증명책임을 사용자에게 지운다. 일부 인정된 징계사유만으로 징계의 타당성을 인정하기에 충분하다는 점도 사용자가 증명해야 한다.","c":"중","v":1},"공인노2024_33-06-1":{"w":"근로기준법 제24조 제1항 후단이 경영 악화를 방지하기 위한 사업의 양도·인수·합병을 긴박한 경영상 필요가 있는 것으로 본다.","c":"상","v":1},"공인노2024_33-06-2":{"w":"판례는 근로기준법 제24조의 각 요건(긴박한 경영상 필요·해고회피노력·합리적 공정한 대상자 선정·성실한 협의)이 고정된 것이 아니라 구체적 사건에서 서로 관련되어 유동적이므로 개별 사정을 종합적으로 고려해 정당성을 판단한다고 본다.","c":"중","v":1},"공인노2024_33-06-3":{"w":"판례는 근로자 과반수로 조직된 노동조합과 협의했다면 해고 대상인 일정 급수 이상 직원들만의 대표를 따로 뽑아 협의하지 않았다는 이유로 정리해고를 무효로 볼 수 없다고 본다. 근로기준법 제24조 제3항의 협의 상대는 과반수 노조다.","c":"중","v":1},"공인노2024_33-06-5":{"w":"근로기준법 제25조 제1항이 경영상 이유로 해고한 날부터 3년 이내 같은 업무에 근로자를 채용하려면 해고된 근로자를 우선 고용하게 한다. 판례는 이를 어기면 의무가 발생한 때부터 고용관계가 성립할 때까지의 임금 상당 손해배상을 청구할 수 있다고 본다(대법원 2020. 11. 26. 선고 2016다13437 판결).","c":"중","v":1},"공인노2024_33-07-1":{"w":"판례가 정한 영업양도의 정의다. 일정한 영업목적으로 조직화된 업체를 동일성을 유지하면서 일체로 이전해야 하므로 단순한 영업재산 양도와 구별된다.","c":"중","v":1},"공인노2024_33-07-3":{"w":"판례는 영업 전부 양도 시 근로관계는 원칙적으로 포괄승계되므로 정당한 이유 없이 해고된 근로자를 승계에서 빼는 특약은 근로기준법 제23조 제1항의 정당한 이유가 있어야 유효하다고 본다. 영업양도 자체만으로는 정당한 이유가 되지 않는다.","c":"중","v":1},"공인노2024_33-07-4":{"w":"판례는 영업재산 일부를 남겨 두고 양도해도 양도된 부분만으로 종래의 조직이 유지된다고 사회관념상 인정되면 영업양도라고 본다. 영업양도 여부는 조직이 유지되는지로 판단한다.","c":"중","v":1},"공인노2024_33-07-5":{"w":"판례는 영업양도 시 근로자가 승계를 반대하는 의사를 표시하면 그 근로관계는 양수 기업으로 승계되지 않고 양도 기업과 존속한다고 본다. 근로자 의사에 반해 사용자를 바꿀 수 없기 때문이다(민법 제657조 제1항 참조).","c":"중","v":1},"공인노2025_34-09-1":{"w":"판례는 취업규칙에 정한 해고사유에 해당하더라도 근로기준법 제23조 제1항의 정당한 이유, 곧 사회통념상 고용관계를 계속할 수 없을 정도로 근로자에게 책임 있는 사유가 있어야 해고가 정당하다고 본다.","c":"중","v":1},"공인노2025_34-09-2":{"w":"판례는 정년퇴직 근로자에게 기간제근로자로 재고용될 기대권이 인정되는데 사용자가 합리적 이유 없이 재고용을 거절하면 부당해고와 마찬가지로 근로자에게 효력이 없다고 본다(대법원 2023. 6. 1. 선고 2018다275925 판결).","c":"중","v":1},"공인노2025_34-09-3":{"w":"판례는 해고·징계의 정당성에 대한 증명책임을 사용자에게 지운다. 일부 인정된 징계사유만으로 징계가 타당하다는 점도 사용자가 증명해야 한다.","c":"중","v":1},"공인노2025_34-09-4":{"w":"판례는 해고를 근로자 의사와 관계없이 사용자가 일방적으로 근로관계를 끝내는 것으로 보고 명시적 의사표시뿐 아니라 묵시적 의사표시로도 할 수 있다고 본다. 다만 근로기준법 제27조에 따라 서면 통지가 없으면 효력이 없다.","c":"중","v":1},"공인노2026_35-09-1":{"w":"판례는 긴박한 경영상 필요가 있었는지를 정리해고를 할 당시의 사정을 기준으로 판단한다. 해고 뒤의 경영 호전 등은 판단 기준이 아니다.","c":"중","v":1},"공인노2026_35-09-2":{"w":"판례는 근로기준법 제24조 제1항의 긴박한 경영상 필요에 장래의 위기에 미리 대처하기 위한 인원삭감도 포함되지만 그 인원삭감이 객관적으로 합리적이어야 한다고 본다.","c":"중","v":1},"공인노2026_35-09-4":{"w":"판례는 기업 운영에 필요한 인력 규모나 잉여인력 판단은 상당한 합리성이 있는 한 경영판단의 문제이므로 특별한 사정이 없으면 경영자의 판단을 존중해야 한다고 본다.","c":"중","v":1},"공인노2026_35-09-5":{"w":"판례는 해고대상자 선정기준이 단체협약·취업규칙에 미리 정해져 있지 않다면 근로자에게 귀책사유가 없는 해고임을 고려해 사회적·경제적 보호 필요성이 높은 근로자를 배려하는 합리적이고 공정한 기준을 세워야 한다고 본다(근로기준법 제24조 제2항).","c":"중","v":1},"공인노2017_26-01-1":{"w":"근로기준법 제33조 제2항이 이행강제금을 부과하기 30일 전까지 부과·징수한다는 뜻을 사용자에게 미리 문서로 알리게 한다.","c":"상","v":1},"공인노2017_26-01-2":{"w":"근로기준법 시행령 제12조 제1항이 이행강제금 부과통지를 받은 날부터 15일 이내의 납부기한을 정하게 한다.","c":"상","v":1},"공인노2017_26-01-3":{"w":"근로기준법 제33조 제6항이 구제명령을 이행하면 새 이행강제금은 부과하지 않되 이행 전에 이미 부과된 이행강제금은 징수하게 한다.","c":"상","v":1},"공인노2017_26-01-5":{"w":"근로기준법 제33조 제7항이 납부기한까지 내지 않으면 기간을 정해 독촉하고 그 기간에도 내지 않으면 국세 체납처분의 예에 따라 징수할 수 있게 한다.","c":"상","v":1},"공인노2017_26-09-2":{"w":"근로기준법 제31조 제2항이 중앙노동위원회 재심판정에 대해 재심판정서를 송달받은 날부터 15일 이내에 행정소송법에 따라 소를 제기할 수 있게 한다.","c":"상","v":1},"공인노2017_26-09-3":{"w":"근로기준법 제32조가 구제명령·기각결정·재심판정은 재심 신청이나 행정소송 제기로 효력이 정지되지 않는다고 정한다.","c":"상","v":1},"공인노2017_26-09-4":{"w":"근로기준법 시행령 제14조 제1호가 사용자가 객관적으로 노력했으나 근로자의 소재불명 등으로 구제명령 이행이 어려운 것이 명백하면 직권 또는 사용자 신청으로 그 사유가 없어진 뒤에 이행강제금을 부과할 수 있게 한다.","c":"상","v":1},"공인노2017_26-09-5":{"w":"근로기준법 제30조 제1항이 부당해고등이 성립하면 구제명령을, 성립하지 않으면 구제신청 기각결정을 하게 한다.","c":"상","v":1},"공인노2019_28-13-1":{"w":"근로기준법 제30조 제1항이 심문을 끝내고 부당해고등이 성립한다고 판정하면 사용자에게 구제명령을 하게 한다.","c":"상","v":1},"공인노2019_28-13-2":{"w":"근로기준법 제30조 제2항이 판정·구제명령·기각결정을 사용자와 근로자에게 각각 서면으로 통지하게 한다.","c":"상","v":1},"공인노2019_28-13-3":{"w":"근로기준법 제31조 제1항이 지방노동위원회 구제명령·기각결정에 불복하면 통지받은 날부터 10일 이내에 중앙노동위원회에 재심을 신청할 수 있게 한다.","c":"상","v":1},"공인노2019_28-13-5":{"w":"근로기준법 제32조가 구제명령·기각결정·재심판정은 재심 신청이나 행정소송 제기로 효력이 정지되지 않는다고 정한다.","c":"상","v":1},"공인노2022_31-10-5":{"w":"근로기준법 제33조 제7항이 납부기한까지 내지 않으면 기간을 정해 독촉하고 그 기간에도 내지 않으면 국세 체납처분의 예에 따라 징수할 수 있게 한다.","c":"상","v":1},"공인노2025_34-02-3":{"w":"근로기준법 제33조 제1항이 이행기한까지 구제명령을 이행하지 않은 사용자에게 3천만원 이하의 이행강제금을 부과하게 한다.","c":"상","v":1},"공인노2026_35-03-2":{"w":"근로기준법 제33조 제1항이 이행기한까지 구제명령을 이행하지 않은 사용자에게 3천만원 이하의 이행강제금을 부과하게 한다.","c":"상","v":1},"공인노2026_35-03-3":{"w":"근로기준법 시행령 제14조 제2호가 천재·사변 그 밖의 부득이한 사유로 구제명령 이행이 어려우면 직권 또는 사용자 신청으로 그 사유가 없어진 뒤에 이행강제금을 부과할 수 있게 한다.","c":"상","v":1},"공인노2026_35-03-4":{"w":"근로기준법 제31조 제1항이 지방노동위원회 구제명령에 불복하면 구제명령서를 통지받은 날부터 10일 이내에 중앙노동위원회에 재심을 신청할 수 있게 한다.","c":"상","v":1},"공인노2026_35-03-5":{"w":"근로기준법 제29조 제1항이 구제신청을 받은 노동위원회에 지체 없이 필요한 조사와 관계 당사자 심문을 하게 한다.","c":"상","v":1},"공인노2019_28-09-1":{"w":"근로기준법 제93조는 취업규칙을 하나만 두라고 하지 않는다. 판례와 행정해석은 근로조건·근로형태·직종 등의 특수성에 따라 일부 근로자에게 적용되는 별도의 취업규칙 작성을 허용한다.","c":"중","v":1},"공인노2019_28-09-3":{"w":"판례는 불이익변경이 일부 근로자 집단에만 직접 불이익하더라도 장래 다른 집단에도 적용될 것이 예상되면 그 집단을 포함한 근로자 전체가 근로기준법 제94조 제1항 단서의 동의 주체가 된다고 본다.","c":"중","v":1},"공인노2019_28-09-4":{"w":"판례는 취업규칙 불이익변경 절차를 거치지 않았더라도 노동조합이 그 취업규칙에 따르기로 하는 단체협약을 맺으면 단체협약의 적용을 받는 기존 근로자에게 변경된 취업규칙이 적용된다고 본다.","c":"중","v":1},"공인노2019_28-09-5":{"w":"판례는 동의 없이 불이익하게 바뀐 취업규칙도 변경 후 새로 들어온 근로자에게는 적용된다고 본다. 현행 법규적 효력을 가진 취업규칙은 변경된 취업규칙이고 기존 근로자에게만 기득이익 보호를 위해 종전 규칙이 적용된다(대법원 1992. 12. 22. 선고 91다45165 전원합의체 판결).","c":"중","v":1},"공인노2022_31-02-5":{"w":"근로기준법 제76조의3 제6항이 직장 내 괴롭힘 발생 사실을 신고한 근로자와 피해근로자등에게 해고나 그 밖의 불리한 처우를 금지한다.","c":"상","v":1},"공인노2022_31-03-1":{"w":"근로기준법 제101조 제1항이 근로조건 기준을 확보하기 위해 고용노동부와 소속 기관에 근로감독관을 두게 한다.","c":"상","v":1},"공인노2022_31-03-2":{"w":"근로기준법 제102조 제1항이 근로감독관에게 사업장 현장조사, 장부·서류 제출 요구, 사용자와 근로자 심문 권한을 준다.","c":"상","v":1},"공인노2022_31-03-3":{"w":"근로기준법 제102조 제2항이 의사인 근로감독관이나 위촉받은 의사에게 취업 금지 질병에 걸릴 의심이 있는 근로자를 검진할 권한을 준다.","c":"상","v":1},"공인노2022_31-03-4":{"w":"근로기준법 제103조가 근로감독관은 직무상 알게 된 비밀을 엄수하게 하고 그만둔 경우에도 같다고 정한다.","c":"상","v":1},"공인노2022_31-08-1":{"w":"판례는 집단적 동의로 취업규칙이 불리하게 바뀌어도 근로자의 개별 동의가 없으면 근로기준법 제4조의 근로조건 자유결정 원칙상 더 유리한 근로계약이 우선한다고 본다(대법원 2019. 11. 14. 선고 2018다200709 판결).","c":"상","v":1},"공인노2022_31-08-2":{"w":"근로기준법 제94조 제1항 본문이 취업규칙 작성·변경 시 과반수 노동조합의 의견을, 그런 노동조합이 없으면 근로자 과반수의 의견을 듣게 한다.","c":"상","v":1},"공인노2022_31-08-4":{"w":"표창과 제재에 관한 사항은 근로기준법 제93조 제12호의 필요적 기재사항이다. 이를 빠뜨린 취업규칙은 법령에 어긋나므로 고용노동부장관이 제96조 제2항에 따라 변경을 명할 수 있다.","c":"중","v":1},"공인노2022_31-08-5":{"w":"판례는 동의 없이 불이익하게 바뀐 취업규칙도 변경 후 새로 들어온 근로자에게는 적용된다고 본다. 현행 법규적 효력을 가진 취업규칙은 변경된 취업규칙이다(대법원 1992. 12. 22. 선고 91다45165 전원합의체 판결).","c":"중","v":1},"공인노2024_33-15-1":{"w":"대법원 2023. 5. 11. 선고 2017다35588 전원합의체 판결은 집단적 동의권 남용이라는 특별한 사정이 없으면 사회통념상 합리성만으로 동의 없는 불이익변경의 유효성을 인정할 수 없다고 하여 종전 합리성 법리를 폐기했다.","c":"상","v":1},"공인노2024_33-15-2":{"w":"대법원 2023. 5. 11. 선고 2017다35588 전원합의체 판결은 근로기준법 제94조 제1항 단서의 집단적 동의권이 변경 내용의 타당성이나 합리성으로 대체될 수 없다고 보았다.","c":"상","v":1},"공인노2024_33-15-4":{"w":"대법원 2023. 5. 11. 선고 2017다35588 전원합의체 판결은 노동조합이나 근로자들이 집단적 동의권을 남용한 경우에는 동의가 없어도 불리한 변경의 유효성을 인정할 수 있다고 보았다.","c":"상","v":1},"공인노2024_33-15-5":{"w":"대법원 2023. 5. 11. 선고 2017다35588 전원합의체 판결이 집단적 동의권을 이렇게 설명했다. 사용자의 일방적 변경 권한을 제한하고 헌법 제32조 제3항과 근로기준법 제4조의 노사대등결정 원칙을 실현하는 절차적 권리라는 것이다.","c":"상","v":1},"공인노2024_33-16-1":{"w":"근로기준법 제97조 전단의 내용이다. 무효로 된 부분은 같은 조 후단에 따라 취업규칙에 정한 기준으로 채운다.","c":"상","v":1},"공인노2024_33-16-3":{"w":"근로기준법 제93조가 취업규칙 작성·신고 의무를 사용자에게 지우고 제94조는 근로자 측 의견 청취·동의를 절차 요건으로 둔다. 판례도 작성·변경 권한은 원칙적으로 사용자에게 있다고 본다.","c":"중","v":1},"공인노2024_33-16-4":{"w":"판례는 취업규칙을 사용자가 정한 법규범으로 보아 문언의 객관적 의미에 따라 해석하고 그 의미를 벗어나는 해석은 신중하고 엄격해야 한다고 본다. 근로자에게 불리한 해석은 더욱 그렇다.","c":"중","v":1},"공인노2024_33-16-5":{"w":"판례는 집단적 동의 없이 불리하게 바뀐 취업규칙도 현행 법규적 효력을 가진 취업규칙은 변경된 취업규칙이라고 본다. 기존 근로자에게는 기득이익 범위에서 종전 규칙이 적용될 뿐이다(대법원 1992. 12. 22. 선고 91다45165 전원합의체 판결).","c":"중","v":1},"공인노2025_34-07-1":{"w":"근로기준법 제98조 제2항이 사용자는 기숙사 생활의 자치에 필요한 임원 선거에 간섭하지 못한다고 정한다.","c":"상","v":1},"공인노2025_34-07-3":{"w":"근로기준법 시행령 제58조가 기숙사 침실의 넓이를 1인당 2.5제곱미터 이상으로 정한다.","c":"상","v":1},"공인노2025_34-07-4":{"w":"근로기준법 시행령 제56조가 소음·진동이 심한 장소, 자연재해 우려가 현저한 장소 등 안전하고 쾌적한 거주가 어려운 곳에 기숙사를 설치하지 못하게 한다.","c":"상","v":1},"공인노2025_34-07-5":{"w":"근로기준법 제99조 제4항이 사용자와 기숙사에 기숙하는 근로자 모두에게 기숙사규칙을 지키게 하고 제116조 제2항 제2호가 제99조 위반에 500만원 이하의 과태료를 정한다.","c":"중","v":1},"공인노2025_34-08-1":{"w":"근로기준법 제108조가 근로감독관의 고의적 위반 묵과를 3년 이하의 징역 또는 5년 이하의 자격정지로 처벌한다.","c":"상","v":1},"공인노2025_34-08-2":{"w":"근로기준법 제107조 제2항 본문이 휴업수당(제46조) 미지급을 반의사불벌죄로 정한다. 다만 명단 공개된 체불사업주가 공개 기간 중에 위반하면 단서에 따라 피해자 의사와 관계없이 공소를 제기할 수 있다.","c":"상","v":1},"공인노2025_34-08-3":{"w":"근로기준법 제111조가 확정된 구제명령이나 구제명령을 내용으로 하는 재심판정을 이행하지 않은 자를 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. 제112조에 따라 노동위원회의 고발이 있어야 공소를 제기할 수 있다.","c":"상","v":1},"공인노2025_34-08-4":{"w":"근로기준법 제116조 제1항 제1호와 시행령 제59조의3이 사용자의 배우자·4촌 이내 혈족·4촌 이내 인척인 근로자가 직장 내 괴롭힘을 한 경우를 사용자의 괴롭힘과 같이 1천만원 이하의 과태료 대상으로 정한다.","c":"상","v":1},"공인노2025_34-10-1":{"w":"근로기준법 제102조 제5항이 근로감독관에게 이 법 위반의 죄에 관한 사법경찰관의 직무를 맡긴다. 직무 범위는 사법경찰관리의 직무를 수행할 자와 그 직무범위에 관한 법률에서 정한다.","c":"상","v":1},"공인노2025_34-10-2":{"w":"근로기준법 제102조 제1항이 근로감독관에게 사업장·기숙사 그 밖의 부속 건물을 현장조사할 권한을 준다.","c":"상","v":1},"공인노2025_34-10-3":{"w":"근로기준법 제102조 제1항이 근로감독관이 사용자와 근로자에 대하여 심문할 수 있다고 정한다.","c":"상","v":1},"공인노2025_34-11-4":{"w":"근로기준법 제76조의3 제5항이 괴롭힘 발생 사실이 확인되면 피해근로자의 의견을 들어 지체 없이 행위자에게 징계·근무장소 변경 등 필요한 조치를 하게 한다.","c":"상","v":1},"공인노2026_35-11-1":{"w":"근로기준법 제102조 제1항이 근로감독관에게 사업장 현장조사와 장부·서류 제출 요구 권한을 준다.","c":"상","v":1},"공인노2026_35-11-2":{"w":"근로기준법 제102조 제2항이 의사인 근로감독관이나 근로감독관의 위촉을 받은 의사에게 취업 금지 질병에 걸릴 의심이 있는 근로자를 검진할 권한을 준다.","c":"상","v":1},"공인노2026_35-11-3":{"w":"근로기준법 제102조 제1항이 근로감독관에게 사용자와 근로자를 심문할 권한을 준다.","c":"상","v":1},"공인노2026_35-11-4":{"w":"근로기준법 제103조가 근로감독관은 직무상 알게 된 비밀을 엄수하게 하고 그만둔 경우에도 같다고 정한다.","c":"상","v":1},"공인노2026_35-12-1":{"w":"지방노동위원회 구제명령은 기간 내 재심 신청이 없으면 근로기준법 제31조 제3항에 따라 확정된다. 확정된 구제명령 불이행은 제111조에 따라 1년 이하의 징역 또는 1천만원 이하의 벌금 대상이다.","c":"상","v":1},"공인노2026_35-12-2":{"w":"근로기준법 제116조 제1항 제1호와 시행령 제59조의3이 사용자의 4촌 이내 혈족인 근로자의 직장 내 괴롭힘도 1천만원 이하의 과태료 대상으로 정한다.","c":"상","v":1},"공인노2026_35-12-3":{"w":"근로기준법 제116조 제2항 제1호가 제13조에 따른 고용노동부장관 등의 요구에 보고·출석을 하지 않거나 거짓 보고를 한 자에게 500만원 이하의 과태료를 부과한다.","c":"상","v":1},"공인노2026_35-12-5":{"w":"근로기준법 제108조가 근로감독관의 고의적 위반 묵과를 3년 이하의 징역 또는 5년 이하의 자격정지로 처벌한다.","c":"상","v":1},"공인노2017_26-13-1":{"w":"근로기준법 제67조 제2항이 친권자·후견인 또는 고용노동부장관에게 미성년자에게 불리한 근로계약의 해지권을 준다.","c":"상","v":1},"공인노2017_26-13-3":{"w":"근로기준법 제68조가 미성년자는 독자적으로 임금을 청구할 수 있다고 정한다. 법정대리인의 동의가 필요 없다.","c":"상","v":1},"공인노2017_26-13-4":{"w":"근로기준법 제66조가 18세 미만인 사람의 연령을 증명하는 가족관계기록사항 증명서와 친권자 또는 후견인의 동의서를 사업장에 갖추어 두게 한다.","c":"상","v":1},"공인노2017_26-13-5":{"w":"근로기준법 시행령 제37조는 제40조의 금지 직종에 취직인허증을 발급하지 못하게 한다. 시행령 [별표 4]의 18세 미만 사용 금지 직종에서 유류 취급 업무는 주유업무를 빼고 있어 주유업무에는 취직인허증을 발급할 수 있다.","c":"중","v":1},"공인노2022_31-06-1":{"w":"근로기준법 제65조 제1항이 임산부와 18세 미만자를 도덕상 또는 보건상 유해·위험한 사업에 사용하지 못하게 한다.","c":"상","v":1},"공인노2022_31-06-3":{"w":"근로기준법 제67조 제3항이 18세 미만인 사람과 근로계약을 체결할 때 제17조의 근로조건을 서면(전자문서 포함)으로 명시하여 교부하게 한다.","c":"상","v":1},"공인노2022_31-06-4":{"w":"근로기준법 제69조 단서가 15세 이상 18세 미만인 사람의 근로시간을 합의로 1일 1시간, 1주 5시간 한도에서 연장할 수 있게 한다. 기본 한도는 1일 7시간, 1주 35시간이다.","c":"상","v":1},"공인노2022_31-06-5":{"w":"근로기준법 제70조 제2항 제1호가 18세 미만자의 동의가 있고 고용노동부장관의 인가를 받으면 야간·휴일근로를 시킬 수 있게 한다.","c":"상","v":1},"공인노2024_33-14-2":{"w":"근로기준법 제74조 제1항이 임신 중의 여성에게 출산 전후를 통하여 90일의 출산전후휴가를 주게 한다. 미숙아 출산은 100일, 다태아 임신은 120일이다.","c":"상","v":1},"공인노2024_33-14-3":{"w":"근로기준법 제74조 제2항과 시행령 제43조 제1항 제2호가 휴가 청구 당시 만 40세 이상인 임신 근로자를 분할 사용 사유로 정한다. 만 42세는 여기에 해당한다.","c":"상","v":1},"공인노2024_33-14-4":{"w":"근로기준법 제74조의2 제1항이 임신한 여성근로자가 모자보건법 제10조의 임산부 정기건강진단 시간을 청구하면 허용하게 한다. 제2항은 이를 이유로 한 임금 삭감을 금지한다.","c":"상","v":1},"공인노2024_33-14-5":{"w":"근로기준법 제65조 제1항이 임산부(임신 중이거나 산후 1년이 지나지 않은 여성)를 도덕상 또는 보건상 유해·위험한 사업에 사용하지 못하게 한다.","c":"상","v":1},"공인노2025_34-04-1":{"w":"근로기준법 시행령 제35조 제3항이 취직인허증 신청은 학교장(의무교육 대상자와 재학 중인 자에 한정)과 친권자 또는 후견인의 서명을 받아 사용자가 될 자와 연명으로 하게 한다.","c":"상","v":1},"공인노2025_34-04-2":{"w":"근로기준법 시행령 제35조 제1항이 취직인허증 대상을 13세 이상 15세 미만으로 하되 예술공연 참가를 위한 경우에는 13세 미만도 받을 수 있게 한다.","c":"상","v":1},"공인노2025_34-04-3":{"w":"근로기준법 시행령 제37조가 제40조의 임산부 등 사용 금지 직종에 대해서는 취직인허증을 발급할 수 없다고 정한다.","c":"상","v":1},"공인노2025_34-04-5":{"w":"근로기준법 시행령 제36조 제2항이 15세 미만인 자를 사용하는 사용자가 취직인허증을 갖추어 두면 법 제66조의 가족관계기록사항 증명서와 친권자·후견인 동의서를 갖춘 것으로 본다.","c":"상","v":1},"공인노2025_34-06-2":{"w":"근로기준법 제69조 단서가 15세 이상 18세 미만인 사람의 근로시간을 합의로 1일 1시간, 1주 5시간 한도에서 연장할 수 있게 한다.","c":"상","v":1},"공인노2025_34-06-3":{"w":"근로기준법 제68조가 미성년자는 독자적으로 임금을 청구할 수 있다고 정한다.","c":"상","v":1},"공인노2025_34-06-4":{"w":"근로기준법 제67조 제2항이 친권자·후견인 또는 고용노동부장관에게 미성년자에게 불리한 근로계약의 해지권을 준다.","c":"상","v":1},"공인노2025_34-06-5":{"w":"근로기준법 제67조 제3항이 18세 미만인 사람과 근로계약을 체결할 때 제17조의 근로조건을 서면(전자문서 포함)으로 명시하여 교부하게 한다. 취업 장소와 종사 업무는 시행령 제8조의 명시 사항이다.","c":"상","v":1},"공인노2026_35-14-1":{"w":"근로기준법 시행령 제35조 제1항 단서가 예술공연 참가를 위한 경우에는 13세 미만인 자도 취직인허증을 받을 수 있게 한다.","c":"상","v":1},"공인노2026_35-14-2":{"w":"근로기준법 제65조 제1항과 시행령 제40조 [별표 4]가 정신건강증진시설 중 정신병원 업무를 18세 미만인 사람의 사용 금지 직종으로 정한다.","c":"중","v":1},"공인노2026_35-14-3":{"w":"근로기준법 제66조가 18세 미만인 사람의 연령을 증명하는 가족관계기록사항 증명서와 친권자 또는 후견인의 동의서를 사업장에 갖추어 두게 한다.","c":"상","v":1},"공인노2026_35-14-4":{"w":"근로기준법 제67조 제2항이 친권자·후견인 또는 고용노동부장관에게 미성년자에게 불리한 근로계약의 해지권을 준다.","c":"상","v":1},"공인노2026_35-15-1":{"w":"근로기준법 제74조 제2항과 시행령 제43조 제1항이 유산 경험을 분할 사용 사유로 정한다. 이때도 출산 후 휴가는 연속 45일(다태아 60일) 이상이어야 한다.","c":"상","v":1},"공인노2026_35-15-2":{"w":"근로기준법 제74조 제1항이 출산전후휴가를 90일, 한 번에 둘 이상 자녀를 임신한 경우 120일로 정한다. 미숙아를 출산한 경우는 100일이다.","c":"상","v":1},"공인노2026_35-15-4":{"w":"근로기준법 제75조(육아 시간)가 생후 1년 미만 유아를 가진 여성 근로자가 청구하면 1일 2회 각각 30분 이상의 유급 수유 시간을 주게 한다.","c":"상","v":1},"공인노2026_35-15-5":{"w":"근로기준법 제74조의2 제1항이 임신한 여성근로자가 모자보건법 제10조의 임산부 정기건강진단 시간을 청구하면 허용하게 한다.","c":"상","v":1},"공인노2026_35-17-1":{"w":"근로기준법 제65조 제1항이 임신 중이거나 산후 1년이 지나지 않은 여성(임산부)을 도덕상 또는 보건상 유해·위험한 사업에 사용하지 못하게 한다.","c":"상","v":1},"공인노2026_35-17-3":{"w":"근로기준법 제71조가 산후 1년이 지나지 않은 여성에게 단체협약이 있더라도 1일 2시간, 1주 6시간, 1년 150시간을 넘는 시간외근로를 시키지 못하게 한다.","c":"상","v":1},"공인노2026_35-17-4":{"w":"근로기준법 제72조 단서와 시행령 제42조가 보건·의료, 보도·취재 등의 업무를 수행하기 위해 일시적으로 필요한 경우에는 여성의 갱내 근로를 허용한다.","c":"상","v":1},"공인노2026_35-17-5":{"w":"근로기준법 제73조가 여성 근로자가 청구하면 월 1일의 생리휴가를 주게 하고 제114조 제1호가 그 위반을 500만원 이하의 벌금으로 처벌한다.","c":"상","v":1},"공인노2017_26-21-2":{"w":"최저임금법 제4조 제1항 후단이 최저임금을 사업의 종류별로 구분하여 정할 수 있게 한다.","c":"상","v":1},"공인노2017_26-21-3":{"w":"최저임금법 제6조 제2항이 최저임금을 이유로 종전의 임금수준을 낮추지 못하게 한다. 위반하면 제28조 제1항의 처벌 대상이다.","c":"상","v":1},"공인노2017_26-21-4":{"w":"최저임금법 제7조와 시행령 제6조가 정신 또는 신체 장애로 근로능력이 현저히 낮은 사람으로서 사용자가 고용노동부장관의 인가를 받은 사람에게 최저임금 효력 규정(제6조)을 적용하지 않는다.","c":"상","v":1},"공인노2017_26-21-5":{"w":"최저임금법 제6조 제7항이 도급인이 책임질 사유로 수급인이 최저임금 미만 임금을 지급하면 도급인이 수급인과 연대책임을 지게 한다.","c":"상","v":1},"공인노2019_28-21-1":{"w":"최저임금법 제5조 제1항 후단이 일·주·월 단위로 최저임금액을 정할 때 시간급으로도 표시하게 한다.","c":"상","v":1},"공인노2019_28-21-2":{"w":"최저임금법 제4조 제1항이 생계비·유사 근로자의 임금·노동생산성·소득분배율 등을 결정 기준으로 하고 사업의 종류별 구분을 허용한다.","c":"상","v":1},"공인노2019_28-21-4":{"w":"최저임금법 제6조 제7항이 도급인이 책임질 사유로 수급인이 최저임금 미만 임금을 지급하면 도급인이 수급인과 연대책임을 지게 한다.","c":"상","v":1},"공인노2019_28-21-5":{"w":"최저임금법 제6조 제3항이 최저임금액에 못 미치는 임금을 정한 근로계약 부분을 무효로 하고 그 부분은 최저임금액과 같은 임금을 지급하기로 정한 것으로 본다.","c":"상","v":1},"공인노2022_31-19-1":{"w":"최저임금법 제3조 제2항이 선원법의 적용을 받는 선원과 그 선박 소유자에게 이 법을 적용하지 않는다고 정한다. 선원은 선원법 제59조의 최저임금을 따른다.","c":"상","v":1},"공인노2022_31-19-2":{"w":"최저임금법 제10조 제1항이 고용노동부장관에게 최저임금을 결정하면 지체 없이 그 내용을 고시하게 한다. 고시된 최저임금은 다음 연도 1월 1일부터 효력이 생긴다(같은 조 제2항).","c":"상","v":1},"공인노2022_31-19-3":{"w":"최저임금법 제4조 제1항 전단이 최저임금 결정기준으로 생계비·유사 근로자의 임금·노동생산성·소득분배율 등을 정한다.","c":"상","v":1},"공인노2022_31-19-5":{"w":"최저임금법 제8조 제1항 후단이 고용노동부장관은 위원회가 심의·의결한 최저임금안에 따라 최저임금을 결정하게 한다.","c":"상","v":1},"공인노2024_33-30-1":{"w":"최저임금법 시행령 제7조가 고용노동부장관에게 매년 3월 31일까지 최저임금위원회에 심의를 요청하게 한다.","c":"상","v":1},"공인노2024_33-30-2":{"w":"최저임금법 제8조 제2항이 위원회가 심의 요청을 받은 날부터 90일 이내에 최저임금안을 의결해 고용노동부장관에게 제출하게 한다.","c":"상","v":1},"공인노2024_33-30-3":{"w":"최저임금법 제8조 제3항이 최저임금안대로 결정하기 어려우면 20일 이내에 이유를 밝혀 10일 이상의 기간을 정해 재심의를 요청할 수 있게 한다.","c":"상","v":1},"공인노2024_33-30-4":{"w":"최저임금법 제8조 제1항 전단이 고용노동부장관에게 매년 8월 5일까지 최저임금을 결정하게 한다.","c":"상","v":1},"공인노2024_33-31-1":{"w":"최저임금법 제15조 제2항이 위원장과 부위원장은 공익위원 중에서 위원회가 선출한다고 정한다.","c":"상","v":1},"공인노2024_33-31-3":{"w":"최저임금법 제14조 제3항이 위원 임기를 3년으로 하고 연임을 허용한다.","c":"상","v":1},"공인노2024_33-31-4":{"w":"최저임금법 제17조 제3항이 따로 정한 경우 외에는 재적위원 과반수 출석과 출석위원 과반수 찬성으로 의결하게 한다. 재심의 재의결(제8조 제5항)은 출석위원 3분의 2 이상 찬성이 필요하다.","c":"상","v":1},"공인노2024_33-31-5":{"w":"최저임금법 제14조 제5항이 위원은 임기가 끝나도 후임자가 임명·위촉될 때까지 직무를 계속 수행한다고 정한다.","c":"상","v":1},"공인노2025_34-30-1":{"w":"최저임금법 제11조와 시행령 제11조 제1항 제2호가 사용자가 근로자에게 알려야 할 사항으로 최저임금에 산입하지 아니하는 임금을 정한다.","c":"상","v":1},"공인노2025_34-30-3":{"w":"최저임금법 제3조 제1항 단서가 동거하는 친족만을 사용하는 사업과 가사 사용인에게 이 법을 적용하지 않는다고 정한다.","c":"상","v":1},"공인노2025_34-30-4":{"w":"최저임금법 제6조 제4항 제1호와 시행규칙 제2조가 연장근로·휴일근로에 대한 임금과 가산임금처럼 소정근로시간이나 소정근로일에 대하여 지급하지 않는 임금을 최저임금 산입 범위에서 뺀다.","c":"상","v":1},"공인노2025_34-30-5":{"w":"최저임금법 제6조 제7항이 도급인이 책임질 사유로 수급인이 최저임금 미만 임금을 지급하면 도급인이 수급인과 연대책임을 지게 한다.","c":"상","v":1},"공인노2025_34-31-1":{"w":"최저임금법 시행령 제19조가 고용노동부장관은 위원회로 하여금 법 제23조의 생계비와 임금실태 조사를 하게 할 수 있다고 정한다.","c":"상","v":1},"공인노2026_35-27-1":{"w":"최저임금법 제3조 제1항이 근로자를 사용하는 모든 사업에 적용하되 동거하는 친족만을 사용하는 사업과 가사 사용인은 제외한다.","c":"상","v":1},"공인노2026_35-27-2":{"w":"최저임금법 제4조 제1항 전단이 생계비·유사 근로자의 임금·노동생산성·소득분배율 등을 최저임금 결정기준으로 정한다.","c":"상","v":1},"공인노2026_35-27-3":{"w":"최저임금법 제5조 제1항 전단이 최저임금액의 단위를 시간·일·주·월로 정한다. 일·주·월 단위면 시간급으로도 표시해야 한다.","c":"상","v":1},"공인노2026_35-27-4":{"w":"최저임금법 시행령 제5조 제2항이 생산고 임금지급제나 도급제 임금은 임금 산정기간의 임금 총액을 그 기간의 총근로시간 수로 나눈 금액을 시간급으로 한다고 정한다.","c":"상","v":1},"공인노2026_35-28-1":{"w":"최저임금법 제14조 제2항이 위원회에 2명의 상임위원을 두고 상임위원은 공익위원이 된다고 정한다.","c":"상","v":1},"공인노2017_26-22-1":{"w":"근로자퇴직급여 보장법 제4조 제1항 단서가 4주 평균 1주 소정근로시간 15시간 미만인 근로자를 퇴직급여제도 설정 대상에서 뺀다.","c":"상","v":1},"공인노2017_26-22-2":{"w":"근로자퇴직급여 보장법 제25조 제1항이 상시 10명 미만 사업에서 개별 근로자의 동의나 요구로 개인형퇴직연금제도를 설정하면 퇴직급여제도를 설정한 것으로 본다.","c":"상","v":1},"공인노2017_26-22-3":{"w":"근로자퇴직급여 보장법 제8조 제2항과 시행령 제3조 제1항 제1호가 무주택자인 근로자의 본인 명의 주택 구입을 퇴직금 중간정산 사유로 정한다.","c":"상","v":1},"공인노2017_26-22-4":{"w":"근로자퇴직급여 보장법 제20조 제1항이 확정기여형 사용자에게 가입자 연간 임금총액의 12분의 1 이상 부담금을 현금으로 계정에 납입하게 한다.","c":"상","v":1},"공인노2019_28-23-2":{"w":"근로자퇴직급여 보장법 제4조 제2항이 하나의 사업에서 급여 및 부담금 산정방법의 적용 등에 차등을 두지 못하게 한다.","c":"상","v":1},"공인노2019_28-23-3":{"w":"근로자퇴직급여 보장법 제4조 제1항 단서가 계속근로기간 1년 미만인 근로자와 4주 평균 1주 소정근로시간 15시간 미만인 근로자를 설정 의무에서 뺀다.","c":"상","v":1},"공인노2019_28-23-4":{"w":"근로자퇴직급여 보장법 제4조 제3항이 퇴직급여제도 설정·변경 시 과반수 노동조합의 동의를, 그런 노조가 없으면 근로자 과반수의 동의를 받게 한다.","c":"상","v":1},"공인노2022_31-20-1":{"w":"근로자퇴직급여 보장법 제4조 제3항이 퇴직급여제도를 설정하거나 다른 종류로 바꿀 때 근로자 과반수가 가입한 노동조합이 있으면 그 노동조합의 동의를 받게 한다.","c":"상","v":1},"공인노2022_31-20-2":{"w":"근로자퇴직급여 보장법 제8조 제2항과 시행령 제3조 제1항 제1호가 무주택자인 근로자의 본인 명의 주택 구입을 중간정산 사유로 정한다.","c":"상","v":1},"공인노2022_31-20-3":{"w":"근로자퇴직급여 보장법 제10조가 퇴직금을 받을 권리의 소멸시효를 3년으로 정한다.","c":"상","v":1},"공인노2022_31-20-4":{"w":"근로자퇴직급여 보장법 제7조 제1항이 중소기업퇴직연금기금제도를 포함한 퇴직연금제도의 급여를 받을 권리를 양도·압류하거나 담보로 제공하지 못하게 한다.","c":"상","v":1},"공인노2024_33-32-1":{"w":"근로자퇴직급여 보장법 제4조 제1항 단서가 계속근로기간 1년 미만인 근로자를 퇴직급여제도 설정 대상에서 뺀다.","c":"상","v":1},"공인노2024_33-32-2":{"w":"근로자퇴직급여 보장법 제4조 제2항이 하나의 사업에서 급여 및 부담금 산정방법의 적용 등에 차등을 두지 못하게 한다.","c":"상","v":1},"공인노2024_33-32-4":{"w":"근로자퇴직급여 보장법 제9조 제1항이 퇴직금을 지급사유 발생일부터 14일 이내에 지급하게 하고 단서에서 특별한 사정이 있으면 당사자 합의로 지급기일을 연장할 수 있게 한다.","c":"상","v":1},"공인노2024_33-32-5":{"w":"근로자퇴직급여 보장법 제10조가 퇴직금을 받을 권리의 소멸시효를 3년으로 정한다.","c":"상","v":1},"공인노2025_34-33-1":{"w":"근로자퇴직급여 보장법 제2조의 확정급여형퇴직연금제도 정의다. 근로자가 받을 급여 수준이 사전에 정해지고 사용자 부담금은 적립금 운용 결과에 따라 달라진다.","c":"상","v":1},"공인노2025_34-33-3":{"w":"근로자퇴직급여 보장법 제13조가 확정급여형 설정 시 근로자대표의 동의를 얻거나 의견을 들어 규약을 작성해 고용노동부장관에게 신고하게 한다.","c":"상","v":1},"공인노2025_34-33-4":{"w":"근로자퇴직급여 보장법 제17조 제1항 제1호가 연금은 55세 이상이고 가입기간 10년 이상인 가입자에게 지급하고 지급기간은 5년 이상으로 정한다.","c":"상","v":1},"공인노2025_34-33-5":{"w":"근로자퇴직급여 보장법 제17조 제1항 제2호가 일시금은 연금수급 요건을 못 갖추었거나 일시금 수급을 원하는 가입자에게 지급하게 한다.","c":"상","v":1},"공인노2026_35-29-1":{"w":"근로자퇴직급여 보장법 제4조 제1항 단서가 4주 평균 1주 소정근로시간 15시간 미만인 근로자를 퇴직급여제도 설정 대상에서 뺀다.","c":"상","v":1},"공인노2026_35-29-2":{"w":"근로자퇴직급여 보장법 제10조가 퇴직금을 받을 권리의 소멸시효를 3년으로 정한다.","c":"상","v":1},"공인노2026_35-29-4":{"w":"근로자퇴직급여 보장법 제17조 제1항 제1호가 연금 수급요건을 55세 이상, 가입기간 10년 이상으로 하고 지급기간을 5년 이상으로 정한다.","c":"상","v":1},"공인노2026_35-29-5":{"w":"근로자퇴직급여 보장법 제17조 제1항 제2호가 일시금은 연금수급 요건을 못 갖추었거나 일시금 수급을 원하는 가입자에게 지급하게 한다.","c":"상","v":1},"공인노2026_35-30-2":{"w":"근로자퇴직급여 보장법 제23조의2 제4항이 운영위원회를 위원장 포함 10명 이상 15명 이내로 구성하고 근로자 대표 위원과 사용자 대표 위원의 수를 같게 한다.","c":"상","v":1},"공인노2026_35-30-3":{"w":"근로자퇴직급여 보장법 제23조의2가 운영위원회의 심의·의결 사항 첫째로 중소기업퇴직연금기금 운용계획 및 지침에 관한 사항을 정한다.","c":"상","v":1},"공인노2026_35-30-4":{"w":"근로자퇴직급여 보장법 제23조의7 제1항이 매년 1회 이상 정기적으로 연간 임금총액의 12분의 1 이상을 현금으로 기금제도사용자부담금계정에 납입하게 한다.","c":"상","v":1},"공인노2026_35-30-5":{"w":"근로자퇴직급여 보장법 제23조의9 단서가 기금제도가입자부담금계정의 가입기간을 계정이 설정된 날부터 급여가 전액 지급된 날까지로 정한다.","c":"상","v":1},"공인노2017_26-18-1":{"w":"남녀고용평등법 제2조 제4호가 근로자를 사업주에게 고용된 사람과 취업할 의사를 가진 사람으로 정의한다. 모집·채용 단계의 구직자도 보호하기 위해서다.","c":"상","v":1},"공인노2017_26-18-2":{"w":"남녀고용평등법 제2조 제3호의 적극적 고용개선조치 정의다. 같은 조 제1호 단서 다목에 따라 이 조치는 차별로 보지 않는다.","c":"상","v":1},"공인노2017_26-18-3":{"w":"남녀고용평등법 제8조 제3항이 임금차별을 목적으로 설립한 별개의 사업을 동일한 사업으로 본다.","c":"상","v":1},"공인노2017_26-18-4":{"w":"남녀고용평등법 제16조가 국가·지방자치단체 및 사업주에게 모든 직업능력 개발 훈련에서 남녀에게 평등한 기회를 보장하게 한다.","c":"상","v":1},"공인노2019_28-17-1":{"w":"남녀고용평등법 제7조 제1항이 모집·채용에서 남녀 차별을 금지한다. 위반하면 제37조 제4항 제1호에 따라 500만원 이하의 벌금 대상이다.","c":"상","v":1},"공인노2019_28-17-2":{"w":"남녀고용평등법 제30조가 이 법과 관련한 분쟁해결에서 입증책임을 사업주에게 지운다. 직장 내 성희롱 분쟁도 여기에 포함된다.","c":"상","v":1},"공인노2019_28-17-4":{"w":"남녀고용평등법 제8조의 동일가치노동에 대해 판례는 직무가 다소 달라도 객관적 직무평가로 본질적으로 동일한 가치가 있으면 포함된다고 본다. 같은 조 제2항은 기술·노력·책임·작업 조건을 기준으로 든다.","c":"중","v":1},"공인노2022_31-18-2":{"w":"남녀고용평등법 제7조 제2항이 모집·채용 시 직무 수행에 필요하지 않은 용모·키·체중 등 신체적 조건과 미혼 조건의 제시·요구를 금지한다.","c":"상","v":1},"공인노2022_31-18-3":{"w":"남녀고용평등법 제8조 제3항이 임금차별을 목적으로 설립한 별개의 사업을 동일한 사업으로 본다.","c":"상","v":1},"공인노2022_31-18-4":{"w":"남녀고용평등법 제14조 제1항이 누구든지 직장 내 성희롱 발생 사실을 알면 해당 사업주에게 신고할 수 있게 한다.","c":"상","v":1},"공인노2022_31-18-5":{"w":"남녀고용평등법 제2조 제3호의 적극적 고용개선조치 정의다.","c":"상","v":1},"공인노2024_33-23-2":{"w":"남녀고용평등법 제8조 제2항이 동일 가치 노동의 기준을 정할 때 노사협의회의 근로자위원 의견을 듣게 한다.","c":"상","v":1},"공인노2024_33-23-3":{"w":"남녀고용평등법 제22조의3 제3항이 가족돌봄 등을 위한 근로시간 단축 후 근로시간을 주당 15시간 이상 30시간 이하로 정한다. 육아기 근로시간 단축(제19조의2 제3항)은 35시간이 상한이다.","c":"상","v":1},"공인노2024_33-23-5":{"w":"남녀고용평등법 제22조의3 제1항 제3호가 55세 이상 근로자의 은퇴 준비를 근로시간 단축 사유로 정하고 제22조의4 제3항이 근로자가 명시적으로 청구하면 주 12시간 이내 연장근로를 허용한다.","c":"상","v":1},"공인노2024_33-25-1":{"w":"남녀고용평등법 제19조의3 제4항이 육아기 근로시간 단축 기간을 평균임금 산정기간에서 빼게 한다.","c":"상","v":1},"공인노2024_33-25-2":{"w":"남녀고용평등법 제19조의2 제2항이 육아기 근로시간 단축을 허용하지 않으면 그 사유를 서면으로 통보하고 육아휴직 사용 등 다른 지원 방법을 근로자와 협의하게 한다.","c":"상","v":1},"공인노2024_33-25-4":{"w":"남녀고용평등법 제19조의4 제2항이 육아기 근로시간 단축을 나누어 사용할 수 있게 한다. 1회 기간은 1개월 이상이어야 한다.","c":"상","v":1},"공인노2024_33-25-5":{"w":"남녀고용평등법 제19조의2 제6항이 단축기간이 끝나면 단축 전과 같은 업무나 같은 수준의 임금을 지급하는 직무에 복귀시키게 한다.","c":"상","v":1},"공인노2025_34-27-1":{"w":"남녀고용평등법 제2조 제1호 단서 가목이 직무의 성격상 특정 성이 불가피하게 요구되는 경우를 차별에서 제외한다.","c":"상","v":1},"공인노2025_34-27-2":{"w":"남녀고용평등법 제3조 제1항 단서와 시행령 제2조 제1항이 동거하는 친족만으로 이루어지는 사업과 가사사용인에게 법의 전부를 적용하지 않는다고 정한다.","c":"상","v":1},"공인노2025_34-27-4":{"w":"남녀고용평등법 제5조 제1항이 근로자에게 남녀가 동등하게 존중받는 직장문화 조성 노력 의무를 지운다.","c":"상","v":1},"공인노2025_34-27-5":{"w":"남녀고용평등법 제6조의2 제1항이 고용노동부장관에게 남녀고용평등과 일·가정 양립 기본계획을 5년마다 수립하게 한다.","c":"상","v":1},"공인노2025_34-28-1":{"w":"남녀고용평등법 시행령 제11조 제3항 제1호가 임신 중인 여성 근로자에게 유산·조산·사산의 위험이 있으면 휴직개시예정일 7일 전까지 육아휴직을 신청할 수 있게 한다. 일반 신청 기한은 30일 전이다.","c":"상","v":1},"공인노2025_34-28-2":{"w":"남녀고용평등법 시행령 제12조 제2항이 휴직종료예정일 연기는 한 번만 할 수 있다고 정한다.","c":"상","v":1},"공인노2025_34-28-3":{"w":"남녀고용평등법 시행령 제13조 제1항 본문이 휴직개시예정일의 7일 전까지 사유를 밝혀 육아휴직 신청을 철회할 수 있게 한다.","c":"상","v":1},"공인노2025_34-28-5":{"w":"남녀고용평등법 시행령 제14조 제2항이 영유아 사망 등의 통지를 받은 사업주에게 통지받은 날부터 30일 이내로 근무개시일을 지정해 알리게 한다.","c":"상","v":1},"공인노2025_34-29-1":{"w":"남녀고용평등법 제26조 제1항의 시정신청 주체는 '근로자'이고 제2조 제4호가 근로자를 사업주에게 고용된 사람과 취업할 의사를 가진 사람으로 정의한다.","c":"상","v":1},"공인노2025_34-29-3":{"w":"남녀고용평등법 제29조 제1항이 노동위원회가 차별적 처우등에 해당한다고 판정하면 사업주에게 시정명령을 하게 한다.","c":"상","v":1},"공인노2025_34-29-4":{"w":"남녀고용평등법 제29조의4 제1항이 고용노동부장관은 확정된 시정명령의 이행상황 제출을 사업주에게 요구할 수 있게 한다.","c":"상","v":1},"공인노2025_34-29-5":{"w":"남녀고용평등법 제26조 제1항 제3호가 성희롱 신고자 등에 대한 불리한 처우(제14조 제6항 위반)를 시정신청 대상인 차별적 처우등에 넣는다.","c":"상","v":1},"공인노2026_35-32-2":{"w":"남녀고용평등법 제5조 제1항이 근로자에게 남녀가 동등하게 존중받는 직장문화 조성 노력 의무를 지운다.","c":"상","v":1},"공인노2026_35-32-3":{"w":"남녀고용평등법 제2조 제3호의 적극적 고용개선조치 정의다.","c":"상","v":1},"공인노2026_35-32-4":{"w":"남녀고용평등법 시행령 제2조 제1항이 동거하는 친족만으로 이루어지는 사업과 가사사용인에 대하여는 법의 전부를 적용하지 않는다고 정한다.","c":"상","v":1},"공인노2026_35-32-5":{"w":"남녀고용평등법 제6조의2 제1항이 고용노동부장관에게 기본계획을 5년마다 수립하게 한다.","c":"상","v":1},"공인노2017_26-19-1":{"w":"파견법 제6조 제3항이 고령자고용법상 고령자(55세 이상)인 파견근로자는 2년을 초과하여 근로자파견기간을 연장할 수 있게 한다. 60세는 고령자에 해당한다.","c":"상","v":1},"공인노2019_28-20-1":{"w":"기간제법 제9조 제1항이 차별적 처우가 있은 날(계속되는 차별은 종료일)부터 6개월이 지나기 전에 노동위원회에 시정을 신청하게 한다.","c":"상","v":1},"공인노2019_28-20-2":{"w":"기간제법 제9조 제2항이 시정신청을 할 때 차별적 처우의 내용을 구체적으로 명시하게 한다.","c":"상","v":1},"공인노2019_28-20-3":{"w":"기간제법 제11조 제1항이 노동위원회는 심문 과정에서 관계당사자 쌍방 또는 일방의 신청이나 직권으로 조정절차를 개시할 수 있다고 정한다.","c":"상","v":1},"공인노2019_28-20-4":{"w":"기간제법 제13조 제2항 단서가 명백한 고의나 반복된 차별적 처우에는 손해액을 기준으로 3배를 넘지 않는 범위에서 배상을 명할 수 있게 한다.","c":"상","v":1},"공인노2022_31-14-1":{"w":"파견법 제16조 제1항이 쟁의행위 중인 사업장에 그 쟁의행위로 중단된 업무를 위한 근로자 파견을 금지한다.","c":"상","v":1},"공인노2022_31-14-2":{"w":"파견법 제25조 제2항이 고용관계 종료 후 사용사업주가 파견근로자를 고용하는 것을 정당한 이유 없이 금지하는 근로자파견계약을 금지한다.","c":"상","v":1},"공인노2022_31-14-4":{"w":"파견법 제11조 제2항이 폐지신고가 있으면 근로자파견사업 허가는 신고일부터 효력을 잃는다고 정한다.","c":"상","v":1},"공인노2022_31-14-5":{"w":"파견법 제10조 제1항이 근로자파견사업 허가의 유효기간을 3년으로 정한다.","c":"상","v":1},"공인노2022_31-15-2":{"w":"기간제법 제4조 제1항 제2호가 휴직·파견 등으로 결원이 생겨 그 근로자가 복귀할 때까지 업무를 대신할 필요가 있는 경우를 2년 초과 사용 가능 사유로 정한다.","c":"상","v":1},"공인노2024_33-19-1":{"w":"파견법 제16조 제1항이 쟁의행위 중인 사업장에 그 쟁의행위로 중단된 업무를 위한 근로자 파견을 금지한다.","c":"상","v":1},"공인노2024_33-19-2":{"w":"파견법 제15조(명의대여의 금지)가 파견사업주가 자기 명의로 타인에게 근로자파견사업을 하게 하는 것을 금지한다.","c":"상","v":1},"공인노2024_33-19-3":{"w":"파견법 제14조 제3호가 결혼중개업의 관리에 관한 법률 제2조 제2호의 결혼중개업을 하는 자의 근로자파견사업을 금지한다(겸업 금지).","c":"상","v":1},"공인노2024_33-19-4":{"w":"파견법 제7조 제1항이 근로자파견사업을 하려는 자에게 고용노동부장관의 허가를 받게 한다.","c":"상","v":1},"공인노2024_33-21-1":{"w":"판례는 노동위원회가 신청인이 주장한 비교대상 근로자와 동일성이 인정되는 범위에서 조사·심리를 거쳐 적합한 근로자를 비교대상 근로자로 선정할 수 있다고 본다. 신청인이 지목한 근로자에 묶이지 않는다.","c":"중","v":1},"공인노2024_33-21-2":{"w":"기간제법 제9조 제2항이 시정신청을 할 때 차별적 처우의 내용을 구체적으로 명시하게 한다.","c":"상","v":1},"공인노2024_33-21-4":{"w":"기간제법 제15조의2 제1항이 고용노동부장관은 사용자가 차별적 처우를 한 경우 그 시정을 요구할 수 있다고 정한다.","c":"상","v":1},"공인노2024_33-21-5":{"w":"기간제법 제13조 제2항 단서가 명백한 고의나 반복된 차별적 처우에는 손해액의 3배를 넘지 않는 범위에서 배상을 명할 수 있게 한다.","c":"상","v":1},"공인노2025_34-18-1":{"w":"파견법 제34조 제1항 단서가 근로기준법 제55조(휴일)를 적용할 때 사용사업주를 사용자로 본다. 유급휴일 임금은 같은 조 제3항에 따라 파견사업주가 지급한다.","c":"상","v":1},"공인노2025_34-18-2":{"w":"파견법 제34조 제1항 단서가 근로기준법 제60조(연차 유급휴가)를 적용할 때 파견사업주를 사용자로 본다.","c":"상","v":1},"공인노2025_34-18-3":{"w":"파견법 제34조 제1항 단서가 근로기준법 제75조(육아 시간)를 적용할 때 사용사업주를 사용자로 본다.","c":"상","v":1},"공인노2025_34-18-4":{"w":"파견법 제34조 제1항 단서가 근로기준법 제15조부터 제36조까지를 적용할 때 파견사업주를 사용자로 본다. 위약 예정의 금지(제20조)는 이 범위에 든다.","c":"상","v":1},"공인노2025_34-19-1":{"w":"파견법 제26조 제2항이 파견근로자는 파견사업주에게 근로자파견의 대가 내역 제시를 요구할 수 있다고 정한다.","c":"상","v":1},"공인노2025_34-19-2":{"w":"파견법 제25조 제2항이 고용관계 종료 후 사용사업주의 파견근로자 고용을 정당한 이유 없이 금지하는 근로자파견계약을 금지한다.","c":"상","v":1},"공인노2025_34-19-4":{"w":"파견법 제26조 제1항이 근로자파견 전에 제20조 제1항 각 호의 사항 등을 파견근로자에게 서면으로 알리게 하고 제20조 제1항 제1호가 파견근로자의 수다.","c":"상","v":1},"공인노2025_34-19-5":{"w":"파견법 제27조가 근로자파견 시 파견근로자의 성명 등 고용노동부령으로 정하는 사항을 사용사업주에게 통지하게 한다.","c":"상","v":1},"공인노2025_34-20-2":{"w":"기간제법 제11조 제1항이 조정 신청은 시정신청을 한 날부터 14일 이내에 하되 노동위원회의 승낙이 있으면 14일 후에도 할 수 있게 한다.","c":"상","v":1},"공인노2025_34-22-2":{"w":"기간제법 제17조 제6호가 서면 명시 사항으로 근로일 및 근로일별 근로시간을 두면서 단시간근로자에 한정한다.","c":"상","v":1},"공인노2025_34-22-3":{"w":"기간제법 제6조 제1항이 단시간근로자의 동의를 얻어 소정근로시간을 초과하여 근로하게 하는 경우에도 1주 12시간을 넘지 못하게 한다.","c":"상","v":1},"공인노2025_34-22-4":{"w":"판례는 기간제법 제8조 제1항의 '기간제근로자임을 이유로 한 불리한 처우'를 비교대상 근로자와 달리 기간제근로자만 가질 수 있는 속성을 원인으로 하는 경우라고 본다.","c":"중","v":1},"공인노2025_34-22-5":{"w":"기간제법 제7조 제2항이 가사·학업 그 밖의 이유로 근로자가 단시간근로를 신청하면 단시간근로자로 전환하도록 노력하게 한다.","c":"상","v":1},"공인노2026_35-22-1":{"w":"파견법 제27조가 근로자파견 시 파견근로자의 성명 등 고용노동부령으로 정하는 사항을 사용사업주에게 통지하게 한다.","c":"상","v":1},"공인노2026_35-22-2":{"w":"파견법 제24조 제2항이 파견근로자로 고용하지 않은 사람을 파견 대상으로 하려면 미리 서면으로 그 취지를 알리고 동의를 받게 한다.","c":"상","v":1},"공인노2026_35-22-3":{"w":"파견법 제18조(사업보고)가 파견사업주에게 고용노동부령에 따라 사업보고서를 작성해 고용노동부장관에게 제출하게 한다.","c":"상","v":1},"공인노2026_35-22-4":{"w":"파견법 제25조 제1항이 파견근로자와 고용관계 종료 후 사용사업주에게 고용되는 것을 정당한 이유 없이 금지하는 근로계약을 금지한다.","c":"상","v":1},"공인노2026_35-23-1":{"w":"파견법 제13조 제1항이 허가취소나 영업정지 처분을 받은 파견사업주도 처분 전에 파견한 근로자와 사용사업주에 대해서는 파견기간이 끝날 때까지 파견사업주로서의 의무와 권리를 가진다고 정한다.","c":"상","v":1},"공인노2026_35-23-2":{"w":"파견법 제8조가 허가 결격사유로 피성년후견인을 두고 같은 조 제6호가 임원 중 결격사유에 해당하는 사람이 있는 법인도 허가를 받을 수 없게 한다.","c":"상","v":1},"공인노2026_35-23-3":{"w":"파견법 제6조의2 제4항이 사용사업주가 파견근로자를 쓰고 있는 업무에 근로자를 직접 고용하려면 해당 파견근로자를 우선 고용하도록 노력하게 한다.","c":"상","v":1},"공인노2026_35-23-5":{"w":"파견법 제10조 제1항이 허가 유효기간을 3년으로, 제3항이 갱신허가 유효기간을 종전 허가 유효기간 만료일 다음 날부터 3년으로 정한다.","c":"상","v":1},"공인노2017_26-16-1":{"w":"산업안전보건법 제24조 제2항 제4호가 그 밖에 해당 사업장 근로자의 안전·보건을 유지·증진시키기 위하여 필요한 사항을 산업안전보건위원회의 심의·의결 사항으로 정한다.","c":"중","v":1},"공인노2017_26-16-2":{"w":"산업안전보건법 제15조 제1항이 사업주는 사업장을 실질적으로 총괄하여 관리하는 사람(안전보건관리책임자)에게 안전보건 업무를 총괄 관리하게 하도록 정한다.","c":"상","v":1},"공인노2017_26-16-3":{"w":"산업안전보건법 제132조 제1항이 건강진단을 실시할 때 근로자대표가 요구하면 근로자대표를 참석시키게 한다.","c":"상","v":1},"공인노2017_26-16-4":{"w":"산업안전보건법 제2조 제2호와 시행규칙 제3조 제1호가 사망자가 1명 이상 발생한 재해를 중대재해로 정한다.","c":"상","v":1},"공인노2019_28-15-2":{"w":"산업안전보건법 제25조 제1항이 안전보건교육 등에 관한 사항을 담은 안전보건관리규정을 작성해 각 사업장에 게시하거나 갖춰 두고 근로자에게 알리게 한다.","c":"상","v":1},"공인노2019_28-15-3":{"w":"산업안전보건법 제132조 제1항이 건강진단을 실시할 때 근로자대표가 요구하면 근로자대표를 참석시키게 한다.","c":"상","v":1},"공인노2019_28-15-4":{"w":"산업안전보건법 제41조 제2항이 고객 등 제3자의 폭언등으로 근로자에게 건강장해가 발생하거나 발생할 현저한 우려가 있으면 업무의 일시적 중단·전환 등 대통령령으로 정하는 조치를 하게 한다.","c":"상","v":1},"공인노2019_28-15-5":{"w":"산업안전보건법 제26조 단서가 산업안전보건위원회가 없는 사업장은 안전보건관리규정 작성·변경 시 근로자대표의 동의를 받게 한다.","c":"상","v":1},"공인노2022_31-16-2":{"w":"산업안전보건법 제38조 제1항 제3호가 전기·열 그 밖의 에너지에 의한 위험으로 인한 산업재해 예방 조치를 사업주에게 요구한다.","c":"상","v":1},"공인노2022_31-16-3":{"w":"산업안전보건법 제51조(사업주의 작업중지)의 내용이다. 근로자도 제52조에 따라 급박한 위험이 있으면 작업을 중지하고 대피할 수 있다.","c":"상","v":1},"공인노2022_31-16-4":{"w":"산업안전보건법 제61조(적격 수급인 선정 의무)가 산업재해 예방 조치를 할 능력을 갖춘 사업주에게 도급하게 한다.","c":"상","v":1},"공인노2022_31-16-5":{"w":"산업안전보건법 제34조가 이 법과 명령의 요지 및 안전보건관리규정을 근로자가 쉽게 볼 수 있는 장소에 게시하거나 갖추어 두게 한다.","c":"상","v":1},"공인노2024_33-26-2":{"w":"산업안전보건법 제25조 제3항과 시행규칙 제25조 제1항 [별표 2]가 보험업은 상시근로자 300명 이상이면 안전보건관리규정을 작성하게 한다.","c":"중","v":1},"공인노2024_33-26-3":{"w":"산업안전보건법 제26조 단서가 산업안전보건위원회가 없는 사업장은 안전보건관리규정 작성·변경 시 근로자대표의 동의를 받게 한다.","c":"상","v":1},"공인노2024_33-26-4":{"w":"산업안전보건법 제27조가 사업주와 근로자 모두 안전보건관리규정을 지키게 한다.","c":"상","v":1},"공인노2024_33-26-5":{"w":"산업안전보건법 제25조 제1항 제4호가 사고 조사 및 대책 수립에 관한 사항을 안전보건관리규정의 포함 사항으로 정한다.","c":"상","v":1},"공인노2024_33-27-1":{"w":"산업안전보건법 제2조 제1호의 산업재해 정의다. 근로자가 아니라 '노무를 제공하는 사람'으로 넓게 정했다.","c":"상","v":1},"공인노2024_33-27-3":{"w":"산업안전보건법 제2조 제9호의 관계수급인 정의다.","c":"상","v":1},"공인노2024_33-27-4":{"w":"산업안전보건법 제2조 제10호의 건설공사발주자 정의다. 시공을 주도해 총괄·관리하는 자와 하도급하는 자는 빠진다.","c":"상","v":1},"공인노2024_33-27-5":{"w":"산업안전보건법 제2조 제7호의 도급인 정의다. 건설공사발주자는 단서로 제외된다.","c":"상","v":1},"공인노2024_33-28-2":{"w":"산업안전보건법 제125조 제2항이 도급인의 사업장에서 관계수급인의 근로자가 작업하는 경우 도급인이 자격을 가진 자로 하여금 작업환경측정을 하게 한다.","c":"상","v":1},"공인노2024_33-28-3":{"w":"산업안전보건법 제125조 제4항이 근로자대표(관계수급인의 근로자대표 포함)가 요구하면 작업환경측정 시 참석시키게 한다.","c":"상","v":1},"공인노2024_33-28-4":{"w":"산업안전보건법 제132조 제1항이 건강진단 실시 때 근로자대표가 요구하면 참석시키게 한다.","c":"상","v":1},"공인노2024_33-28-5":{"w":"산업안전보건법 제128조의2 제1항이 관계수급인의 근로자를 포함한 근로자가 이용할 휴게시설을 갖추게 한다.","c":"상","v":1},"공인노2025_34-24-1":{"w":"산업안전보건법 제36조 제5항과 시행규칙 제37조의4 제2항이 위험성평가 결과 기록 자료를 3년간 보존하게 한다.","c":"상","v":1},"공인노2025_34-24-2":{"w":"산업안전보건법 시행규칙 제37조의4 제1항 제3호와 제37조의3 제2호가 위험성평가 결과를 기록할 때 위험성 수준 결정 결과를 포함하게 한다.","c":"상","v":1},"공인노2025_34-24-3":{"w":"산업안전보건법 제36조 제2항이 위험성평가에 해당 사업장의 근로자를 참여시키게 한다. 2026. 8. 1. 시행 개정으로 참여 방법은 고시가 아니라 고용노동부령(시행규칙 제37조의2)이 정하고 근로자대표가 요구하면 근로자대표도 참여시켜야 한다(같은 조 제3항).","c":"중","v":1},"공인노2025_34-24-5":{"w":"산업안전보건법 제36조 제1항이 건설물 등으로 인한 유해·위험 요인을 찾아 위험성의 크기가 허용 가능한 수준인지 결정하고 개선대책을 세워 이행하게 한다.","c":"상","v":1},"공인노2026_35-20-1":{"w":"산업안전보건법 제125조 제3항이 작업환경측정을 작업환경측정기관에 위탁할 수 있고 필요하면 시료 분석만 위탁할 수 있게 한다.","c":"상","v":1},"공인노2026_35-20-2":{"w":"산업안전보건법 제125조 제4항이 근로자대표가 요구하면 작업환경측정 시 근로자대표를 참석시키게 한다.","c":"상","v":1},"공인노2026_35-20-3":{"w":"산업안전보건법 제105조 제1항이 고용노동부장관은 유해인자의 유해성·위험성을 평가하고 그 결과를 관보 등에 공표할 수 있다고 정한다.","c":"상","v":1},"공인노2026_35-20-5":{"w":"산업안전보건법 제137조 제2항이 건강관리카드를 제출하면 요양급여 신청 시 의학적 소견 서류 제출을 대신할 수 있게 한다.","c":"상","v":1},"공인노2026_35-21-1":{"w":"산업안전보건법 제145조 제1항이 지도사가 직무를 수행하려면 고용노동부장관에게 등록하게 한다.","c":"상","v":1},"공인노2026_35-21-2":{"w":"산업안전보건법 제148조 제1항이 지도사가 고의 또는 과실로 의뢰인에게 손해를 입히면 배상책임을 지게 한다.","c":"상","v":1},"공인노2026_35-21-3":{"w":"산업안전보건법 제150조 제2항이 지도사는 직무와 관련해 작성하거나 확인한 서류에 기명·날인하거나 서명하게 한다.","c":"상","v":1},"공인노2026_35-21-5":{"w":"산업안전보건법 제154조 단서 제3호가 업무 관련 서류를 거짓으로 작성한 경우를 필요적 등록취소 사유로 정한다.","c":"상","v":1},"공인노2017_26-24-2":{"w":"근로복지기본법 제47조 제1항 제3호가 사업의 합병·분할·분할합병 등을 위한 우리사주제도 실시회사의 해산을 우리사주조합의 해산 사유로 정한다.","c":"상","v":1},"공인노2017_26-25-1":{"w":"외국인고용법 제16조(귀국에 필요한 조치)가 사용자에게 외국인근로자 귀국 전 임금 등 금품관계 청산 등 필요한 조치를 하게 한다.","c":"상","v":1},"공인노2017_26-25-3":{"w":"외국인고용법 제4조 제2항 제3호가 송출국가의 지정 및 지정취소에 관한 사항을 외국인력정책위원회의 심의·의결 사항으로 정한다.","c":"상","v":1},"공인노2017_26-25-4":{"w":"외국인고용법 제19조 제1항 제3호가 사용자의 임금체불 그 밖의 노동관계법 위반 등으로 근로계약 유지가 어렵다고 인정되면 직업안정기관의 장이 고용허가를 취소할 수 있게 한다.","c":"상","v":1},"공인노2017_26-25-5":{"w":"외국인고용법 제15조 제1항이 외국인근로자에게 귀국 비용 충당을 위한 귀국비용보험·신탁 가입 의무를 지운다. 출국만기보험·신탁(제13조)은 사용자의 의무다.","c":"상","v":1},"공인노2019_28-16-4":{"w":"직업안정법 제2조(균등처우)의 내용이다. 성별·연령·종교·신체적 조건·사회적 신분·혼인 여부를 차별 금지 사유로 든다.","c":"상","v":1},"공인노2019_28-22-2":{"w":"임금채권보장법 제7조의3 제3항이 체불 임금등과 생계비 융자금액을 고용노동부장관이 해당 근로자에게 직접 지급하게 한다.","c":"상","v":1},"공인노2019_28-22-3":{"w":"임금채권보장법 제8조 제1항이 지급한 금액의 한도에서 근로자의 미지급 임금등 청구권을 고용노동부장관이 대위한다고 정한다. 2021년 개정으로 '체당금'의 명칭이 '대지급금'으로 바뀌었다.","c":"상","v":1},"공인노2019_28-22-4":{"w":"임금채권보장법 제7조 제5항이 고용노동부령으로 정하는 기준에 해당하는 퇴직 근로자가 대지급금(종전 체당금)을 청구할 때 공인노무사의 청구서 작성·사실확인 지원을 받을 수 있게 한다.","c":"상","v":1},"공인노2019_28-22-5":{"w":"임금채권보장법 제9조 제1항이 대지급금(종전 체당금) 지급 등 임금채권보장사업 비용에 충당하기 위하여 사업주로부터 부담금을 징수하게 한다.","c":"상","v":1},"공인노2019_28-25-1":{"w":"외국인고용법 제9조 제1항이 선정한 외국인근로자를 고용하려면 고용노동부령으로 정하는 표준근로계약서를 사용하게 한다. 위반은 제32조의 과태료 대상이다.","c":"상","v":1},"공인노2019_28-25-3":{"w":"외국인고용법 제10조가 근로계약을 체결한 사용자가 외국인근로자를 대리하여 법무부장관에게 사증발급인정서를 신청할 수 있게 한다.","c":"상","v":1},"공인노2019_28-25-4":{"w":"외국인고용법 제9조 제4항이 제18조의2로 취업활동 기간이 연장되는 외국인근로자와 사용자는 연장된 기간 범위에서 근로계약을 체결할 수 있게 한다.","c":"상","v":1},"공인노2019_28-25-5":{"w":"외국인고용법 제8조 제6항이 직업안정기관이 아닌 자의 외국인근로자 선발·알선·채용 개입을 금지한다. 위반은 제29조 제1호의 처벌 대상이다.","c":"상","v":1},"공인노2022_31-17-1":{"w":"직업안정법 제8조 제3호가 구인자가 구인조건을 밝히기를 거부하는 경우를 구인신청 수리 거부 사유로 정한다.","c":"상","v":1},"공인노2022_31-17-2":{"w":"직업안정법 제12조(광역 직업소개)가 통근 가능 지역에서 알맞은 직업을 소개할 수 없으면 광범위한 지역에 걸쳐 직업소개를 할 수 있게 한다.","c":"상","v":1},"공인노2022_31-17-3":{"w":"직업안정법 제18조 제4항 제2호가 한국장애인고용공단이 장애인을 대상으로 하는 직업소개를 신고 없이 할 수 있는 무료직업소개로 정한다.","c":"상","v":1},"공인노2022_31-17-5":{"w":"직업안정법 제28조(근로자의 모집)가 광고·문서·정보통신망 등 다양한 매체로 자유롭게 근로자를 모집할 수 있게 한다.","c":"상","v":1},"공인노2022_31-21-1":{"w":"임금채권보장법 제8조 제1항이 대지급금을 지급한 고용노동부장관이 그 금액 한도에서 근로자의 미지급 임금등 청구권을 대위한다고 정한다.","c":"상","v":1},"공인노2022_31-21-2":{"w":"임금채권보장법 제7조 제2항이 대지급금 범위에 휴업수당을 넣는다. 도산대지급금은 최종 6개월분(2026. 8. 20. 시행 개정), 간이대지급금은 최종 3개월분까지이므로 최종 3개월분은 어느 경우든 범위에 든다.","c":"상","v":1},"공인노2022_31-21-4":{"w":"임금채권보장법 제11조의2 제3항이 미성년자인 근로자는 독자적으로 대지급금 지급을 청구할 수 있게 한다.","c":"상","v":1},"공인노2022_31-21-5":{"w":"임금채권보장법 제11조의2 제4항이 대지급금수급계좌의 예금에 관한 채권을 압류하지 못하게 한다.","c":"상","v":1},"공인노2022_31-22-3":{"w":"근로복지기본법 제52조 제1항이 사내근로복지기금은 법인으로 한다고 정한다.","c":"상","v":1},"공인노2022_31-23-2":{"w":"외국인고용법 제20조 제1항 제4호와 시행령 제25조 제1호가 고용허가서 발급일부터 6개월 이내에 내국인근로자를 고용조정으로 이직시킨 사용자의 외국인근로자 고용을 3년간 제한할 수 있게 한다.","c":"상","v":1},"공인노2022_31-23-3":{"w":"외국인고용법 시행령 제14조 제1항이 고용허가서를 발급받은 사용자는 발급일부터 3개월 이내에 외국인근로자와 근로계약을 체결하게 한다.","c":"상","v":1},"공인노2022_31-23-4":{"w":"외국인고용법 제18조가 외국인근로자의 취업활동 기간을 입국한 날부터 3년의 범위로 정한다. 재고용 허가 시 제18조의2에 따라 2년 미만 연장할 수 있다.","c":"상","v":1},"공인노2022_31-23-5":{"w":"외국인고용법 제6조 제1항이 외국인근로자를 고용하려는 자는 직업안정기관에 우선 내국인 구인 신청을 하게 한다.","c":"상","v":1},"공인노2024_33-29-1":{"w":"직업안정법 제18조 제1항이 국외 무료직업소개사업은 고용노동부장관에게, 국내 무료직업소개사업은 시장·군수·구청장 등에게 신고하게 한다.","c":"상","v":1},"공인노2024_33-29-2":{"w":"직업안정법 제18조 제4항 제4호가 근로복지공단이 업무상 재해를 입은 근로자를 대상으로 하는 직업소개를 신고 없이 할 수 있는 무료직업소개로 정한다.","c":"상","v":1},"공인노2024_33-29-4":{"w":"직업안정법 제21조(명의대여 등의 금지)가 유료직업소개사업 등록자의 등록증 대여와 명의 사용 허락을 금지한다.","c":"상","v":1},"공인노2024_33-29-5":{"w":"직업안정법 제21조의2가 유료직업소개사업자와 종사자가 구직자 제공을 위해 구인자로부터 선급금을 받지 못하게 한다.","c":"상","v":1},"공인노2024_33-34-2":{"w":"임금채권보장법 제3조 단서가 국가와 지방자치단체가 직접 수행하는 사업을 적용 대상에서 뺀다.","c":"상","v":1},"공인노2024_33-34-3":{"w":"임금채권보장법 제7조의2 제4항이 재직 근로자 대지급금은 하나의 사업에 근로하는 동안 1회만 지급한다고 정한다.","c":"상","v":1},"공인노2024_33-34-4":{"w":"임금채권보장법 제20조 제1항이 임금채권보장기금은 고용노동부장관이 관리·운용한다고 정한다.","c":"상","v":1},"공인노2024_33-34-5":{"w":"임금채권보장법 제7조의3 제2항이 임금등을 받지 못한 근로자(퇴직자 포함)의 신청에 따라 생계비를 융자할 수 있게 한다.","c":"상","v":1},"공인노2024_33-35-1":{"w":"임금채권보장법 제9조 제2항이 부담금을 보수총액에 1천분의 2 범위에서 위원회 심의를 거쳐 정한 부담금비율을 곱한 금액으로 정한다.","c":"상","v":1},"공인노2024_33-35-2":{"w":"임금채권보장법 제9조 제5항이 사업주의 부담금에 관하여 이 법을 다른 법률에 우선 적용한다고 정한다.","c":"상","v":1},"공인노2024_33-35-3":{"w":"임금채권보장법 제10조 제4호가 외국인근로자 출국만기보험·신탁에 가입한 사업주를 부담금 경감 대상으로 정한다.","c":"상","v":1},"공인노2024_33-35-4":{"w":"임금채권보장법 제10조 제2호가 근로기준법이나 근로자퇴직급여 보장법에 따라 퇴직금을 미리 정산해 지급한 사업주를 부담금 경감 대상으로 정한다.","c":"상","v":1},"공인노2024_33-36-1":{"w":"근로복지기본법 제6조(목적 외 사용금지)가 국가·지방자치단체가 근로복지를 위해 보조·융자한 자금을 목적사업에만 쓰게 한다.","c":"상","v":1},"공인노2024_33-36-2":{"w":"근로복지기본법 제95조의2 제1항 제1호가 근로자가 아니면서 다른 사람을 사용하지 않고 직접 노무를 제공해 대가를 얻는 사람을 대상으로 국가·지방자치단체가 근로복지사업을 실시할 수 있게 한다.","c":"상","v":1},"공인노2024_33-36-3":{"w":"근로복지기본법 제81조 제2항 단서가 선택적 복지제도에서 근로자의 직급·근속연수·부양가족 등을 고려해 합리적 기준에 따라 수혜 수준을 달리할 수 있게 한다.","c":"상","v":1},"공인노2024_33-36-5":{"w":"근로복지기본법 제35조 제3항 단서가 대의원회를 두더라도 규약의 제정과 변경은 반드시 우리사주조합원총회의 의결을 거치게 한다.","c":"상","v":1},"공인노2024_33-38-1":{"w":"외국인고용법 제8조 제6항이 직업안정기관이 아닌 자의 외국인근로자 선발·알선·채용 개입을 금지한다.","c":"상","v":1},"공인노2024_33-38-3":{"w":"외국인고용법 제11조의2 제1항이 고용허가를 최초로 받은 사용자에게 노동관계법령·인권 등에 관한 사용자 교육을 받게 한다.","c":"상","v":1},"공인노2024_33-38-4":{"w":"외국인고용법 제11조 제1항과 시행규칙 제10조가 외국인근로자는 입국 후 15일 이내에 외국인 취업교육을 받게 한다.","c":"상","v":1},"공인노2024_33-38-5":{"w":"외국인고용법 시행령 제17조 제1항이 표준근로계약서로 체결한 근로계약의 효력발생 시기를 외국인근로자가 입국한 날로 정한다.","c":"상","v":1},"공인노2025_34-26-2":{"w":"직업안정법 제26조 제2호가 직업소개사업자(법인 임원 포함)와 종사자는 공중위생관리법의 숙박업을 경영할 수 없다고 정한다(겸업 금지).","c":"상","v":1},"공인노2025_34-26-3":{"w":"직업안정법 제2조의2 제7호 단서가 파견법의 근로자파견사업을 근로자공급사업에서 뺀다.","c":"상","v":1},"공인노2025_34-26-4":{"w":"직업안정법 제8조 본문이 구인신청 수리 거부를 금지하고 제1호가 신청 내용이 법령을 위반한 경우를 예외로 둔다.","c":"상","v":1},"공인노2025_34-26-5":{"w":"직업안정법 제21조의3 제1항이 무료·유료 직업소개사업자와 종사자에게 18세 미만 구직자를 소개할 때 친권자나 후견인의 취업동의서를 받게 한다.","c":"상","v":1},"공인노2025_34-35-1":{"w":"임금채권보장법 제11조의2 제4항이 대지급금수급계좌의 예금에 관한 채권을 압류하지 못하게 한다.","c":"상","v":1},"공인노2025_34-35-2":{"w":"임금채권보장법 제25조(신고)가 사업주의 이 법 위반 사실을 근로자가 근로감독관에게 신고하여 시정 조치를 요구할 수 있게 한다.","c":"상","v":1},"공인노2025_34-35-3":{"w":"임금채권보장법 제26조 제1항이 부담금 등 징수금을 징수하거나 대지급금·부담금을 반환받을 권리의 소멸시효를 3년으로 정한다.","c":"상","v":1},"공인노2025_34-35-4":{"w":"임금채권보장법 제23조의2 제6항이 임금채권보장 업무에 종사하거나 종사했던 자의 사업주·근로자 정보 누설과 목적 외 사용을 금지한다.","c":"상","v":1},"공인노2025_34-36-1":{"w":"근로복지기본법 제19조 제1항이 국가에 근로자와 가족의 의료비·혼례비·장례비 등 융자 지원 의무를 지운다.","c":"상","v":1},"공인노2025_34-36-2":{"w":"근로복지기본법 제19조 제2항이 임금을 받지 못한 근로자 등의 생계비 융자 등을 국가가 할 수 있게 한다.","c":"상","v":1},"공인노2025_34-36-3":{"w":"근로복지기본법 제20조 제1항이 근로자와 자녀의 교육기회 확대를 위한 장학금 지급·학자금 융자 등을 국가가 할 수 있게 한다.","c":"상","v":1},"공인노2025_34-36-5":{"w":"근로복지기본법 제18조가 취업이나 근무지 변경으로 이주하거나 가족과 떨어져 생활하는 근로자의 주거안정 지원을 국가가 할 수 있게 한다.","c":"상","v":1},"공인노2025_34-37-1":{"w":"외국인고용법 제22조(차별 금지)가 외국인근로자라는 이유로 한 부당한 차별 처우를 금지한다.","c":"상","v":1},"공인노2025_34-37-3":{"w":"외국인고용법 제24조 제1항이 외국인근로자 상담·교육 등을 하는 기관이나 단체에 사업비 일부를 예산 범위에서 국가가 지원할 수 있게 한다.","c":"상","v":1},"공인노2025_34-37-4":{"w":"외국인고용법 제23조 제2항이 대통령령으로 정하는 사업장에서 취업하는 외국인근로자에게 질병·사망 등에 대비한 상해보험 가입 의무를 지운다.","c":"상","v":1},"공인노2025_34-37-5":{"w":"외국인고용법 제24조의2 제1항이 직업안정기관에 노동자단체·사용자단체 등이 참여하는 외국인근로자 권익보호협의회를 둘 수 있게 한다.","c":"상","v":1},"공인노2025_34-38-1":{"w":"외국인고용법 제19조 제1항 제1호가 거짓이나 부정한 방법으로 고용허가를 받은 경우를 고용허가 취소 사유로 정한다.","c":"상","v":1},"공인노2025_34-38-2":{"w":"외국인고용법 제19조 제1항 제2호가 사용자가 입국 전에 계약한 임금 등 근로조건을 위반한 경우를 고용허가 취소 사유로 정한다.","c":"상","v":1},"공인노2025_34-38-3":{"w":"외국인고용법 제19조 제1항 제3호가 사용자의 임금체불 등으로 근로계약 유지가 어려운 경우를 고용허가 취소 사유로 정한다.","c":"상","v":1},"공인노2025_34-38-4":{"w":"외국인고용법 제19조 제2항이 고용허가가 취소된 사용자는 취소된 날부터 15일 이내에 그 외국인근로자와 근로계약을 종료하게 한다.","c":"상","v":1},"공인노2026_35-34-1":{"w":"임금채권보장법 제17조가 대지급금 지급과 체불 임금등·생계비 융자 등 임금채권보장사업에 충당하기 위해 임금채권보장기금을 설치하게 한다.","c":"상","v":1},"공인노2026_35-34-3":{"w":"임금채권보장법 제19조 제7호가 대한법률구조공단에 대한 출연을 기금 용도로 정하면서 단서에서 임금 체불 근로자 법률구조사업 지원에 한정한다.","c":"상","v":1},"공인노2026_35-34-4":{"w":"임금채권보장법 제21조가 기금의 회계연도는 정부의 회계연도에 따른다고 정한다.","c":"상","v":1},"공인노2026_35-34-5":{"w":"임금채권보장법 제18조 제2항이 기금 운용에 필요하면 기금 부담으로 금융기관이나 다른 기금 등에서 차입할 수 있게 한다.","c":"상","v":1},"공인노2026_35-35-1":{"w":"근로복지기본법 제52조 제7항이 준비위원회가 설립인가증을 받은 날부터 3주 이내에 기금법인의 설립등기를 하게 하고 기금법인은 설립등기로 성립한다.","c":"상","v":1},"공인노2026_35-35-2":{"w":"근로복지기본법 제64조 제2항이 기금법인은 자금차입을 할 수 없다고 정한다. 우리사주조합의 차입(제42조)과 다르다.","c":"상","v":1},"공인노2026_35-35-3":{"w":"근로복지기본법 제56조 제1항 제2호가 이사 및 감사의 선임과 해임을 복지기금협의회의 협의·결정 사항으로 정한다.","c":"상","v":1},"공인노2026_35-35-4":{"w":"근로복지기본법 제62조 제1항 제7호와 시행령 제46조 제2항 제1호가 근로자의 체육·문화활동 지원을 기금법인이 수익금으로 할 수 있는 사업으로 정한다.","c":"상","v":1},"공인노2026_35-38-1":{"w":"외국인고용법 제11조 제1항과 시행규칙 제10조가 외국인근로자는 입국 후 15일 이내에 한국산업인력공단이나 외국인 취업교육기관에서 취업교육을 받게 한다.","c":"상","v":1},"공인노2026_35-38-2":{"w":"외국인고용법 제11조 제2항이 사용자는 외국인근로자가 취업교육을 받을 수 있도록 하게 한다.","c":"상","v":1},"공인노2026_35-38-4":{"w":"외국인고용법 제11조의3 제2항이 외국인 취업교육기관 지정을 받으려면 전문인력·시설 등 대통령령으로 정하는 지정기준을 갖추어 고용노동부장관에게 신청하게 한다.","c":"상","v":1},"공인노2026_35-38-5":{"w":"외국인고용법 제11조의4 제2항이 지정이 취소된 외국인 취업교육기관은 취소된 날부터 1년이 지나지 않으면 지정신청을 할 수 없다고 정한다.","c":"상","v":1},"공인노2026_35-40-2":{"w":"임금채권보장법 시행령 제9조 제1항 제1호가 도산대지급금은 파산선고등 또는 도산등사실인정이 있은 날부터 2년 이내에 청구하게 한다.","c":"상","v":1},"공인노2017_26-04-3":{"old":1,"ow":"출제 당시 정답 O. 2018년 개정(2018.7.1 시행)으로 금융보험업이 근로시간·휴게시간 특례업종에서 빠져, 지금은 근로자대표와 서면 합의를 해도 1주 12시간을 넘는 연장근로를 시킬 수 없으므로 틀린 문장이다(근로기준법 제59조)."},"공인노2019_28-17-5":{"old":1,"ow":"출제 당시 정답 O. 2025.2.23 시행 개정으로 배우자 출산휴가는 20일이고 전부 유급이며 출산일부터 120일 안에 청구해야 하므로 '5일 범위에서 3일 이상, 최초 3일 유급'은 틀린 문장이다(남녀고용평등법 제18조의2)."},"공인노2024_33-23-4":{"old":1,"ow":"출제 당시 정답 O. 2025.2.23 시행 개정으로 난임치료휴가는 연간 6일이고 최초 2일이 유급이므로 틀린 문장이다(남녀고용평등법 제18조의3)."},"공인노2019_28-23-1":{"old":1,"ow":"출제 당시 정답 O. 2021년 개정(2022.4.14 시행)으로 중소기업퇴직연금기금제도가 퇴직급여제도에 들어가, 지금은 확정급여형·확정기여형 퇴직연금제도, 중소기업퇴직연금기금제도, 퇴직금제도를 말하므로 셋만 든 이 정의는 틀린 문장이다(근로자퇴직급여 보장법 제2조제6호)."},"공인노2025_34-10-5":{"old":1,"ow":"출제 당시 정답 O. 근로기준법 제105조가 2026. 8. 4. 개정되어 '검사와'가 빠졌다. 2026-10-14 시행 중인 조문은 현장조사·서류 제출·심문 등의 수사를 근로감독관이 전담하고 근로감독관의 직무에 관한 범죄 수사만 예외로 둔다."}};
